import java.util.Optional;

import org.opentron.backend.security.confidential.gateway.SecureContextKey;
import org.opentron.backend.security.confidential.gateway.SecureContextKeyProvider;

public final class AwsNitroAttestedSecureContextKeyProvider implements SecureContextKeyProvider {
    private final AwsNitroEnclaveKeyReleaseService keyReleaseService;
    private final String contextKeyId;

    public AwsNitroAttestedSecureContextKeyProvider(
            AwsNitroEnclaveKeyReleaseService keyReleaseService,
            String contextKeyId) {
        if (keyReleaseService == null
                || contextKeyId == null
                || !contextKeyId.matches("[A-Za-z0-9_-]{1,64}")) {
            throw new IllegalArgumentException("AWS Nitro key release configuration is invalid.");
        }
        if (!keyReleaseService.contextKeyId().equals(contextKeyId)) {
            throw new IllegalArgumentException("Context key identifier does not match key release.");
        }
        this.keyReleaseService = keyReleaseService;
        this.contextKeyId = contextKeyId;
    }

    @Override
    public SecureContextKey currentKey() {
        return keyReleaseService.releaseContextKey();
    }

    @Override
    public Optional<SecureContextKey> findKey(String id) {
        if (!contextKeyId.equals(id)) {
            return Optional.empty();
        }
        return Optional.of(keyReleaseService.releaseContextKey());
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import java.security.SecureRandom;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.opentron.backend.security.confidential.ConfidentialRuntimeVerifier;
import org.opentron.backend.security.confidential.gateway.SecureContextKeyProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;

/**
 * Wires enclave-side AWS Nitro key release. The default NSM source uses Panama
 * FFM directly against /dev/nsm; deployments must provide a trusted parent KMS proxy.
 * The separately guarded OIDC gateway module owns any HTTP request surface.
 */
@Configuration(proxyBeanMethods = false)
@Profile("aws-nitro & !gcp-cvm & !local-untrusted")
public class AwsNitroConfidentialGatewayConfiguration {
    @Bean
    @ConditionalOnMissingBean(AwsNitroEnclaveAttestationSource.class)
    public AwsNitroEnclaveAttestationSource awsNitroEnclaveAttestationSource() {
        return new PanamaNitroEnclaveAttestationSource();
    }

    @Bean
    @ConditionalOnMissingBean(ParentVsockKmsTransport.class)
    public ParentVsockKmsTransport parentVsockKmsTransport(
            @Value("${confidential.aws.nitro.vsock.parent-cid:3}") int parentCid,
            @Value("${confidential.aws.nitro.vsock.proxy-port:8000}") int proxyPort) {
        return new LinuxVsockParentKmsTransport(
                parentCid, proxyPort, new ObjectMapper());
    }

    @Bean
    public AwsNitroEnclaveKeyReleaseService awsNitroEnclaveKeyReleaseService(
            AwsNitroEnclaveAttestationSource attestationSource,
            ParentVsockKmsTransport kmsTransport,
            @Value("${confidential.aws.nitro.kms.key-id}") String kmsKeyId,
            @Value("${confidential.aws.nitro.kms.ciphertext-blob-base64}")
                    String encodedCiphertext,
            @Value("${confidential.aws.nitro.kms.context-key-id}") String contextKeyId) {
        byte[] ciphertext;
        try {
            ciphertext = Base64.getDecoder().decode(encodedCiphertext);
        } catch (IllegalArgumentException e) {
            throw new IllegalStateException(
                    "confidential.aws.nitro.kms.ciphertext-blob-base64 must be Base64.", e);
        }
        try {
            return new AwsNitroEnclaveKeyReleaseService(
                    attestationSource,
                    kmsTransport,
                    new SecureRandom(),
                    kmsKeyId,
                    ciphertext,
                    contextKeyId);
        } finally {
            java.util.Arrays.fill(ciphertext, (byte) 0);
        }
    }

    @Bean
    public SecureContextKeyProvider awsNitroSecureContextKeyProvider(
            AwsNitroEnclaveKeyReleaseService keyReleaseService,
            @Value("${confidential.aws.nitro.kms.context-key-id}") String contextKeyId) {
        return new AwsNitroAttestedSecureContextKeyProvider(keyReleaseService, contextKeyId);
    }

    @Bean
    public ConfidentialRuntimeVerifier awsNitroConfidentialRuntimeVerifier(
            AwsNitroEnclaveKeyReleaseService keyReleaseService) {
        return new AwsNitroConfidentialRuntimeVerifier(keyReleaseService);
    }

    @Bean
    @ConditionalOnProperty(
            prefix = "confidential.aws.nitro.kms",
            name = "policy-export-enabled",
            havingValue = "true")
    public AwsNitroKmsAttestationPolicy awsNitroKmsAttestationPolicy(
            @Value("${confidential.aws.nitro.kms.image-sha384}") String imageSha384,
            @Value("${confidential.aws.nitro.kms.required-pcrs}") String rawPcrs) {
        return new AwsNitroKmsAttestationPolicy(imageSha384, parsePcrs(rawPcrs));
    }

    private static Map<Integer, String> parsePcrs(String rawPcrs) {
        if (rawPcrs == null || rawPcrs.isBlank()) {
            throw new IllegalArgumentException(
                    "At least one confidential.aws.nitro.kms.required-pcrs entry is required.");
        }
        var pcrs = new HashMap<Integer, String>();
        for (String item : rawPcrs.split(",")) {
            String[] pair = item.trim().split("=", -1);
            if (pair.length != 2) {
                throw new IllegalArgumentException(
                        "AWS Nitro PCRs must use comma-separated index=sha384hex entries.");
            }
            try {
                int index = Integer.parseInt(pair[0]);
                if (pcrs.putIfAbsent(index, pair[1]) != null) {
                    throw new IllegalArgumentException("AWS Nitro PCR index is duplicated.");
                }
            } catch (NumberFormatException e) {
                throw new IllegalArgumentException("AWS Nitro PCR index must be an integer.", e);
            }
        }
        return Map.copyOf(pcrs);
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import java.util.Arrays;

import org.opentron.backend.security.confidential.ConfidentialRuntimeVerifier;
import org.opentron.backend.security.confidential.gateway.SecureContextKey;

/**
 * Fails closed unless a fresh NSM Recipient decrypt succeeds and its response
 * can be unwrapped within this JVM. PCR/image checks depend on corresponding
 * key-policy conditions being provisioned externally; this verifier cannot
 * inspect or attest to that remote policy configuration.
 */
public final class AwsNitroConfidentialRuntimeVerifier implements ConfidentialRuntimeVerifier {
    private final AwsNitroEnclaveKeyReleaseService keyReleaseService;

    public AwsNitroConfidentialRuntimeVerifier(
            AwsNitroEnclaveKeyReleaseService keyReleaseService) {
        if (keyReleaseService == null) {
            throw new IllegalArgumentException("AWS Nitro key release service is required.");
        }
        this.keyReleaseService = keyReleaseService;
    }

    @Override
    public void verifyCurrentRuntime() {
        SecureContextKey released = keyReleaseService.releaseContextKey();
        byte[] encodedKey = released.key().getEncoded();
        if (!keyReleaseService.contextKeyId().equals(released.id())
                || encodedKey == null
                || !"AES".equalsIgnoreCase(released.key().getAlgorithm())
                || encodedKey.length != 32) {
            if (encodedKey != null) {
                Arrays.fill(encodedKey, (byte) 0);
            }
            throw new AwsNitroEnclaveException(
                    "AWS Nitro runtime verification received an unexpected context key.");
        }
        Arrays.fill(encodedKey, (byte) 0);
    }
}package org.opentron.backend.security.confidential.gateway.aws;

/** Supplies an NSM attestation document binding its nonce and public_key claims. */
@FunctionalInterface
public interface AwsNitroEnclaveAttestationSource {
    byte[] attest(byte[] nonce, byte[] ephemeralRsaPublicKey);
}package org.opentron.backend.security.confidential.gateway.aws;

public final class AwsNitroEnclaveException extends RuntimeException {
    public AwsNitroEnclaveException(String message) {
        super(message);
    }

    public AwsNitroEnclaveException(String message, Throwable cause) {
        super(message, cause);
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import java.security.GeneralSecurityException;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.PrivateKey;
import java.security.SecureRandom;
import java.util.Arrays;
import java.util.Collection;

import javax.crypto.spec.SecretKeySpec;

import org.bouncycastle.cms.CMSException;
import org.bouncycastle.cms.CMSEnvelopedData;
import org.bouncycastle.cms.RecipientInformation;
import org.bouncycastle.cms.jcajce.JceKeyTransEnvelopedRecipient;
import org.opentron.backend.security.confidential.gateway.SecureContextKey;

/**
 * Obtains a fresh NSM document and submits a KMS Recipient Decrypt request.
 * Configured KMS key-policy conditions are the sole PCR/image enforcement
 * point; this class does not parse PCRs or provision/verify the remote policy.
 */
public final class AwsNitroEnclaveKeyReleaseService {
    private static final int NONCE_BYTES = 32;
    private static final int RSA_KEY_BITS = 2048;

    private final AwsNitroEnclaveAttestationSource attestationSource;
    private final ParentVsockKmsTransport kmsTransport;
    private final SecureRandom secureRandom;
    private final String kmsKeyId;
    private final byte[] ciphertextBlob;
    private final String contextKeyId;

    public AwsNitroEnclaveKeyReleaseService(
            AwsNitroEnclaveAttestationSource attestationSource,
            ParentVsockKmsTransport kmsTransport,
            SecureRandom secureRandom,
            String kmsKeyId,
            byte[] ciphertextBlob,
            String contextKeyId) {
        if (attestationSource == null || kmsTransport == null || secureRandom == null) {
            throw new IllegalArgumentException(
                    "NSM source, parent-vsock KMS transport, and secure random are required.");
        }
        if (kmsKeyId == null || kmsKeyId.isBlank() || kmsKeyId.length() > 2048) {
            throw new IllegalArgumentException("A bounded KMS key ID is required.");
        }
        if (ciphertextBlob == null || ciphertextBlob.length < 1
                || ciphertextBlob.length > AwsNitroKmsDecryptRequest.MAX_CIPHERTEXT_BLOB_BYTES) {
            throw new IllegalArgumentException("KMS ciphertext exceeds its size bound.");
        }
        if (contextKeyId == null || !contextKeyId.matches("[A-Za-z0-9_-]{1,64}")) {
            throw new IllegalArgumentException("Context key identifier is invalid.");
        }
        this.attestationSource = attestationSource;
        this.kmsTransport = kmsTransport;
        this.secureRandom = secureRandom;
        this.kmsKeyId = kmsKeyId;
        this.ciphertextBlob = ciphertextBlob.clone();
        this.contextKeyId = contextKeyId;
    }

    public SecureContextKey releaseContextKey() {
        byte[] unwrappedKey = releaseSecret(ciphertextBlob);
        try {
            if (unwrappedKey.length != 32) {
                throw new AwsNitroEnclaveException(
                        "KMS Recipient plaintext is not a 256-bit AES key.");
            }
            return new SecureContextKey(
                    contextKeyId, new SecretKeySpec(unwrappedKey, "AES"));
        } finally {
            clear(unwrappedKey);
        }
    }

    public byte[] releaseSecret(byte[] encryptedSecret) {
        if (encryptedSecret == null || encryptedSecret.length < 1
                || encryptedSecret.length > AwsNitroKmsDecryptRequest.MAX_CIPHERTEXT_BLOB_BYTES) {
            throw new IllegalArgumentException("KMS ciphertext exceeds its size bound.");
        }
        byte[] nonce = new byte[NONCE_BYTES];
        byte[] attestationDocument = null;
        byte[] ciphertextForRecipient = null;
        byte[] unwrappedKey = null;
        try {
            secureRandom.nextBytes(nonce);
            KeyPairGenerator generator = KeyPairGenerator.getInstance("RSA");
            generator.initialize(RSA_KEY_BITS, secureRandom);
            KeyPair recipientKeyPair = generator.generateKeyPair();
            byte[] publicKey = recipientKeyPair.getPublic().getEncoded();

            byte[] sourceNonce = nonce.clone();
            byte[] sourcePublicKey = publicKey.clone();
            try {
                attestationDocument = attestationSource.attest(sourceNonce, sourcePublicKey);
            } finally {
                Arrays.fill(sourceNonce, (byte) 0);
                Arrays.fill(sourcePublicKey, (byte) 0);
                Arrays.fill(publicKey, (byte) 0);
            }
            if (attestationDocument == null || attestationDocument.length < 1
                    || attestationDocument.length
                            > AwsNitroKmsDecryptRequest.MAX_ATTESTATION_DOCUMENT_BYTES) {
                throw new AwsNitroEnclaveException(
                        "NSM did not provide a bounded attestation document.");
            }

            AwsNitroKmsDecryptRequest request = new AwsNitroKmsDecryptRequest(
                    kmsKeyId,
                    encryptedSecret,
                    new AwsNitroKmsRecipient(
                            attestationDocument,
                            AwsNitroKmsDecryptRequest.RSAES_OAEP_SHA_256));
            AwsNitroKmsDecryptResponse response = kmsTransport.decrypt(request);
            if (response == null) {
                throw new AwsNitroEnclaveException("KMS Recipient response is missing.");
            }
            ciphertextForRecipient = response.ciphertextForRecipient();
            unwrappedKey =
                    decryptCiphertextForRecipient(ciphertextForRecipient, recipientKeyPair.getPrivate());
            byte[] released = unwrappedKey;
            unwrappedKey = null;
            return released;
        } catch (AwsNitroEnclaveException e) {
            throw e;
        } catch (GeneralSecurityException | RuntimeException e) {
            throw new AwsNitroEnclaveException(
                    "AWS Nitro attested key release failed closed.", e);
        } finally {
            Arrays.fill(nonce, (byte) 0);
            clear(attestationDocument);
            clear(ciphertextForRecipient);
            clear(unwrappedKey);
        }
    }

    public String contextKeyId() {
        return contextKeyId;
    }

    static byte[] decryptCiphertextForRecipient(
            byte[] ciphertextForRecipient, PrivateKey recipientPrivateKey) {
        try {
            CMSEnvelopedData envelope = new CMSEnvelopedData(ciphertextForRecipient);
            Collection<RecipientInformation> recipients =
                    envelope.getRecipientInfos().getRecipients();
            if (recipients.size() != 1) {
                throw new AwsNitroEnclaveException(
                        "AWS KMS Recipient envelope must contain exactly one recipient.");
            }
            return recipients.iterator()
                    .next()
                    .getContent(new JceKeyTransEnvelopedRecipient(recipientPrivateKey));
        } catch (CMSException exception) {
            throw new AwsNitroEnclaveException(
                    "AWS KMS Recipient CMS envelope could not be decrypted.", exception);
        }
    }

    private static void clear(byte[] bytes) {
        if (bytes != null) {
            Arrays.fill(bytes, (byte) 0);
        }
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import java.net.InetAddress;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.ssl.SslBundle;
import org.springframework.boot.ssl.SslBundleKey;
import org.springframework.boot.ssl.SslBundles;
import org.springframework.boot.ssl.SslOptions;
import org.springframework.boot.ssl.SslStoreBundle;
import org.springframework.boot.ssl.NoSuchSslBundleException;
import org.springframework.boot.web.server.Ssl;
import org.springframework.boot.web.servlet.server.ConfigurableServletWebServerFactory;
import org.springframework.boot.web.server.WebServerFactoryCustomizer;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;

@Configuration(proxyBeanMethods = false)
@Profile("aws-nitro & gateway-oidc & !gcp-cvm")
@ConditionalOnProperty(name = "confidential.gateway.enabled", havingValue = "true")
public class AwsNitroGatewayTlsConfiguration {
    private static final String SSL_BUNDLE_NAME = "cjae-nitro-gateway";

    @Bean
    public AwsNitroTlsKeyStoreProvider awsNitroTlsKeyStoreProvider(
            AwsNitroEnclaveKeyReleaseService keyReleaseService,
            @Value("${confidential.aws.nitro.tls.keystore-ciphertext-base64}")
                    String encryptedKeyStore) {
        return new AwsNitroTlsKeyStoreProvider(keyReleaseService, encryptedKeyStore);
    }

    @Bean
    public SslBundle awsNitroGatewaySslBundle(
            AwsNitroTlsKeyStoreProvider keyStoreProvider) {
        SslStoreBundle stores =
                SslStoreBundle.of(keyStoreProvider.getKeyStore(), "", null);
        SslOptions options = SslOptions.of(
                new String[0], new String[] {"TLSv1.3", "TLSv1.2"});
        return SslBundle.of(stores, SslBundleKey.of(""), options);
    }

    @Bean
    public WebServerFactoryCustomizer<ConfigurableServletWebServerFactory>
            awsNitroGatewayTlsCustomizer(
                    SslBundle awsNitroGatewaySslBundle,
                    @Value("${confidential.aws.nitro.gateway.tls-port:8443}") int tlsPort) {
        if (tlsPort < 1 || tlsPort > 65535) {
            throw new IllegalStateException("AWS Nitro gateway TLS port is invalid.");
        }
        return factory -> {
            SslBundles bundles = name -> {
                if (!SSL_BUNDLE_NAME.equals(name)) {
                    throw new NoSuchSslBundleException(
                            name, "Only the configured CJAE TLS bundle is available.");
                }
                return awsNitroGatewaySslBundle;
            };
            factory.setSslBundles(bundles);
            Ssl ssl = Ssl.forBundle(SSL_BUNDLE_NAME);
            ssl.setEnabled(true);
            factory.setSsl(ssl);
            factory.setPort(tlsPort);
            factory.setAddress(InetAddress.getLoopbackAddress());
        };
    }
}package org.opentron.backend.security.confidential.gateway.aws;

