import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.regex.Pattern;

/**
 * Values for KMS key-policy StringEquals conditions. PCR/image enforcement
 * occurs only if these conditions are installed in the applicable AWS KMS key
 * policy; this descriptor does not provision or verify that policy.
 */
public final class AwsNitroKmsAttestationPolicy {
    public static final String IMAGE_SHA384_CONDITION =
            "kms:RecipientAttestation:ImageSha384";
    private static final Pattern SHA384_HEX = Pattern.compile("[0-9a-fA-F]{96}");

    private final Map<String, String> stringEqualsConditions;

    public AwsNitroKmsAttestationPolicy(String imageSha384, Map<Integer, String> pcrs) {
        requireSha384(imageSha384, "ImageSha384");
        Objects.requireNonNull(pcrs, "PCR requirements are required.");
        if (pcrs.isEmpty()) {
            throw new IllegalArgumentException("At least one PCR policy requirement is required.");
        }
        for (Map.Entry<Integer, String> entry : pcrs.entrySet()) {
            Integer index = entry.getKey();
            if (index == null || index < 0 || index > 8) {
                throw new IllegalArgumentException("Nitro PCR index must be between 0 and 8.");
            }
            requireSha384(entry.getValue(), "PCR" + index);
        }
        String pcr0 = pcrs.get(0);
        if (pcr0 != null && !pcr0.equalsIgnoreCase(imageSha384)) {
            throw new IllegalArgumentException(
                    "ImageSha384 and PCR0 must express the same AWS image measurement.");
        }

        Map<String, String> conditions = new LinkedHashMap<>();
        conditions.put(IMAGE_SHA384_CONDITION, imageSha384.toLowerCase(Locale.ROOT));
        pcrs.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(entry -> {
            Integer index = entry.getKey();
            conditions.put(
                    "kms:RecipientAttestation:PCR" + index,
                    entry.getValue().toLowerCase(Locale.ROOT));
        });
        this.stringEqualsConditions = Map.copyOf(conditions);
    }

    /**
     * Map to place under {@code Condition.StringEquals} in the KMS key policy
     * statement granting {@code kms:Decrypt}. Applying that policy is external
     * provisioning and is not performed or verified by this adapter.
     */
    public Map<String, String> stringEqualsConditions() {
        return stringEqualsConditions;
    }

    private static void requireSha384(String value, String field) {
        if (value == null || !SHA384_HEX.matcher(value).matches()) {
            throw new IllegalArgumentException(field + " must be a 96-character SHA-384 hex value.");
        }
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import java.util.Objects;

/**
 * Bounded AWS KMS Decrypt request data, including its Recipient structure.
 */
public record AwsNitroKmsDecryptRequest(
        String keyId,
        byte[] ciphertextBlob,
        AwsNitroKmsRecipient recipient) {
    public static final int MAX_CIPHERTEXT_BLOB_BYTES = 6 * 1024;
    public static final int MAX_ATTESTATION_DOCUMENT_BYTES = 256 * 1024;
    public static final int MAX_REQUEST_BYTES = 272 * 1024;
    public static final String RSAES_OAEP_SHA_256 = "RSAES_OAEP_SHA_256";

    public AwsNitroKmsDecryptRequest {
        if (keyId == null || keyId.isBlank() || keyId.length() > 2048) {
            throw new IllegalArgumentException("A bounded KMS key ID is required.");
        }
        ciphertextBlob = copyAndRequireSize(
                ciphertextBlob, 1, MAX_CIPHERTEXT_BLOB_BYTES, "CiphertextBlob");
        Objects.requireNonNull(recipient, "KMS Recipient is required.");
        long requestBytes = (long) keyId.getBytes(java.nio.charset.StandardCharsets.UTF_8).length
                + ciphertextBlob.length + recipient.attestationDocument().length
                + recipient.keyEncryptionAlgorithm().length();
        if (requestBytes > MAX_REQUEST_BYTES) {
            throw new IllegalArgumentException("KMS Decrypt request exceeds its size bound.");
        }
    }

    @Override
    public byte[] ciphertextBlob() {
        return ciphertextBlob.clone();
    }

    private static byte[] copyAndRequireSize(byte[] value, int min, int max, String field) {
        Objects.requireNonNull(value, field + " is required.");
        if (value.length < min || value.length > max) {
            throw new IllegalArgumentException(field + " exceeds its size bound.");
        }
        return value.clone();
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import java.util.Objects;

/**
 * KMS Recipient response. Plaintext is deliberately not represented here:
 * only CiphertextForRecipient may cross the transport boundary.
 */
public record AwsNitroKmsDecryptResponse(byte[] ciphertextForRecipient) {
    public static final int MAX_CIPHERTEXT_FOR_RECIPIENT_BYTES = 6 * 1024;

    public AwsNitroKmsDecryptResponse {
        Objects.requireNonNull(ciphertextForRecipient, "CiphertextForRecipient is required.");
        if (ciphertextForRecipient.length < 1
                || ciphertextForRecipient.length > MAX_CIPHERTEXT_FOR_RECIPIENT_BYTES) {
            throw new IllegalArgumentException("CiphertextForRecipient exceeds its size bound.");
        }
        ciphertextForRecipient = ciphertextForRecipient.clone();
    }

    @Override
    public byte[] ciphertextForRecipient() {
        return ciphertextForRecipient.clone();
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import java.util.Objects;

/**
 * AWS KMS Decrypt {@code Recipient} parameter for an attested Nitro enclave.
 */
public record AwsNitroKmsRecipient(
        byte[] attestationDocument,
        String keyEncryptionAlgorithm) {

    public AwsNitroKmsRecipient {
        Objects.requireNonNull(attestationDocument, "AttestationDocument is required.");
        if (attestationDocument.length < 1
                || attestationDocument.length
                        > AwsNitroKmsDecryptRequest.MAX_ATTESTATION_DOCUMENT_BYTES) {
            throw new IllegalArgumentException("AttestationDocument exceeds its size bound.");
        }
        if (!AwsNitroKmsDecryptRequest.RSAES_OAEP_SHA_256.equals(keyEncryptionAlgorithm)) {
            throw new IllegalArgumentException("Unsupported KMS recipient encryption algorithm.");
        }
        attestationDocument = attestationDocument.clone();
    }

    @Override
    public byte[] attestationDocument() {
        return attestationDocument.clone();
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import java.security.SecureRandom;
import java.time.Clock;
import java.time.Duration;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.opentron.backend.security.confidential.gateway.AesGcmSecureContextCodec;
import org.opentron.backend.security.confidential.gateway.ConfidentialGatewayService;
import org.opentron.backend.security.confidential.gateway.ConfidentialOperationGovernor;
import org.opentron.backend.security.confidential.gateway.GatewayPiiDetectorConfiguration;
import org.opentron.backend.security.confidential.gateway.PiiDetector;
import org.opentron.backend.security.confidential.gateway.SecureContextKeyProvider;
import org.opentron.backend.security.confidential.gateway.SecureContextConsumptionStore;
import org.opentron.backend.security.confidential.gateway.api.ConfidentialGatewayApiKeyInterceptor;
import org.opentron.backend.security.confidential.gateway.api.ConfidentialOperationGovernorConfiguration;
import org.opentron.backend.security.confidential.gateway.api.GatewayCredentialAuthenticator;
import org.opentron.backend.security.confidential.gateway.api.GatewayQuotaService;
import org.opentron.backend.security.confidential.gateway.api.FixedWindowGatewayQuotaService;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Import;
import org.springframework.context.annotation.Profile;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

@Configuration(proxyBeanMethods = false)
@Profile("aws-nitro & gateway-oidc & !gcp-cvm")
@ConditionalOnProperty(name = "confidential.gateway.enabled", havingValue = "true")
@Import({ConfidentialOperationGovernorConfiguration.class, GatewayPiiDetectorConfiguration.class})
public class AwsNitroOidcGatewayApiConfiguration implements WebMvcConfigurer {
    private final ConfidentialGatewayApiKeyInterceptor apiKeyInterceptor;

    public AwsNitroOidcGatewayApiConfiguration(
            GatewayCredentialAuthenticator credentialAuthenticator) {
        apiKeyInterceptor = new ConfidentialGatewayApiKeyInterceptor(credentialAuthenticator);
    }

    @Bean
    public AesGcmSecureContextCodec awsNitroSecureContextCodec(
            SecureContextKeyProvider awsNitroSecureContextKeyProvider,
            ObjectMapper objectMapper) {
        return new AesGcmSecureContextCodec(
                awsNitroSecureContextKeyProvider,
                objectMapper,
                new SecureRandom(),
                Clock.systemUTC());
    }

    @Bean
    public ConfidentialGatewayService awsNitroConfidentialGatewayService(
            AesGcmSecureContextCodec awsNitroSecureContextCodec,
            ConfidentialOperationGovernor operationGovernor,
            PiiDetector piiDetector,
            SecureContextConsumptionStore contextConsumptionStore,
            @Value("${CONFIDENTIAL_GATEWAY_CONTEXT_TTL_MINUTES:5}") long ttlMinutes) {
        if (ttlMinutes <= 0 || ttlMinutes > 15) {
            throw new IllegalStateException(
                    "CONFIDENTIAL_GATEWAY_CONTEXT_TTL_MINUTES must be between 1 and 15.");
        }
        return new ConfidentialGatewayService(
                piiDetector,
                awsNitroSecureContextCodec,
                Duration.ofMinutes(ttlMinutes),
                new SecureRandom(),
                Clock.systemUTC(),
                operationGovernor,
                contextConsumptionStore);
    }

    @Bean
    public GatewayQuotaService awsNitroGatewayQuotaService(
            @Value("${CONFIDENTIAL_GATEWAY_MAX_REQUESTS_PER_MINUTE:60}")
                    int maximumRequests,
            @Value("${CONFIDENTIAL_GATEWAY_MAX_CHARACTERS_PER_MINUTE:5000000}")
                    long maximumCharacters,
            @Value("${CONFIDENTIAL_GATEWAY_MAX_TENANTS:10000}")
                    int maximumTenants) {
        return new FixedWindowGatewayQuotaService(
                maximumRequests,
                maximumCharacters,
                maximumTenants,
                Duration.ofMinutes(1),
                Clock.systemUTC());
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(apiKeyInterceptor).addPathPatterns("/v1/confidential/**");
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import java.io.ByteArrayInputStream;
import java.security.KeyStore;
import java.security.cert.X509Certificate;
import java.util.Arrays;
import java.util.Base64;

public final class AwsNitroTlsKeyStoreProvider {
    private final KeyStore keyStore;

    public AwsNitroTlsKeyStoreProvider(
            AwsNitroEnclaveKeyReleaseService keyReleaseService,
            String encryptedKeyStoreBase64) {
        if (keyReleaseService == null || encryptedKeyStoreBase64 == null
                || encryptedKeyStoreBase64.isBlank()) {
            throw new IllegalArgumentException(
                    "A KMS-encrypted TLS PKCS#12 identity is required for the AWS gateway.");
        }

        byte[] encryptedKeyStore;
        try {
            encryptedKeyStore = Base64.getDecoder().decode(encryptedKeyStoreBase64);
        } catch (IllegalArgumentException exception) {
            throw new IllegalStateException(
                    "AWS Nitro TLS identity must be valid Base64 KMS ciphertext.", exception);
        }

        byte[] keyStoreBytes = null;
        try {
            keyStoreBytes = keyReleaseService.releaseSecret(encryptedKeyStore);
            if (keyStoreBytes.length > 4096) {
                throw new IllegalStateException(
                        "KMS-released AWS Nitro TLS identity exceeds 4 KiB.");
            }
            KeyStore loaded = KeyStore.getInstance("PKCS12");
            loaded.load(new ByteArrayInputStream(keyStoreBytes), new char[0]);
            boolean hasPrivateKey = java.util.Collections.list(loaded.aliases()).stream()
                    .anyMatch(alias -> {
                        try {
                            if (!loaded.isKeyEntry(alias)
                                    || loaded.getKey(alias, new char[0]) == null
                                    || !(loaded.getCertificate(alias)
                                            instanceof X509Certificate certificate)) {
                                return false;
                            }
                            certificate.checkValidity();
                            return true;
                        } catch (Exception exception) {
                            throw new IllegalStateException(
                                    "AWS Nitro TLS identity contains an unreadable private key.",
                                    exception);
                        }
                    });
            if (!hasPrivateKey) {
                throw new IllegalStateException(
                        "AWS Nitro TLS identity has no passwordless PKCS#12 private key.");
            }
            keyStore = loaded;
        } catch (Exception exception) {
            throw new IllegalStateException(
                    "Unable to load the KMS-released AWS Nitro TLS identity.", exception);
        } finally {
            Arrays.fill(encryptedKeyStore, (byte) 0);
            if (keyStoreBytes != null) {
                Arrays.fill(keyStoreBytes, (byte) 0);
            }
        }
    }

    public KeyStore getKeyStore() {
        return keyStore;
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import java.io.IOException;
import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.Linker;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.SymbolLookup;
import java.lang.foreign.ValueLayout;
import java.lang.invoke.MethodHandle;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Objects;
import java.util.concurrent.Semaphore;

public final class LinuxVsockHealthBridge implements AutoCloseable {
    private static final System.Logger LOGGER =
            System.getLogger(LinuxVsockHealthBridge.class.getName());
    private static final int AF_VSOCK = 40;
    private static final int SOCK_STREAM = 1;
    private static final int VMADDR_CID_ANY = -1;
    private static final int SHUT_RDWR = 2;
    private static final int SOCKET_ADDRESS_SIZE = 16;
    private static final int MAX_REQUEST_LINE_BYTES = 1024;
    private static final int MAX_RESPONSE_BYTES = 65536;
    private static final int MAX_CLIENTS = 8;
    private static final byte[] BUSY_RESPONSE = httpResponse(
            503, "{\"status\":\"unavailable\"}".getBytes(StandardCharsets.UTF_8));
    private static final byte[] BAD_REQUEST_RESPONSE = httpResponse(
            400, "{\"status\":\"bad_request\"}".getBytes(StandardCharsets.UTF_8));
    private static final Linker LINKER = Linker.nativeLinker();
    private static final FunctionDescriptor SOCKET_DESCRIPTOR = FunctionDescriptor.of(
            ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT);
    private static final FunctionDescriptor BIND_DESCRIPTOR = FunctionDescriptor.of(
            ValueLayout.JAVA_INT,
            ValueLayout.JAVA_INT,
            ValueLayout.ADDRESS,
            ValueLayout.JAVA_INT);
    private static final FunctionDescriptor LISTEN_DESCRIPTOR =
            FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT);
    private static final FunctionDescriptor ACCEPT_DESCRIPTOR = FunctionDescriptor.of(
            ValueLayout.JAVA_INT,
            ValueLayout.JAVA_INT,
            ValueLayout.ADDRESS,
            ValueLayout.ADDRESS);
    private static final FunctionDescriptor IO_DESCRIPTOR = FunctionDescriptor.of(
            ValueLayout.JAVA_LONG, ValueLayout.JAVA_INT, ValueLayout.ADDRESS, ValueLayout.JAVA_LONG);
    private static final FunctionDescriptor SHUTDOWN_DESCRIPTOR =
            FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT);
    private static final FunctionDescriptor CLOSE_DESCRIPTOR =
            FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.JAVA_INT);

    private final int parentCid;
    private final int vsockPort;
    private final HealthResponseProvider healthResponseProvider;
    private final HealthResponseProvider benchmarkResponseProvider;
    private final Semaphore activeClients = new Semaphore(MAX_CLIENTS);
    private volatile boolean closed;
    private volatile int serverFd = -1;
    private Thread acceptThread;

    public LinuxVsockHealthBridge(
            int parentCid, int vsockPort, HealthResponseProvider healthResponseProvider) {
        this(parentCid, vsockPort, healthResponseProvider, null);
    }

    public LinuxVsockHealthBridge(
            int parentCid,
            int vsockPort,
            HealthResponseProvider healthResponseProvider,
            HealthResponseProvider benchmarkResponseProvider) {
        if (parentCid < 0 || vsockPort < 1 || vsockPort > 65535) {
            throw new IllegalArgumentException("AWS Nitro health bridge values are invalid.");
        }
        this.parentCid = parentCid;
        this.vsockPort = vsockPort;
        this.healthResponseProvider =
                Objects.requireNonNull(healthResponseProvider, "healthResponseProvider");
        this.benchmarkResponseProvider = benchmarkResponseProvider;
    }

    public synchronized void start() {
        if (acceptThread != null) {
            throw new IllegalStateException("AWS Nitro health vsock bridge is already started.");
        }
        requireLinux();
        try (Arena arena = Arena.ofConfined()) {
            NativeMethods methods = nativeMethods();
            int fd = (int) methods.socket().invokeExact(AF_VSOCK, SOCK_STREAM, 0);
            if (fd < 0) {
                throw new AwsNitroEnclaveException("Unable to open health-only vsock listener.");
            }
            serverFd = fd;
            MemorySegment address = arena.allocate(SOCKET_ADDRESS_SIZE, Long.BYTES);
            address.fill((byte) 0);
            address.set(ValueLayout.JAVA_SHORT, 0, (short) AF_VSOCK);
            address.set(ValueLayout.JAVA_INT, 4, vsockPort);
            address.set(ValueLayout.JAVA_INT, 8, VMADDR_CID_ANY);
            if ((int) methods.bind().invokeExact(fd, address, SOCKET_ADDRESS_SIZE) != 0) {
                throw new AwsNitroEnclaveException("Unable to bind health-only vsock port.");
            }
            if ((int) methods.listen().invokeExact(fd, MAX_CLIENTS) != 0) {
                throw new AwsNitroEnclaveException("Unable to listen on health-only vsock port.");
            }
            acceptThread = Thread.ofVirtual()
                    .name("cjae-health-vsock-accept")
                    .start(this::acceptLoop);
            LOGGER.log(
                    System.Logger.Level.INFO,
                    "AWS Nitro health-only vsock listener started (port={0}, parentCid={1}).",
                    vsockPort,
                    parentCid);
        } catch (AwsNitroEnclaveException exception) {
            closeServerSocket();
            throw exception;
        } catch (Throwable failure) {
            closeServerSocket();
            throw new AwsNitroEnclaveException(
                    "Unable to start AWS Nitro health-only vsock bridge.", failure);
        }
    }

    @Override
    public synchronized void close() {
        closed = true;
        closeServerSocket();
        if (acceptThread != null) {
            try {
                acceptThread.join(2_000);
            } catch (InterruptedException exception) {
                Thread.currentThread().interrupt();
            }
            acceptThread = null;
        }
    }

    static boolean isHealthRequestLine(String requestLine) {
        return "GET /health HTTP/1.0".equals(requestLine)
                || "GET /health HTTP/1.1".equals(requestLine);
    }

    static boolean isBenchmarkResultsRequestLine(String requestLine) {
        return "GET /benchmark/results HTTP/1.0".equals(requestLine)
                || "GET /benchmark/results HTTP/1.1".equals(requestLine);
    }

    private void acceptLoop() {
        NativeMethods methods = nativeMethods();
        while (!closed) {
            try (Arena arena = Arena.ofConfined()) {
                MemorySegment peerAddress = arena.allocate(SOCKET_ADDRESS_SIZE, Long.BYTES);
                MemorySegment addressLength = arena.allocate(ValueLayout.JAVA_INT);
                peerAddress.fill((byte) 0);
                addressLength.set(ValueLayout.JAVA_INT, 0, SOCKET_ADDRESS_SIZE);
                int clientFd = (int) methods.accept().invokeExact(
                        serverFd, peerAddress, addressLength);
                if (clientFd < 0) {
                    if (!closed) {
                        LOGGER.log(
                                System.Logger.Level.ERROR,
                                "AWS Nitro health vsock accept failed.");
                        throw new AwsNitroEnclaveException(
                                "AWS Nitro health vsock accept failed.");
                    }
                    return;
                }
                int peerFamily = peerAddress.get(ValueLayout.JAVA_SHORT, 0);
                int peerAddressSize = addressLength.get(ValueLayout.JAVA_INT, 0);
                int peerCid = peerAddress.get(ValueLayout.JAVA_INT, 8);
                if (peerFamily != AF_VSOCK
                        || peerAddressSize != SOCKET_ADDRESS_SIZE
                        || peerCid != parentCid) {
                    LOGGER.log(
                            System.Logger.Level.WARNING,
                            "AWS Nitro health vsock rejected peer (family={0}, cid={1}, "
                                    + "addressLength={2}, expectedParentCid={3}).",
                            peerFamily,
                            peerCid,
                            peerAddressSize,
                            parentCid);
                    closeSocket(methods, clientFd);
                    continue;
                }
                if (!activeClients.tryAcquire()) {
                    closeSocket(methods, clientFd);
                    continue;
                }
                try {
                    Thread.ofVirtual()
                            .name("cjae-health-vsock-client")
                            .start(() -> serveClient(methods, clientFd));
                } catch (RuntimeException failure) {
                    activeClients.release();
                    closeSocket(methods, clientFd);
                    throw failure;
                }
            } catch (AwsNitroEnclaveException exception) {
                if (!closed) {
                    throw exception;
                }
                return;
            } catch (Throwable failure) {
                if (!closed) {
                    throw new AwsNitroEnclaveException(
                            "AWS Nitro health vsock accept failed.", failure);
                }
                return;
            }
        }
    }

    private void serveClient(NativeMethods methods, int clientFd) {
        try {
            String requestLine = readRequestLine(methods, clientFd);
            boolean healthRequest = isHealthRequestLine(requestLine);
            boolean benchmarkRequest = benchmarkResponseProvider != null
                    && isBenchmarkResultsRequestLine(requestLine);
            if (!healthRequest && !benchmarkRequest) {
                writeResponse(methods, clientFd, BAD_REQUEST_RESPONSE.clone());
                return;
            }
            HealthResponse health = (healthRequest
                    ? healthResponseProvider
                    : benchmarkResponseProvider).get();
            byte[] body = health.body();
            try {
                if (body.length > MAX_RESPONSE_BYTES) {
                    throw new IOException("Worker health response exceeds its size limit.");
                }
                int statusCode = health.statusCode() == 200 || health.statusCode() == 503
                        ? health.statusCode()
                        : 503;
                writeResponse(methods, clientFd, httpResponse(statusCode, body));
            } finally {
                Arrays.fill(body, (byte) 0);
            }
        } catch (IOException failure) {
            LOGGER.log(System.Logger.Level.WARNING,
                    "AWS Nitro health vsock probe could not produce worker health "
                            + "(failureType={0}).",
                    failure.getClass().getSimpleName());
            try {
                writeResponse(methods, clientFd, BUSY_RESPONSE.clone());
            } catch (IOException writeFailure) {
                LOGGER.log(System.Logger.Level.DEBUG,
                        "AWS Nitro health vsock probe response could not be sent.");
            }
        } catch (RuntimeException failure) {
            LOGGER.log(
                    System.Logger.Level.ERROR,
                    "AWS Nitro health vsock probe failed (failureType={0}).",
                    failure.getClass().getSimpleName());
            try {
                writeResponse(methods, clientFd, BUSY_RESPONSE.clone());
            } catch (IOException writeFailure) {
                LOGGER.log(System.Logger.Level.DEBUG,
                        "AWS Nitro health vsock probe response could not be sent.");
            }
        } finally {
            shutdown(methods, clientFd);
            closeSocket(methods, clientFd);
            activeClients.release();
        }
    }

    private static String readRequestLine(NativeMethods methods, int fd) throws IOException {
        try (Arena arena = Arena.ofConfined()) {
            MemorySegment buffer = arena.allocate(MAX_REQUEST_LINE_BYTES, 8);
            try {
                long total = 0;
                while (total < MAX_REQUEST_LINE_BYTES) {
                    long count;
                    try {
                        count = (long) methods.read().invokeExact(
                                fd,
                                buffer.asSlice(total),
                                (long) MAX_REQUEST_LINE_BYTES - total);
                    } catch (Throwable failure) {
                        throw new IOException("Unable to read health probe request.", failure);
                    }
                    if (count <= 0) {
                        throw new IOException("Health probe request ended before its request line.");
                    }
                    long end = total + count;
                    for (long index = total; index < end; index++) {
                        if (buffer.get(ValueLayout.JAVA_BYTE, index) == (byte) '\n') {
                            if (index < 1
                                    || buffer.get(ValueLayout.JAVA_BYTE, index - 1) != (byte) '\r') {
                                throw new IOException("Health probe request line is malformed.");
                            }
                            byte[] requestLine =
                                    buffer.asSlice(0, index - 1).toArray(ValueLayout.JAVA_BYTE);
                            try {
                                return new String(requestLine, StandardCharsets.US_ASCII);
                            } finally {
                                Arrays.fill(requestLine, (byte) 0);
                            }
                        }
                    }
                    total = end;
                }
                throw new IOException("Health probe request line exceeds the allowed length.");
            } finally {
                buffer.fill((byte) 0);
            }
        }
    }

    static byte[] httpResponse(int statusCode, byte[] body) {
        String reason = switch (statusCode) {
            case 200 -> "OK";
            case 400 -> "Bad Request";
            default -> "Service Unavailable";
        };
        byte[] header = ("HTTP/1.1 " + statusCode + " " + reason
                + "\r\nContent-Type: application/json; charset=utf-8"
                + "\r\nContent-Length: " + body.length
                + "\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII);
        byte[] response = Arrays.copyOf(header, header.length + body.length);
        System.arraycopy(body, 0, response, header.length, body.length);
        return response;
    }

    private static void writeResponse(
            NativeMethods methods, int fd, byte[] response) throws IOException {
        try (Arena arena = Arena.ofConfined()) {
            MemorySegment buffer = arena.allocate(response.length, 8);
            buffer.copyFrom(MemorySegment.ofArray(response));
            long offset = 0;
            while (offset < buffer.byteSize()) {
                long written;
                try {
                    written = (long) methods.write().invokeExact(
                            fd, buffer.asSlice(offset), buffer.byteSize() - offset);
                } catch (Throwable failure) {
                    throw new IOException("Unable to write health probe response.", failure);
                }
                if (written <= 0) {
                    throw new IOException("Health probe response write did not complete.");
                }
                offset += written;
            }
            buffer.fill((byte) 0);
        }
    }

    private void closeServerSocket() {
        int fd = serverFd;
        serverFd = -1;
        if (fd >= 0) {
            shutdown(nativeMethods(), fd);
            closeSocket(nativeMethods(), fd);
        }
    }

    private static void shutdown(NativeMethods methods, int fd) {
        try {
            int result = (int) methods.shutdown().invokeExact(fd, SHUT_RDWR);
            if (result != 0) {
                LOGGER.log(System.Logger.Level.DEBUG,
                        "Unable to shut down AWS Nitro health socket.");
            }
        } catch (Throwable failure) {
            LOGGER.log(System.Logger.Level.DEBUG,
                    "Unable to shut down AWS Nitro health socket: {0}",
                    failure.getClass().getSimpleName());
        }
    }

    private static void closeSocket(NativeMethods methods, int fd) {
        try {
            int result = (int) methods.close().invokeExact(fd);
            if (result != 0) {
                LOGGER.log(System.Logger.Level.DEBUG,
                        "Unable to close AWS Nitro health socket.");
            }
        } catch (Throwable failure) {
            LOGGER.log(System.Logger.Level.DEBUG,
                    "Unable to close AWS Nitro health socket: {0}",
                    failure.getClass().getSimpleName());
        }
    }

    private static void requireLinux() {
        if (!System.getProperty("os.name", "").toLowerCase().contains("linux")) {
            throw new AwsNitroEnclaveException(
                    "AWS Nitro health vsock bridge is supported only on Linux.");
        }
    }

    private static MethodHandle downcall(
            SymbolLookup symbols, String name, FunctionDescriptor descriptor) {
        MemorySegment address = symbols.find(name)
                .orElseThrow(() -> new UnsatisfiedLinkError(
                        "Linux libc symbol is unavailable: " + name));
        return LINKER.downcallHandle(address, descriptor);
    }

    private static NativeMethods nativeMethods() {
        return NativeMethodsHolder.METHODS;
    }

    private static final class NativeMethodsHolder {
        private static final NativeMethods METHODS = loadMethods();

        private static NativeMethods loadMethods() {
            SymbolLookup libc = LINKER.defaultLookup();
            return new NativeMethods(
                    downcall(libc, "socket", SOCKET_DESCRIPTOR),
                    downcall(libc, "bind", BIND_DESCRIPTOR),
                    downcall(libc, "listen", LISTEN_DESCRIPTOR),
                    downcall(libc, "accept", ACCEPT_DESCRIPTOR),
                    downcall(libc, "read", IO_DESCRIPTOR),
                    downcall(libc, "write", IO_DESCRIPTOR),
                    downcall(libc, "shutdown", SHUTDOWN_DESCRIPTOR),
                    downcall(libc, "close", CLOSE_DESCRIPTOR));
        }
    }

    private record NativeMethods(
            MethodHandle socket,
            MethodHandle bind,
            MethodHandle listen,
            MethodHandle accept,
            MethodHandle read,
            MethodHandle write,
            MethodHandle shutdown,
            MethodHandle close) {
    }

    @FunctionalInterface
    public interface HealthResponseProvider {
        HealthResponse get() throws IOException;
    }

    public record HealthResponse(int statusCode, byte[] body) {
        public HealthResponse {
            body = Objects.requireNonNull(body, "body").clone();
        }

        @Override
        public byte[] body() {
            return body.clone();
        }
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import java.io.IOException;
import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.Linker;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.SymbolLookup;
import java.lang.foreign.ValueLayout;
import java.lang.invoke.MethodHandle;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.Arrays;
import java.util.Base64;
import java.util.Objects;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

/**
 * Sends a bounded, length-prefixed JSON KMS Decrypt request to a parent vsock
 * proxy. The proxy is responsible for AWS credentials and KMS HTTPS access.
 */
public final class LinuxVsockParentKmsTransport implements ParentVsockKmsTransport {
    private static final int AF_VSOCK = 40;
    private static final int SOCK_STREAM = 1;
    private static final int SOL_SOCKET = 1;
    private static final int SO_RCVTIMEO = 20;
    private static final int SO_SNDTIMEO = 21;
    private static final long IO_TIMEOUT_SECONDS = 30;
    private static final int HEADER_SIZE = Integer.BYTES;
    private static final int MAX_FRAME_BYTES =
            AwsNitroKmsDecryptRequest.MAX_REQUEST_BYTES + 16 * 1024;
    private static final Linker LINKER = Linker.nativeLinker();
    private static final FunctionDescriptor SOCKET_DESCRIPTOR = FunctionDescriptor.of(
            ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT);
    private static final FunctionDescriptor CONNECT_DESCRIPTOR = FunctionDescriptor.of(
            ValueLayout.JAVA_INT,
            ValueLayout.JAVA_INT,
            ValueLayout.ADDRESS,
            ValueLayout.JAVA_INT);
    private static final FunctionDescriptor SOCKET_OPTION_DESCRIPTOR = FunctionDescriptor.of(
            ValueLayout.JAVA_INT,
            ValueLayout.JAVA_INT,
            ValueLayout.JAVA_INT,
            ValueLayout.JAVA_INT,
            ValueLayout.ADDRESS,
            ValueLayout.JAVA_INT);
    private static final FunctionDescriptor IO_DESCRIPTOR = FunctionDescriptor.of(
            ValueLayout.JAVA_LONG, ValueLayout.JAVA_INT, ValueLayout.ADDRESS, ValueLayout.JAVA_LONG);
    private static final FunctionDescriptor CLOSE_DESCRIPTOR = FunctionDescriptor.of(
            ValueLayout.JAVA_INT, ValueLayout.JAVA_INT);

    private final int parentCid;
    private final int proxyPort;
    private final ObjectMapper objectMapper;
    private volatile NativeMethods nativeMethods;

    public LinuxVsockParentKmsTransport(
            int parentCid, int proxyPort, ObjectMapper objectMapper) {
        if (parentCid < 0 || parentCid == 0xffff_ffff || proxyPort < 1 || proxyPort > 65535) {
            throw new IllegalArgumentException("Parent vsock CID or proxy port is invalid.");
        }
        this.parentCid = parentCid;
        this.proxyPort = proxyPort;
        this.objectMapper = Objects.requireNonNull(objectMapper, "objectMapper");
    }

    @Override
    public AwsNitroKmsDecryptResponse decrypt(AwsNitroKmsDecryptRequest request) {
        Objects.requireNonNull(request, "request");
        if (!System.getProperty("os.name", "").toLowerCase().contains("linux")) {
            throw new AwsNitroEnclaveException(
                    "AWS Nitro parent-vsock transport is supported only on Linux.");
        }
        NativeMethods methods = nativeMethods();

        byte[] requestFrame = null;
        byte[] responseFrame = null;
        try {
            requestFrame = encodeRequest(request);
            try (Arena arena = Arena.ofConfined()) {
                int fd = openSocket(methods);
                try {
                    configureTimeouts(arena, methods, fd);
                    connectToParent(arena, methods, fd);
                    writeFrame(arena, methods, fd, requestFrame);
                    responseFrame = readFrame(arena, methods, fd);
                } finally {
                    closeSocket(methods, fd);
                }
            }
            return decodeResponse(responseFrame);
        } catch (AwsNitroEnclaveException exception) {
            throw exception;
        } catch (IOException | RuntimeException exception) {
            throw new AwsNitroEnclaveException(
                    "AWS KMS parent-vsock exchange failed.", exception);
        } finally {
            clear(requestFrame);
            clear(responseFrame);
        }
    }

    byte[] encodeRequest(AwsNitroKmsDecryptRequest request) throws IOException {
        byte[] ciphertext = request.ciphertextBlob();
        byte[] attestationDocument = request.recipient().attestationDocument();
        try {
            return objectMapper.writeValueAsBytes(new ProxyRequest(
                    1,
                    "kms:Decrypt",
                    new KmsRequest(
                            request.keyId(),
                            Base64.getEncoder().encodeToString(ciphertext),
                            new Recipient(
                                    Base64.getEncoder().encodeToString(attestationDocument),
                                    request.recipient().keyEncryptionAlgorithm()))));
        } finally {
            clear(ciphertext);
            clear(attestationDocument);
        }
    }

    AwsNitroKmsDecryptResponse decodeResponse(byte[] response) throws IOException {
        JsonNode root = objectMapper.readTree(response);
        if (root.path("version").asInt(-1) != 1) {
            throw new AwsNitroEnclaveException("Parent-vsock proxy protocol version is invalid.");
        }
        JsonNode responseNode = root.path("response");
        String encoded = responseNode.path("CiphertextForRecipient").asText(null);
        if (encoded == null || encoded.isBlank()) {
            throw new AwsNitroEnclaveException(
                    "Parent-vsock KMS response omitted CiphertextForRecipient.");
        }
        byte[] ciphertext;
        try {
            ciphertext = Base64.getDecoder().decode(encoded);
        } catch (IllegalArgumentException exception) {
            throw new AwsNitroEnclaveException(
                    "Parent-vsock KMS response contains invalid base64.", exception);
        }
        try {
            return new AwsNitroKmsDecryptResponse(ciphertext);
        } finally {
            clear(ciphertext);
        }
    }

    private int openSocket(NativeMethods methods) {
        try {
            int fd = (int) methods.socket().invokeExact(AF_VSOCK, SOCK_STREAM, 0);
            if (fd < 0) {
                throw new AwsNitroEnclaveException("Unable to open parent-vsock connection.");
            }
            return fd;
        } catch (AwsNitroEnclaveException exception) {
            throw exception;
        } catch (Throwable failure) {
            throw nativeFailure("Unable to open parent-vsock connection.", failure);
        }
    }

    private void configureTimeouts(Arena arena, NativeMethods methods, int fd) {
        MemorySegment timeout = arena.allocate(2L * Long.BYTES, Long.BYTES);
        timeout.set(ValueLayout.JAVA_LONG, 0, IO_TIMEOUT_SECONDS);
        timeout.set(ValueLayout.JAVA_LONG, Long.BYTES, 0L);
        setSocketOption(methods, fd, SO_RCVTIMEO, timeout);
        setSocketOption(methods, fd, SO_SNDTIMEO, timeout);
    }

    private void setSocketOption(NativeMethods methods, int fd, int option, MemorySegment value) {
        try {
            int result = (int) methods.setSocketOption().invokeExact(
                    fd, SOL_SOCKET, option, value, (int) (2L * Long.BYTES));
            if (result != 0) {
                throw new AwsNitroEnclaveException("Unable to configure vsock I/O timeout.");
            }
        } catch (AwsNitroEnclaveException exception) {
            throw exception;
        } catch (Throwable failure) {
            throw nativeFailure("Unable to configure vsock I/O timeout.", failure);
        }
    }

    private void connectToParent(Arena arena, NativeMethods methods, int fd) {
        MemorySegment address = arena.allocate(16, 8);
        address.fill((byte) 0);
        address.set(ValueLayout.JAVA_SHORT, 0, (short) AF_VSOCK);
        address.set(ValueLayout.JAVA_INT, 4, proxyPort);
        address.set(ValueLayout.JAVA_INT, 8, parentCid);
        try {
            int result = (int) methods.connect().invokeExact(fd, address, 16);
            if (result != 0) {
                throw new AwsNitroEnclaveException("Unable to connect to parent vsock proxy.");
            }
        } catch (AwsNitroEnclaveException exception) {
            throw exception;
        } catch (Throwable failure) {
            throw nativeFailure("Unable to connect to parent vsock proxy.", failure);
        }
    }

    private void writeFrame(Arena arena, NativeMethods methods, int fd, byte[] payload) {
        byte[] header = ByteBuffer.allocate(HEADER_SIZE)
                .order(ByteOrder.BIG_ENDIAN)
                .putInt(payload.length)
                .array();
        MemorySegment nativeHeader = copyToNative(arena, header);
        MemorySegment nativePayload = copyToNative(arena, payload);
        try {
            writeFully(methods, fd, nativeHeader);
            writeFully(methods, fd, nativePayload);
        } finally {
            nativeHeader.fill((byte) 0);
            nativePayload.fill((byte) 0);
            clear(header);
        }
    }

    static MemorySegment copyToNative(Arena arena, byte[] bytes) {
        MemorySegment nativeBuffer = arena.allocate(bytes.length, 1);
        return nativeBuffer.copyFrom(MemorySegment.ofArray(bytes));
    }

    private byte[] readFrame(Arena arena, NativeMethods methods, int fd) {
        MemorySegment header = arena.allocate(HEADER_SIZE, 1);
        readFully(methods, fd, header);
        byte[] headerBytes = header.toArray(ValueLayout.JAVA_BYTE);
        int length;
        try {
            length = ByteBuffer.wrap(headerBytes).order(ByteOrder.BIG_ENDIAN).getInt();
        } finally {
            clear(headerBytes);
            header.fill((byte) 0);
        }
        if (length < 1 || length > MAX_FRAME_BYTES) {
            throw new AwsNitroEnclaveException("Parent-vsock response frame exceeds its size bound.");
        }
        MemorySegment body = arena.allocate(length, 1);
        readFully(methods, fd, body);
        return body.toArray(ValueLayout.JAVA_BYTE);
    }

    private void writeFully(NativeMethods methods, int fd, MemorySegment buffer) {
        long offset = 0;
        while (offset < buffer.byteSize()) {
            try {
                long written = (long) methods.write().invokeExact(
                        fd, buffer.asSlice(offset), buffer.byteSize() - offset);
                if (written <= 0) {
                    throw new AwsNitroEnclaveException("Parent-vsock write did not complete.");
                }
                offset += written;
            } catch (AwsNitroEnclaveException exception) {
                throw exception;
            } catch (Throwable failure) {
                throw nativeFailure("Parent-vsock write failed.", failure);
            }
        }
    }

    private void readFully(NativeMethods methods, int fd, MemorySegment buffer) {
        long offset = 0;
        while (offset < buffer.byteSize()) {
            try {
                long received = (long) methods.read().invokeExact(
                        fd, buffer.asSlice(offset), buffer.byteSize() - offset);
                if (received <= 0) {
                    throw new AwsNitroEnclaveException(
                            "Parent-vsock closed before the full response was received.");
                }
                offset += received;
            } catch (AwsNitroEnclaveException exception) {
                throw exception;
            } catch (Throwable failure) {
                throw nativeFailure("Parent-vsock read failed.", failure);
            }
        }
    }

    private void closeSocket(NativeMethods methods, int fd) {
        try {
            int result = (int) methods.close().invokeExact(fd);
            if (result != 0) {
                throw new AwsNitroEnclaveException("Unable to close parent-vsock socket.");
            }
        } catch (AwsNitroEnclaveException exception) {
            throw exception;
        } catch (Throwable failure) {
            throw nativeFailure("Unable to close parent-vsock socket.", failure);
        }
    }

    private static MethodHandle downcall(
            SymbolLookup symbols, String name, FunctionDescriptor descriptor) {
        MemorySegment address = symbols.find(name)
                .orElseThrow(() -> new UnsatisfiedLinkError(
                        "Linux libc symbol is unavailable: " + name));
        return LINKER.downcallHandle(address, descriptor);
    }

    private NativeMethods nativeMethods() {
        NativeMethods methods = nativeMethods;
        if (methods != null) {
            return methods;
        }
        synchronized (this) {
            methods = nativeMethods;
            if (methods == null) {
                SymbolLookup libc = LINKER.defaultLookup();
                methods = new NativeMethods(
                        downcall(libc, "socket", SOCKET_DESCRIPTOR),
                        downcall(libc, "connect", CONNECT_DESCRIPTOR),
                        downcall(libc, "setsockopt", SOCKET_OPTION_DESCRIPTOR),
                        downcall(libc, "read", IO_DESCRIPTOR),
                        downcall(libc, "write", IO_DESCRIPTOR),
                        downcall(libc, "close", CLOSE_DESCRIPTOR));
                nativeMethods = methods;
            }
        }
        return methods;
    }

    private static AwsNitroEnclaveException nativeFailure(String message, Throwable failure) {
        return new AwsNitroEnclaveException(message, failure);
    }

    private static void clear(byte[] bytes) {
        if (bytes != null) {
            Arrays.fill(bytes, (byte) 0);
        }
    }

    private record ProxyRequest(int version, String operation, KmsRequest request) {
    }

    private record KmsRequest(String KeyId, String CiphertextBlob, Recipient Recipient) {
    }

    private record Recipient(String AttestationDocument, String KeyEncryptionAlgorithm) {
    }

    private record NativeMethods(
            MethodHandle socket,
            MethodHandle connect,
            MethodHandle setSocketOption,
            MethodHandle read,
            MethodHandle write,
            MethodHandle close) {
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.Linker;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.SymbolLookup;
import java.lang.foreign.ValueLayout;
import java.lang.invoke.MethodHandle;
import java.net.InetAddress;
import java.net.Socket;
import java.util.Arrays;

/**
 * Relays encrypted TLS records from a parent-enclave vsock to loopback Tomcat.
 */
public final class LinuxVsockTlsBridge implements AutoCloseable {
    private static final System.Logger LOGGER =
            System.getLogger(LinuxVsockTlsBridge.class.getName());
    private static final int AF_VSOCK = 40;
    private static final int SOCK_STREAM = 1;
    private static final int VMADDR_CID_ANY = -1;
    private static final int SHUT_WR = 1;
    private static final int SHUT_RDWR = 2;
    private static final int SOCKET_ADDRESS_SIZE = 16;
    private static final int BUFFER_BYTES = 16 * 1024;
    private static final Linker LINKER = Linker.nativeLinker();
    private static final FunctionDescriptor SOCKET_DESCRIPTOR = FunctionDescriptor.of(
            ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT);
    private static final FunctionDescriptor BIND_DESCRIPTOR = FunctionDescriptor.of(
            ValueLayout.JAVA_INT,
            ValueLayout.JAVA_INT,
            ValueLayout.ADDRESS,
            ValueLayout.JAVA_INT);
    private static final FunctionDescriptor LISTEN_DESCRIPTOR =
            FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT);
    private static final FunctionDescriptor ACCEPT_DESCRIPTOR = FunctionDescriptor.of(
            ValueLayout.JAVA_INT,
            ValueLayout.JAVA_INT,
            ValueLayout.ADDRESS,
            ValueLayout.ADDRESS);
    private static final FunctionDescriptor IO_DESCRIPTOR = FunctionDescriptor.of(
            ValueLayout.JAVA_LONG, ValueLayout.JAVA_INT, ValueLayout.ADDRESS, ValueLayout.JAVA_LONG);
    private static final FunctionDescriptor SHUTDOWN_DESCRIPTOR =
            FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT);
    private static final FunctionDescriptor CLOSE_DESCRIPTOR =
            FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.JAVA_INT);

    private final int vsockPort;
    private final int tlsPort;
    private volatile boolean closed;
    private volatile int serverFd = -1;
    private Thread acceptThread;

    public LinuxVsockTlsBridge(int vsockPort, int tlsPort) {
        if (vsockPort < 1 || vsockPort > 65535 || tlsPort < 1 || tlsPort > 65535) {
            throw new IllegalArgumentException("AWS Nitro TLS bridge port values are invalid.");
        }
        this.vsockPort = vsockPort;
        this.tlsPort = tlsPort;
    }

    public synchronized void start() {
        if (acceptThread != null) {
            throw new IllegalStateException("AWS Nitro TLS vsock bridge is already started.");
        }
        requireLinux();
        try (Arena arena = Arena.ofConfined()) {
            NativeMethods methods = nativeMethods();
            int fd = (int) methods.socket().invokeExact(AF_VSOCK, SOCK_STREAM, 0);
            if (fd < 0) {
                throw new AwsNitroEnclaveException("Unable to open gateway vsock listener.");
            }
            serverFd = fd;
            MemorySegment address = arena.allocate(SOCKET_ADDRESS_SIZE, Long.BYTES);
            address.fill((byte) 0);
            address.set(ValueLayout.JAVA_SHORT, 0, (short) AF_VSOCK);
            address.set(ValueLayout.JAVA_INT, 4, vsockPort);
            address.set(ValueLayout.JAVA_INT, 8, VMADDR_CID_ANY);
            int bindResult = (int) methods.bind().invokeExact(
                    fd, address, SOCKET_ADDRESS_SIZE);
            if (bindResult != 0) {
                throw new AwsNitroEnclaveException("Unable to bind AWS Nitro gateway vsock port.");
            }
            int listenResult = (int) methods.listen().invokeExact(fd, 64);
            if (listenResult != 0) {
                throw new AwsNitroEnclaveException("Unable to listen on AWS Nitro gateway vsock.");
            }
            acceptThread = Thread.ofVirtual()
                    .name("cjae-gateway-vsock-accept")
                    .start(this::acceptLoop);
        } catch (AwsNitroEnclaveException exception) {
            closeServerSocket();
            throw exception;
        } catch (Throwable failure) {
            closeServerSocket();
            throw new AwsNitroEnclaveException(
                    "Unable to start AWS Nitro gateway vsock bridge.", failure);
        }
    }

    @Override
    public synchronized void close() {
        closed = true;
        closeServerSocket();
        if (acceptThread != null) {
            try {
                acceptThread.join(2_000);
            } catch (InterruptedException exception) {
                Thread.currentThread().interrupt();
            }
            acceptThread = null;
        }
    }

    private void acceptLoop() {
        NativeMethods methods = nativeMethods();
        while (!closed) {
            final int clientFd;
            try {
                clientFd = (int) methods.accept().invokeExact(
                        serverFd, MemorySegment.NULL, MemorySegment.NULL);
            } catch (Throwable failure) {
                if (!closed) {
                    throw new AwsNitroEnclaveException(
                            "AWS Nitro gateway vsock accept failed.", failure);
                }
                return;
            }
            if (clientFd >= 0) {
                Thread.ofVirtual()
                        .name("cjae-gateway-vsock-client")
                        .start(() -> relayConnection(clientFd));
            }
        }
    }

    private void relayConnection(int clientFd) {
        NativeMethods methods = nativeMethods();
        try (Socket tlsSocket = new Socket(
                InetAddress.getLoopbackAddress(), tlsPort)) {
            tlsSocket.setTcpNoDelay(true);
            Thread toVsock = Thread.ofVirtual().start(() -> {
                try {
                    InputStream input = tlsSocket.getInputStream();
                    copyToVsock(input, methods, clientFd);
                } catch (IOException failure) {
                    LOGGER.log(System.Logger.Level.WARNING,
                            "AWS Nitro TLS bridge failed while relaying client data.");
                    shutdown(methods, clientFd, SHUT_RDWR);
                }
            });
            try {
                OutputStream output = tlsSocket.getOutputStream();
                copyToSocket(methods, clientFd, output);
                tlsSocket.shutdownOutput();
            } catch (IOException failure) {
                LOGGER.log(System.Logger.Level.WARNING,
                        "AWS Nitro TLS bridge failed while relaying enclave data.");
                shutdown(methods, clientFd, SHUT_RDWR);
            }
            try {
                toVsock.join();
            } catch (InterruptedException exception) {
                Thread.currentThread().interrupt();
                shutdown(methods, clientFd, SHUT_RDWR);
            }
        } catch (IOException failure) {
            LOGGER.log(System.Logger.Level.DEBUG,
                    "AWS Nitro TLS bridge could not connect to loopback TLS service: {0}",
                    failure.getClass().getSimpleName());
            shutdown(methods, clientFd, SHUT_RDWR);
        } finally {
            closeSocket(methods, clientFd);
        }
    }

    private static void copyToSocket(NativeMethods methods, int fd, OutputStream output)
            throws IOException {
        try (Arena arena = Arena.ofConfined()) {
            MemorySegment buffer = arena.allocate(BUFFER_BYTES, 8);
            while (true) {
                long count = (long) methods.read().invokeExact(
                        fd, buffer, (long) BUFFER_BYTES);
                if (count == 0) {
                    output.flush();
                    return;
                }
                if (count < 0) {
                    throw new IOException("AWS Nitro gateway vsock read failed.");
                }
                byte[] bytes = buffer.asSlice(0, count).toArray(ValueLayout.JAVA_BYTE);
                try {
                    output.write(bytes);
                    output.flush();
                } finally {
                    Arrays.fill(bytes, (byte) 0);
                }
            }
        } catch (IOException exception) {
            throw exception;
        } catch (Throwable failure) {
            throw new IOException("AWS Nitro gateway vsock read failed.", failure);
        }
    }

    private static void copyToVsock(InputStream input, NativeMethods methods, int fd)
            throws IOException {
        byte[] bytes = new byte[BUFFER_BYTES];
        try (Arena arena = Arena.ofConfined()) {
            MemorySegment buffer = arena.allocate(BUFFER_BYTES, 8);
            try {
                int count;
                while ((count = input.read(bytes)) >= 0) {
                    if (count == 0) {
                        continue;
                    }
                    buffer.asSlice(0, count).copyFrom(
                            MemorySegment.ofArray(bytes).asSlice(0, count));
                    writeFully(methods, fd, buffer.asSlice(0, count));
                    Arrays.fill(bytes, 0, count, (byte) 0);
                    buffer.asSlice(0, count).fill((byte) 0);
                }
                shutdown(methods, fd, SHUT_WR);
            } finally {
                buffer.fill((byte) 0);
            }
        } catch (IOException exception) {
            throw exception;
        } catch (Throwable failure) {
            throw new IOException("AWS Nitro gateway vsock write failed.", failure);
        } finally {
            Arrays.fill(bytes, (byte) 0);
        }
    }

    private static void writeFully(NativeMethods methods, int fd, MemorySegment buffer)
            throws Throwable {
        long offset = 0;
        while (offset < buffer.byteSize()) {
            long written = (long) methods.write().invokeExact(
                    fd, buffer.asSlice(offset), buffer.byteSize() - offset);
            if (written <= 0) {
                throw new IOException("AWS Nitro gateway vsock write did not complete.");
            }
            offset += written;
        }
    }

    private void closeServerSocket() {
        int fd = serverFd;
        serverFd = -1;
        if (fd >= 0) {
            shutdown(nativeMethods(), fd, SHUT_RDWR);
            closeSocket(nativeMethods(), fd);
        }
    }

    private static void shutdown(NativeMethods methods, int fd, int direction) {
        try {
            methods.shutdown().invokeExact(fd, direction);
        } catch (Throwable failure) {
            LOGGER.log(System.Logger.Level.DEBUG,
                    "Unable to shut down AWS Nitro gateway socket: {0}",
                    failure.getClass().getSimpleName());
        }
    }

    private static void closeSocket(NativeMethods methods, int fd) {
        try {
            methods.close().invokeExact(fd);
        } catch (Throwable failure) {
            LOGGER.log(System.Logger.Level.DEBUG,
                    "Unable to close AWS Nitro gateway socket: {0}",
                    failure.getClass().getSimpleName());
        }
    }

    private static void requireLinux() {
        if (!System.getProperty("os.name", "").toLowerCase().contains("linux")) {
            throw new AwsNitroEnclaveException(
                    "AWS Nitro gateway vsock bridge is supported only on Linux.");
        }
    }

    private static MethodHandle downcall(
            SymbolLookup symbols, String name, FunctionDescriptor descriptor) {
        MemorySegment address = symbols.find(name)
                .orElseThrow(() -> new UnsatisfiedLinkError(
                        "Linux libc symbol is unavailable: " + name));
        return LINKER.downcallHandle(address, descriptor);
    }

    private static NativeMethods nativeMethods() {
        return NativeMethodsHolder.METHODS;
    }

    private static final class NativeMethodsHolder {
        private static final NativeMethods METHODS = loadMethods();

        private static NativeMethods loadMethods() {
            SymbolLookup libc = LINKER.defaultLookup();
            return new NativeMethods(
                    downcall(libc, "socket", SOCKET_DESCRIPTOR),
                    downcall(libc, "bind", BIND_DESCRIPTOR),
                    downcall(libc, "listen", LISTEN_DESCRIPTOR),
                    downcall(libc, "accept", ACCEPT_DESCRIPTOR),
                    downcall(libc, "read", IO_DESCRIPTOR),
                    downcall(libc, "write", IO_DESCRIPTOR),
                    downcall(libc, "shutdown", SHUTDOWN_DESCRIPTOR),
                    downcall(libc, "close", CLOSE_DESCRIPTOR));
        }
    }

    private record NativeMethods(
            MethodHandle socket,
            MethodHandle bind,
            MethodHandle listen,
            MethodHandle accept,
            MethodHandle read,
            MethodHandle write,
            MethodHandle shutdown,
            MethodHandle close) {
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.dataformat.cbor.CBORFactory;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;

final class NsmCbor {
    private static final ObjectMapper MAPPER = new ObjectMapper(new CBORFactory());

    private NsmCbor() {}

    static byte[] encodeAttestationRequest(byte[] nonce, byte[] publicKey) throws IOException {
        Map<String, Object> fields = new LinkedHashMap<>();
        fields.put("user_data", null);
        fields.put("nonce", nonce);
        fields.put("public_key", publicKey);
        Map<String, Object> request = new LinkedHashMap<>();
        request.put("Attestation", fields);
        return MAPPER.writeValueAsBytes(request);
    }

    static byte[] decodeAttestationResponse(byte[] response) throws IOException {
        try (JsonParser parser = MAPPER.createParser(response)) {
            JsonNode root = MAPPER.readTree(parser);
            if (root == null || !root.isObject() || root.size() != 1) {
                throw new IOException("Expected a single NSM response entry.");
            }
            JsonNode attestation = root.get("Attestation");
            if (attestation == null || !attestation.isObject() || attestation.size() != 1) {
                throw new IOException("Expected an NSM attestation response.");
            }
            JsonNode document = attestation.get("document");
            if (document == null || !document.isBinary()) {
                throw new IOException("Expected a binary NSM attestation document.");
            }
            if (parser.nextToken() != null) {
                throw new IOException("Unexpected trailing data in NSM response.");
            }
            return document.binaryValue();
        }
    }
}package org.opentron.backend.security.confidential.gateway.aws;

import java.io.IOException;
import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.Linker;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.SymbolLookup;
import java.lang.foreign.ValueLayout;
import java.lang.invoke.MethodHandle;
import java.util.Arrays;
import java.util.Objects;

/**
 * Calls the AWS Nitro Secure Module directly through Linux's {@code /dev/nsm}
 * ioctl interface using Panama.
 */
public final class PanamaNitroEnclaveAttestationSource
        implements AwsNitroEnclaveAttestationSource {
    private static final int NONCE_BYTES = 32;
    private static final int MAX_PUBLIC_KEY_BYTES = 16 * 1024;
    private static final int MAX_ATTESTATION_DOCUMENT_BYTES = 0x3000;
    private static final int MAX_NSM_REQUEST_BYTES = 0x1000;
    private static final int NSM_IOCTL_MAGIC = 0x0A;
    private static final int NSM_IOCTL_NUMBER = 0;
    private static final int IOVEC_BYTES = 2 * Long.BYTES;
    private static final int NSM_MESSAGE_BYTES = 2 * IOVEC_BYTES;
    private static final int LINUX_O_RDWR = 2;
    private static final long NSM_IOCTL_REQUEST = (3L << 30)
            | ((long) NSM_MESSAGE_BYTES << 16)
            | ((long) NSM_IOCTL_MAGIC << 8)
            | NSM_IOCTL_NUMBER;

    private final NativeOperations nativeOperations;

    public PanamaNitroEnclaveAttestationSource() {
        this.nativeOperations = new PanamaNativeOperations();
    }

    PanamaNitroEnclaveAttestationSource(NativeOperations nativeOperations) {
        this.nativeOperations = Objects.requireNonNull(nativeOperations, "nativeOperations");
    }

    @Override
    public byte[] attest(byte[] nonce, byte[] ephemeralRsaPublicKey) {
        if (nonce == null || nonce.length != NONCE_BYTES) {
            throw new IllegalArgumentException("AWS NSM requires a 256-bit nonce.");
        }
        if (ephemeralRsaPublicKey == null || ephemeralRsaPublicKey.length == 0
                || ephemeralRsaPublicKey.length > MAX_PUBLIC_KEY_BYTES) {
            throw new IllegalArgumentException("AWS NSM recipient public key is invalid.");
        }
        byte[] document = nativeOperations.attest(nonce, ephemeralRsaPublicKey);
        if (document == null || document.length == 0
                || document.length > MAX_ATTESTATION_DOCUMENT_BYTES) {
            if (document != null) {
                Arrays.fill(document, (byte) 0);
            }
            throw new AwsNitroEnclaveException(
                    "AWS NSM returned an invalid attestation document.");
        }
        return document;
    }

    @FunctionalInterface
    interface NativeOperations {
        byte[] attest(byte[] nonce, byte[] ephemeralRsaPublicKey);
    }

    private static final class PanamaNativeOperations implements NativeOperations {
        @Override
        public byte[] attest(byte[] nonce, byte[] ephemeralRsaPublicKey) {
            requireSupportedPlatform();
            byte[] request;
            try {
                request = NsmCbor.encodeAttestationRequest(nonce, ephemeralRsaPublicKey);
            } catch (IOException failure) {
                throw new AwsNitroEnclaveException(
                        "Unable to encode the AWS NSM attestation request.", failure);
            }
            if (request.length > MAX_NSM_REQUEST_BYTES) {
                Arrays.fill(request, (byte) 0);
                throw new IllegalArgumentException("AWS NSM request exceeds its size limit.");
            }

            try (Arena arena = Arena.ofConfined()) {
                MemorySegment nativeRequest = arena.allocate(request.length, 1)
                        .copyFrom(MemorySegment.ofArray(request));
                MemorySegment nativeResponse = arena.allocate(MAX_ATTESTATION_DOCUMENT_BYTES, 1);
                MemorySegment nativeMessage = arena.allocate(NSM_MESSAGE_BYTES, Long.BYTES);
                try {
                    nativeMessage.set(ValueLayout.ADDRESS, 0, nativeRequest);
                    nativeMessage.set(ValueLayout.JAVA_LONG, Long.BYTES, request.length);
                    nativeMessage.set(ValueLayout.ADDRESS, IOVEC_BYTES, nativeResponse);
                    nativeMessage.set(
                            ValueLayout.JAVA_LONG,
                            IOVEC_BYTES + Long.BYTES,
                            MAX_ATTESTATION_DOCUMENT_BYTES);
                    try (NsmDevice device = NsmDevice.open()) {
                        int status = invokeIoctl(device.fileDescriptor(), nativeMessage);
                        long responseLength = nativeMessage.get(
                                ValueLayout.JAVA_LONG, IOVEC_BYTES + Long.BYTES);
                        if (status != 0 || responseLength <= 0
                                || responseLength > MAX_ATTESTATION_DOCUMENT_BYTES) {
                            throw new AwsNitroEnclaveException(
                                    "AWS NSM attestation ioctl returned an invalid response.");
                        }
                        byte[] encodedResponse = nativeResponse.asSlice(0, responseLength)
                                .toArray(ValueLayout.JAVA_BYTE);
                        try {
                            return NsmCbor.decodeAttestationResponse(encodedResponse);
                        } catch (IOException failure) {
                            throw new AwsNitroEnclaveException(
                                    "AWS NSM returned an invalid CBOR attestation response.",
                                    failure);
                        } finally {
                            Arrays.fill(encodedResponse, (byte) 0);
                        }
                    }
                } finally {
                    nativeRequest.fill((byte) 0);
                    nativeResponse.fill((byte) 0);
                    nativeMessage.fill((byte) 0);
                }
            } finally {
                Arrays.fill(request, (byte) 0);
            }
        }

        private static int invokeIoctl(int fileDescriptor, MemorySegment message) {
            try {
                return (int) NativeBindings.IOCTL.invokeExact(
                        fileDescriptor, NSM_IOCTL_REQUEST, message);
            } catch (Throwable failure) {
                throw new AwsNitroEnclaveException(
                        "Unable to invoke the AWS NSM ioctl.", failure);
            }
        }

        private static void requireSupportedPlatform() {
            if (!"Linux".equalsIgnoreCase(System.getProperty("os.name", ""))
                    || ValueLayout.ADDRESS.byteSize() != Long.BYTES) {
                throw new AwsNitroEnclaveException(
                        "Direct AWS NSM access requires a 64-bit Linux runtime.");
            }
        }
    }

    private static final class NsmDevice implements AutoCloseable {
        private final int fileDescriptor;
        private boolean closed;

        private NsmDevice(int fileDescriptor) {
            this.fileDescriptor = fileDescriptor;
        }

        static NsmDevice open() {
            try (Arena arena = Arena.ofConfined()) {
                int fd = (int) NativeBindings.OPEN.invokeExact(
                        arena.allocateUtf8String("/dev/nsm"), LINUX_O_RDWR);
                if (fd < 0) {
                    throw new AwsNitroEnclaveException(
                            "Unable to open the AWS NSM device at /dev/nsm.");
                }
                return new NsmDevice(fd);
            } catch (AwsNitroEnclaveException failure) {
                throw failure;
            } catch (Throwable failure) {
                throw new AwsNitroEnclaveException(
                        "Unable to open the AWS NSM device at /dev/nsm.", failure);
            }
        }

        int fileDescriptor() {
            return fileDescriptor;
        }

        @Override
        public void close() {
            if (closed) {
                return;
            }
            closed = true;
            try {
                int status = (int) NativeBindings.CLOSE.invokeExact(fileDescriptor);
                if (status != 0) {
                    throw new AwsNitroEnclaveException(
                            "Unable to close the AWS NSM device.");
                }
            } catch (AwsNitroEnclaveException failure) {
                throw failure;
            } catch (Throwable failure) {
                throw new AwsNitroEnclaveException(
                        "Unable to close the AWS NSM device.", failure);
            }
        }
    }

    private static final class NativeBindings {
        private static final Linker LINKER = Linker.nativeLinker();
        private static final SymbolLookup SYMBOLS = LINKER.defaultLookup();
        private static final MethodHandle OPEN = bind(
                "open",
                FunctionDescriptor.of(
                        ValueLayout.JAVA_INT, ValueLayout.ADDRESS, ValueLayout.JAVA_INT));
        private static final MethodHandle CLOSE = bind(
                "close",
                FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.JAVA_INT));
        private static final MethodHandle IOCTL = bind(
                "ioctl",
                FunctionDescriptor.of(
                        ValueLayout.JAVA_INT,
                        ValueLayout.JAVA_INT,
                        ValueLayout.JAVA_LONG,
                        ValueLayout.ADDRESS),
                Linker.Option.firstVariadicArg(2));

        private NativeBindings() {}

        private static MethodHandle bind(
                String name,
                FunctionDescriptor descriptor,
                Linker.Option... options) {
            try {
                MemorySegment symbol = SYMBOLS.find(name)
                        .orElseThrow(() -> new UnsatisfiedLinkError(
                                "Linux libc symbol is unavailable: " + name));
                return LINKER.downcallHandle(symbol, descriptor, options);
            } catch (Throwable failure) {
                throw new AwsNitroEnclaveException(
                        "Unable to bind Linux libc symbol: " + name, failure);
            }
        }
    }
}package org.opentron.backend.security.confidential.gateway.aws;

/**
 * Explicit enclave-to-parent-vsock KMS transport boundary.
 *
 * <p>Nitro Enclaves have no external networking. A production implementation
 * must send the bounded request through the parent instance's vsock proxy to
 * AWS KMS and validate/parse the AWS response. No transport implementation or
 * provisioning integration is included in this package.</p>
 */
@FunctionalInterface
public interface ParentVsockKmsTransport {
    AwsNitroKmsDecryptResponse decrypt(AwsNitroKmsDecryptRequest request);
}package org.opentron.backend.security.confidential.gateway.gcp;

public final class GcpAttestationException extends RuntimeException {
    public GcpAttestationException(String message) {
        super(message);
    }

    public GcpAttestationException(String message, Throwable cause) {
        super(message, cause);
    }
}package org.opentron.backend.security.confidential.gateway.gcp;

import org.springframework.security.oauth2.jwt.Jwt;

@FunctionalInterface
public interface GcpAttestationJwtDecoder {
    Jwt decode(String compactJwt);
}package org.opentron.backend.security.confidential.gateway.gcp;

import java.util.Set;

/**
 * Policy for Google Cloud Attestation EAT claims. Instance entries may match the
 * official GCA {@code instance_name} or {@code instance_id} value.
 */
public record GcpAttestationPolicy(
        String audience,
        HardwareModel hardwareModel,
        Set<String> allowedProjects,
        Set<String> allowedZones,
        Set<String> allowedInstances,
        String expectedImageDigest) {

    public enum HardwareModel {
        AMD_SEV("GCP_AMD_SEV"),
        INTEL_TDX("GCP_INTEL_TDX");

        private final String claimValue;

        HardwareModel(String claimValue) {
            this.claimValue = claimValue;
        }

        String claimValue() {
            return claimValue;
        }
    }

    public GcpAttestationPolicy {
        expectedImageDigest = expectedImageDigest == null ? "" : expectedImageDigest;
        if (audience == null || audience.isBlank() || audience.length() > 512) {
            throw new IllegalArgumentException("A GCA audience of at most 512 characters is required.");
        }
        if (hardwareModel == null) {
            throw new IllegalArgumentException("An explicit GCA hardware model is required.");
        }
        allowedProjects = immutableNonEmptySet(allowedProjects, "project");
        allowedZones = immutableNonEmptySet(allowedZones, "zone");
        allowedInstances = immutableNonEmptySet(allowedInstances, "instance");
        if (expectedImageDigest != null && !expectedImageDigest.isBlank()
                && !expectedImageDigest.matches("sha256:[A-Fa-f0-9]{64}")) {
            throw new IllegalArgumentException(
                    "Expected Confidential Space image digest must be a SHA-256 digest.");
        }
    }

    public GcpAttestationPolicy(
            String audience,
            HardwareModel hardwareModel,
            Set<String> allowedProjects,
            Set<String> allowedZones,
            Set<String> allowedInstances) {
        this(audience, hardwareModel, allowedProjects, allowedZones, allowedInstances, "");
    }

    private static Set<String> immutableNonEmptySet(Set<String> values, String label) {
        if (values == null || values.isEmpty()
                || values.stream().anyMatch(value -> value == null || value.isBlank())) {
            throw new IllegalArgumentException("At least one allowed " + label + " is required.");
        }
        return Set.copyOf(values);
    }
}package org.opentron.backend.security.confidential.gateway.gcp;

/**
 * Deployment-supplied source of a GCA-issued compact JWT bound to the requested
 * audience and nonce. Google documents the token claims and the launcher flow,
 * but this adapter intentionally does not assume an undocumented metadata URL.
 * The deployment must supply an implementation using its approved acquisition
 * mechanism; it must not return caller-supplied or unverified evidence.
 */
@FunctionalInterface
public interface GcpAttestationTokenSource {
    String fetch(String audience, String nonce);
}package org.opentron.backend.security.confidential.gateway.gcp;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.security.SecureRandom;
import java.time.Clock;
import java.time.Duration;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.Set;
import java.util.stream.Collectors;
import org.opentron.backend.security.confidential.ConfidentialRuntimeVerifier;
import org.opentron.backend.security.confidential.gateway.SecureContextKeyProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;

/**
 * GCP adapter configuration for the {@code gcp-cvm} profile.
 *
 * <p>Required properties: {@code confidential.gcp.attestation.audience},
 * {@code confidential.gcp.attestation.hardware-model} ({@code AMD_SEV} or
 * {@code INTEL_TDX}), {@code confidential.gcp.attestation.allowed-projects},
 * {@code confidential.gcp.attestation.allowed-zones},
 * {@code confidential.gcp.attestation.allowed-instances},
 * {@code confidential.gcp.wif.audience} (the canonical provider resource name),
 * {@code confidential.gcp.kms.key-resource},
 * {@code confidential.gcp.kms.context-key-id}, and
 * {@code confidential.gcp.kms.ciphertext-base64}. The ciphertext must be a
 * previously Cloud-KMS-encrypted 256-bit context DEK. This configuration uses
 * the packaged Google {@code gotpm} vTPM token source. The API key
 * release path remains disabled unless the GCP gateway is explicitly enabled
 * and its WIF/KMS configuration is supplied.
 */
@Configuration(proxyBeanMethods = false)
@Profile("gcp-cvm")
public class GcpConfidentialGatewayConfiguration {
    @Bean
    public GcpAttestationTokenSource gcpAttestationTokenSource(
            @Value("${confidential.gcp.attestation.gotpm-path}") Path gotpmPath,
            @Value("${confidential.gcp.attestation.event-log-path}") Path eventLogPath,
            @Value("${confidential.gcp.attestation.hardware-model}") String hardwareModel) {
        String teeTechnology = switch (GcpAttestationPolicy.HardwareModel.valueOf(hardwareModel)) {
            case AMD_SEV -> "";
            case INTEL_TDX -> "tdx";
        };
        return new GoTpmGcpAttestationTokenSource(
                gotpmPath, teeTechnology, eventLogPath, Duration.ofSeconds(45));
    }

    @Bean
    public GcpHttpTransport gcpHttpTransport() {
        return new JavaGcpHttpTransport(Duration.ofSeconds(3));
    }

    @Bean
    public GcpAttestationPolicy gcpAttestationPolicy(
            @Value("${confidential.gcp.attestation.audience}") String audience,
            @Value("${confidential.gcp.attestation.hardware-model}") String hardwareModel,
            @Value("${confidential.gcp.attestation.allowed-projects}") String projects,
            @Value("${confidential.gcp.attestation.allowed-zones}") String zones,
            @Value("${confidential.gcp.attestation.allowed-instances}") String instances,
            @Value("${confidential.gcp.attestation.expected-image-digest:}")
                    String expectedImageDigest,
            @Value("${confidential.gateway.enabled:false}") boolean gatewayEnabled) {
        if (gatewayEnabled && (expectedImageDigest == null || expectedImageDigest.isBlank())) {
            throw new IllegalStateException(
                    "The GCP confidential gateway requires a pinned Confidential Space workload image digest.");
        }
        return new GcpAttestationPolicy(
                audience,
                GcpAttestationPolicy.HardwareModel.valueOf(hardwareModel),
                csv(projects),
                csv(zones),
                csv(instances),
                expectedImageDigest);
    }

    @Bean
    public GcpAttestationJwtDecoder gcpAttestationJwtDecoder(
            GcpHttpTransport transport,
            ObjectMapper objectMapper) {
        return new GoogleGcaJwtDecoder(transport, objectMapper);
    }

    @Bean
    public GcpGcaAttestationVerifier gcpGcaAttestationVerifier(
            GcpAttestationTokenSource tokenSource,
            GcpAttestationJwtDecoder decoder,
            GcpAttestationPolicy policy) {
        return new GcpGcaAttestationVerifier(
                tokenSource, decoder, policy, Clock.systemUTC(), new SecureRandom());
    }

    @Bean
    public ConfidentialRuntimeVerifier gcpConfidentialRuntimeVerifier(
            GcpGcaAttestationVerifier attestationVerifier) {
        return new GcpConfidentialRuntimeVerifier(attestationVerifier);
    }

    @Bean
    @ConditionalOnProperty(name = "confidential.gateway.enabled", havingValue = "true")
    public SecureContextKeyProvider gcpSecureContextKeyProvider(
            GcpGcaAttestationVerifier attestationVerifier,
            GcpHttpTransport transport,
            ObjectMapper objectMapper,
            @Value("${confidential.gcp.wif.audience}") String wifAudience,
            @Value("${confidential.gcp.kms.key-resource}") String keyResource,
            @Value("${confidential.gcp.kms.context-key-id}") String contextKeyId,
            @Value("${confidential.gcp.kms.ciphertext-base64}") String ciphertext) {
        return new GcpWifKmsSecureContextKeyProvider(
                attestationVerifier,
                transport,
                objectMapper,
                wifAudience,
                keyResource,
                contextKeyId,
                ciphertext);
    }

    private static Set<String> csv(String value) {
        return Arrays.stream(value.split(","))
                .map(String::trim)
                .filter(item -> !item.isEmpty())
                .collect(Collectors.toUnmodifiableSet());
    }
}package org.opentron.backend.security.confidential.gateway.gcp;

import org.opentron.backend.security.confidential.ConfidentialRuntimeVerifier;

public final class GcpConfidentialRuntimeVerifier implements ConfidentialRuntimeVerifier {
    private final GcpGcaAttestationVerifier attestationVerifier;

    public GcpConfidentialRuntimeVerifier(GcpGcaAttestationVerifier attestationVerifier) {
        this.attestationVerifier = attestationVerifier;
    }

    @Override
    public void verifyCurrentRuntime() {
        attestationVerifier.attestCurrentRuntime();
    }
}package org.opentron.backend.security.confidential.gateway.gcp;

import java.security.SecureRandom;
import java.math.BigInteger;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Base64;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.springframework.security.oauth2.jwt.Jwt;

/** Produces and validates fresh Google Cloud Attestation evidence against local policy. */
public final class GcpGcaAttestationVerifier {
    static final String GOOGLE_ISSUER = "https://confidentialcomputing.googleapis.com";
    static final String EAT_PROFILE =
            "https://cloud.google.com/confidential-computing/confidential-vm/docs/token-claims";
    private static final Duration CLOCK_SKEW = Duration.ofSeconds(30);
    private static final Duration MAX_TOKEN_LIFETIME = Duration.ofHours(2);
    private static final Duration MAX_TOKEN_AGE = Duration.ofMinutes(10);
    private static final int NONCE_BYTES = 32;
    private static final Set<String> EXPECTED_ENV_OVERRIDES = Set.of(
            "CJAE_RUNTIME_CONFIG_BASE64",
            "CJAE_RUNTIME_CONFIG_SIGNATURE_BASE64");

    private final GcpAttestationTokenSource tokenSource;
    private final GcpAttestationJwtDecoder jwtDecoder;
    private final GcpAttestationPolicy policy;
    private final Clock clock;
    private final SecureRandom secureRandom;

    public GcpGcaAttestationVerifier(
            GcpAttestationTokenSource tokenSource,
            GcpAttestationJwtDecoder jwtDecoder,
            GcpAttestationPolicy policy,
            Clock clock,
            SecureRandom secureRandom) {
        this.tokenSource = tokenSource;
        this.jwtDecoder = jwtDecoder;
        this.policy = policy;
        this.clock = clock;
        this.secureRandom = secureRandom;
    }

    public Jwt attestCurrentRuntime() {
        byte[] random = new byte[NONCE_BYTES];
        secureRandom.nextBytes(random);
        String nonce = Base64.getUrlEncoder().withoutPadding().encodeToString(random);
        java.util.Arrays.fill(random, (byte) 0);
        return attestCurrentRuntime(nonce);
    }

    public Jwt attestCurrentRuntime(String clientChallenge) {
        if (!isClientChallenge(clientChallenge)) {
            reject("Client attestation challenge must be a canonical 256-bit base64url nonce.");
        }
        String token = tokenSource.fetch(policy.audience(), clientChallenge);
        Jwt jwt = jwtDecoder.decode(token);
        if (jwt == null) {
            reject("GCA JWT decoder returned no verified claims.");
        }
        validateClaims(jwt, clientChallenge);
        return jwt;
    }

    private static boolean isClientChallenge(String challenge) {
        if (challenge == null || !challenge.matches("[A-Za-z0-9_-]{43}")) {
            return false;
        }
        try {
            byte[] decoded = Base64.getUrlDecoder().decode(challenge);
            try {
                return decoded.length == NONCE_BYTES
                        && Base64.getUrlEncoder().withoutPadding()
                                .encodeToString(decoded).equals(challenge);
            } finally {
                java.util.Arrays.fill(decoded, (byte) 0);
            }
        } catch (IllegalArgumentException failure) {
            return false;
        }
    }

    private void validateClaims(Jwt jwt, String expectedNonce) {
        if (!GOOGLE_ISSUER.equals(jwt.getClaimAsString("iss"))) {
            reject("GCA issuer does not match the pinned Google issuer.");
        }
        if (!hasAudience(jwt.getClaims().get("aud"), policy.audience())) {
            reject("GCA audience does not match policy.");
        }
        if (!EAT_PROFILE.equals(jwt.getClaimAsString("eat_profile"))) {
            reject("Evidence does not identify the official Google CVM EAT profile.");
        }
        validateTimes(jwt);
        if (!hasExpectedNonce(jwt.getClaims().get("eat_nonce"), expectedNonce)) {
            reject("GCA nonce does not match the fresh request challenge.");
        }
        if (!policy.hardwareModel().claimValue().equals(jwt.getClaimAsString("hwmodel"))) {
            reject("GCA hardware model does not match the selected policy.");
        }
        if (!Boolean.TRUE.equals(jwt.getClaim("secboot"))) {
            reject("GCA evidence does not assert that Secure Boot is enabled.");
        }
        validateLaunchPolicyClaims(jwt);
        validateGceIdentity(jwt);
        validateConfidentialSpaceWorkload(jwt);
    }

    private static void validateLaunchPolicyClaims(Jwt jwt) {
        Object supportAttributes = jwt.getClaims().get("support_attributes");
        if (!(supportAttributes instanceof Collection<?> values)
                || !values.contains("STABLE")) {
            reject("GCA evidence does not assert the STABLE support attribute.");
        }
        validateEnvironmentOverrides(overrideClaim(jwt, "env_override"));
        Object commandOverride = overrideClaim(jwt, "cmd_override");
        if (commandOverride != null
                && !Boolean.FALSE.equals(commandOverride)
                && !(commandOverride instanceof Collection<?> values && values.isEmpty())
                && !(commandOverride instanceof String value && value.isEmpty())) {
            reject("GCA evidence allows an unexpected command override.");
        }
    }

    private static Object overrideClaim(Jwt jwt, String name) {
        Object claim = jwt.getClaims().get(name);
        Map<String, Object> submods = jwt.getClaim("submods");
        Object containerValue = submods == null ? null : submods.get("container");
        Object containerClaim = containerValue instanceof Map<?, ?> container
                ? container.get(name) : null;
        if (claim != null && containerClaim != null && !claim.equals(containerClaim)) {
            reject("GCA evidence contains conflicting " + name + " claims.");
        }
        return claim == null ? containerClaim : claim;
    }

    private static void validateEnvironmentOverrides(Object claim) {
        if (claim == null) {
            return;
        }
        Set<String> values = new HashSet<>();
        if (claim instanceof String value) {
            for (String item : value.split(",", -1)) {
                if (item.isBlank() || !values.add(item)) {
                    reject("GCA evidence contains an invalid environment override claim.");
                }
            }
        } else if (claim instanceof Collection<?> collection) {
            for (Object item : collection) {
                if (!(item instanceof String value) || value.isBlank() || !values.add(value)) {
                    reject("GCA evidence contains an invalid environment override claim.");
                }
            }
        } else {
            reject("GCA evidence contains an invalid environment override claim.");
        }
        if (!EXPECTED_ENV_OVERRIDES.equals(values)) {
            reject("GCA evidence allows unexpected environment overrides.");
        }
    }

    private void validateConfidentialSpaceWorkload(Jwt jwt) {
        if (policy.expectedImageDigest().isBlank()) {
            return;
        }
        if (!"CONFIDENTIAL_SPACE".equals(jwt.getClaimAsString("swname"))
                || !"disabled-since-boot".equals(jwt.getClaimAsString("dbgstat"))) {
            reject("GCA evidence must identify a production Confidential Space image.");
        }
        Map<String, Object> submods = jwt.getClaim("submods");
        Object containerValue = submods == null ? null : submods.get("container");
        if (!(containerValue instanceof Map<?, ?> container)
                || !policy.expectedImageDigest().equals(string(container.get("image_digest")))) {
            reject("GCA workload image digest does not match the pinned production image.");
        }
    }

    private void validateTimes(Jwt jwt) {
        Instant now = clock.instant();
        Instant issuedAt = jwt.getIssuedAt();
        Instant expiresAt = jwt.getExpiresAt();
        Instant notBefore = instantClaim(jwt.getClaims().get("nbf"));
        if (issuedAt == null || expiresAt == null || notBefore == null
                || issuedAt.isAfter(now.plus(CLOCK_SKEW))
                || issuedAt.isBefore(now.minus(MAX_TOKEN_AGE))
                || !expiresAt.isAfter(now.minus(CLOCK_SKEW))
                || !notBefore.isBefore(now.plus(CLOCK_SKEW))
                || !expiresAt.isAfter(issuedAt)
                || Duration.between(issuedAt, expiresAt).compareTo(MAX_TOKEN_LIFETIME) > 0) {
            reject("GCA issue, not-before, or expiration times are invalid or stale.");
        }
    }

    private void validateGceIdentity(Jwt jwt) {
        Map<String, Object> submods = jwt.getClaim("submods");
        if (submods == null || !(submods.get("gce") instanceof Map<?, ?>)) {
            reject("GCA evidence does not contain the required submods.gce identity.");
        }
        Map<?, ?> gce = (Map<?, ?>) submods.get("gce");
        String zone = string(gce.get("zone"));
        String project;
        String instance;
        String expectedSubject;
        if (policy.hardwareModel() == GcpAttestationPolicy.HardwareModel.AMD_SEV) {
            project = string(gce.get("project_id"));
            instance = string(gce.get("instance_name"));
            if (project == null || instance == null) {
                reject("AMD SEV GCA identity is missing project_id or instance_name.");
            }
            expectedSubject = "https://www.googleapis.com/compute/v1/projects/"
                    + project + "/zones/" + zone + "/instances/" + instance;
        } else {
            project = string(gce.get("project_number"));
            instance = string(gce.get("instance_id"));
            if (project == null || instance == null) {
                reject("Intel TDX GCA identity is missing project_number or instance_id.");
            }
            expectedSubject = "//compute.googleapis.com/projects/"
                    + project + "/zones/" + zone + "/instances/" + instance;
        }
        if (zone == null || !policy.allowedZones().contains(zone)
                || !policy.allowedProjects().contains(project)
                || !policy.allowedInstances().contains(instance)
                || !expectedSubject.equals(jwt.getSubject())) {
            reject("GCA project, zone, instance, or subject is outside the allowlist.");
        }
    }

    private static boolean hasAudience(Object claim, String expected) {
        if (claim instanceof String value) {
            return expected.equals(value);
        }
        return claim instanceof List<?> values && values.stream().anyMatch(expected::equals);
    }

    private static boolean hasExpectedNonce(Object claim, String expected) {
        if (claim instanceof String value) {
            return validNonce(value) && expected.equals(value);
        }
        if (!(claim instanceof List<?> values) || values.isEmpty() || values.size() > 6) {
            return false;
        }
        boolean matched = false;
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        for (Object item : values) {
            if (!(item instanceof String value) || !validNonce(value) || !seen.add(value)) {
                return false;
            }
            matched |= expected.equals(value);
        }
        return matched;
    }

    private static boolean validNonce(String nonce) {
        int byteLength = nonce.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;
        return byteLength >= 10 && byteLength <= 74;
    }

    private static String string(Object value) {
        return value instanceof String text && !text.isBlank() ? text : null;
    }

    private static Instant instantClaim(Object value) {
        if (value instanceof Instant instant) {
            return instant;
        }
        if (!(value instanceof Byte || value instanceof Short
                || value instanceof Integer || value instanceof Long
                || value instanceof BigInteger)) {
            return null;
        }
        try {
            long epochSeconds = value instanceof BigInteger integer
                    ? integer.longValueExact() : ((Number) value).longValue();
            return Instant.ofEpochSecond(epochSeconds);
        } catch (RuntimeException e) {
            return null;
        }
    }

    private static void reject(String message) {
        throw new GcpAttestationException(message);
    }
}package org.opentron.backend.security.confidential.gateway.gcp;

import java.net.URI;
import java.time.Duration;
import java.util.Map;

/** Injectable bounded HTTP boundary used for metadata, JWKS, STS, and KMS calls. */
@FunctionalInterface
public interface GcpHttpTransport {
    HttpResponse postOrGet(
            String method,
            URI uri,
            Map<String, String> headers,
            byte[] body,
            Duration timeout,
            int maximumResponseBytes);

    record HttpResponse(int statusCode, byte[] body) {
        public HttpResponse {
            body = body == null ? new byte[0] : body.clone();
        }

        @Override
        public byte[] body() {
            return body.clone();
        }

        public void clear() {
            java.util.Arrays.fill(body, (byte) 0);
        }
    }
}package org.opentron.backend.security.confidential.gateway.gcp;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.net.URI;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.Base64;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.locks.ReentrantLock;
import java.util.regex.Pattern;
import javax.crypto.spec.SecretKeySpec;
import org.opentron.backend.security.confidential.gateway.SecureContextKey;
import org.opentron.backend.security.confidential.gateway.SecureContextKeyProvider;
import org.springframework.security.oauth2.jwt.Jwt;

/**
 * Releases a configured encrypted context DEK only after fresh local GCA
 * validation, then exchanges that exact token through WIF before Cloud KMS decrypt.
 */
public final class GcpWifKmsSecureContextKeyProvider implements SecureContextKeyProvider {
    private static final URI STS_URI = URI.create("https://sts.googleapis.com/v1/token");
    private static final String CLOUD_PLATFORM_SCOPE = "https://www.googleapis.com/auth/cloud-platform";
    private static final String GRANT_TYPE = "urn:ietf:params:oauth:grant-type:token-exchange";
    private static final String SUBJECT_TOKEN_TYPE = "urn:ietf:params:oauth:token-type:jwt";
    private static final String REQUESTED_TOKEN_TYPE =
            "urn:ietf:params:oauth:token-type:access_token";
    private static final int MAX_RESPONSE_BYTES = 64 * 1024;
    private static final Duration REQUEST_TIMEOUT = Duration.ofSeconds(5);
    private static final long KEY_CACHE_TTL_NANOS = Duration.ofSeconds(60).toNanos();
    private static final Pattern KMS_RESOURCE = Pattern.compile(
            "projects/[A-Za-z0-9-]+/locations/[A-Za-z0-9-]+/keyRings/[A-Za-z0-9_-]+/cryptoKeys/[A-Za-z0-9_-]+");
    private static final Pattern WIF_AUDIENCE = Pattern.compile(
            "//iam\\.googleapis\\.com/projects/[0-9]+/locations/global/"
                    + "workloadIdentityPools/[A-Za-z0-9_-]+/providers/[A-Za-z0-9_-]+");

    private final GcpGcaAttestationVerifier attestationVerifier;
    private final GcpHttpTransport transport;
    private final ObjectMapper mapper;
    private final String wifAudience;
    private final String kmsKeyResource;
    private final String contextKeyId;
    private final String ciphertext;
    private final ReentrantLock refreshLock = new ReentrantLock();
    private volatile CachedKey cachedKey;

    public GcpWifKmsSecureContextKeyProvider(
            GcpGcaAttestationVerifier attestationVerifier,
            GcpHttpTransport transport,
            ObjectMapper mapper,
            String wifAudience,
            String kmsKeyResource,
            String contextKeyId,
            String ciphertext) {
        if (wifAudience == null || !WIF_AUDIENCE.matcher(wifAudience).matches()) {
            throw new IllegalArgumentException("A canonical Workload Identity Provider audience is required.");
        }
        if (kmsKeyResource == null || !KMS_RESOURCE.matcher(kmsKeyResource).matches()) {
            throw new IllegalArgumentException("A canonical Cloud KMS CryptoKey resource is required.");
        }
        if (contextKeyId == null || !contextKeyId.matches("[A-Za-z0-9_-]{1,64}")) {
            throw new IllegalArgumentException("Context key identifier is invalid.");
        }
        if (ciphertext == null || ciphertext.isBlank() || ciphertext.length() > MAX_RESPONSE_BYTES) {
            throw new IllegalArgumentException("A bounded pre-encrypted context DEK is required.");
        }
        try {
            if (Base64.getDecoder().decode(ciphertext).length == 0) {
                throw new IllegalArgumentException("Encrypted context DEK is empty.");
            }
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("Encrypted context DEK must be Base64 encoded.", e);
        }
        this.attestationVerifier = attestationVerifier;
        this.transport = transport;
        this.mapper = mapper;
        this.wifAudience = wifAudience;
        this.kmsKeyResource = kmsKeyResource;
        this.contextKeyId = contextKeyId;
        this.ciphertext = ciphertext;
    }

    @Override
    public SecureContextKey currentKey() {
        long now = System.nanoTime();
        CachedKey cached = cachedKey;
        if (cached != null && now - cached.expiresAtNanos() < 0) {
            return cached.key();
        }
        refreshLock.lock();
        try {
            now = System.nanoTime();
            cached = cachedKey;
            if (cached != null && now - cached.expiresAtNanos() < 0) {
                return cached.key();
            }
            SecureContextKey key = releaseCurrentKey();
            cachedKey = new CachedKey(key, System.nanoTime() + KEY_CACHE_TTL_NANOS);
            return key;
        } finally {
            refreshLock.unlock();
        }
    }

    private SecureContextKey releaseCurrentKey() {
        Jwt attestation = attestationVerifier.attestCurrentRuntime();
        String accessToken = exchangeForAccessToken(attestation.getTokenValue());
        byte[] dek = decrypt(accessToken);
        try {
            if (dek.length != 32) {
                throw new GcpAttestationException("Cloud KMS did not return a 256-bit context DEK.");
            }
            return new SecureContextKey(contextKeyId, new SecretKeySpec(dek, "AES"));
        } finally {
            java.util.Arrays.fill(dek, (byte) 0);
        }
    }

    @Override
    public Optional<SecureContextKey> findKey(String id) {
        return contextKeyId.equals(id) ? Optional.of(currentKey()) : Optional.empty();
    }

    private record CachedKey(SecureContextKey key, long expiresAtNanos) {
    }

    private String exchangeForAccessToken(String attestationJwt) {
        String form = "grant_type=" + encode(GRANT_TYPE)
                + "&audience=" + encode(wifAudience)
                + "&requested_token_type=" + encode(REQUESTED_TOKEN_TYPE)
                + "&subject_token_type=" + encode(SUBJECT_TOKEN_TYPE)
                + "&subject_token=" + encode(attestationJwt)
                + "&scope=" + encode(CLOUD_PLATFORM_SCOPE);
        byte[] requestBody = form.getBytes(StandardCharsets.UTF_8);
        try {
            GcpHttpTransport.HttpResponse response = transport.postOrGet(
                    "POST",
                    STS_URI,
                    Map.of(
                            "Content-Type", "application/x-www-form-urlencoded",
                            "Accept", "application/json"),
                    requestBody,
                    REQUEST_TIMEOUT,
                    MAX_RESPONSE_BYTES);
            JsonNode json = parseSuccess(response, "WIF STS token exchange");
            String token = text(json, "access_token");
            String tokenType = text(json, "token_type");
            JsonNode expiresIn = json.get("expires_in");
            if (token == null || token.length() > 16_384 || !"Bearer".equalsIgnoreCase(tokenType)
                    || expiresIn == null || !expiresIn.canConvertToInt()
                    || expiresIn.intValue() < 1 || expiresIn.intValue() > 3600) {
                throw new GcpAttestationException("WIF STS returned an invalid access token.");
            }
            return token;
        } finally {
            java.util.Arrays.fill(requestBody, (byte) 0);
        }
    }

    private byte[] decrypt(String accessToken) {
        URI uri = URI.create("https://cloudkms.googleapis.com/v1/"
                + kmsKeyResource + ":decrypt");
        byte[] requestBody = ("{\"ciphertext\":\"" + ciphertext + "\"}")
                .getBytes(StandardCharsets.UTF_8);
        try {
            GcpHttpTransport.HttpResponse response = transport.postOrGet(
                    "POST",
                    uri,
                    Map.of(
                            "Authorization", "Bearer " + accessToken,
                            "Content-Type", "application/json",
                            "Accept", "application/json"),
                    requestBody,
                    REQUEST_TIMEOUT,
                    MAX_RESPONSE_BYTES);
            JsonNode json = parseSuccess(response, "Cloud KMS decrypt");
            String encodedPlaintext = text(json, "plaintext");
            if (encodedPlaintext == null || encodedPlaintext.length() > MAX_RESPONSE_BYTES) {
                throw new GcpAttestationException("Cloud KMS returned no bounded plaintext.");
            }
            try {
                return Base64.getDecoder().decode(encodedPlaintext);
            } catch (IllegalArgumentException e) {
                throw new GcpAttestationException("Cloud KMS plaintext is not valid Base64.", e);
            }
        } finally {
            java.util.Arrays.fill(requestBody, (byte) 0);
        }
    }

    private JsonNode parseSuccess(GcpHttpTransport.HttpResponse response, String operation) {
        byte[] body = response.body();
        try {
            if (response.statusCode() != 200) {
                throw new GcpAttestationException(operation + " was rejected.");
            }
            try (JsonParser parser = mapper.getFactory().createParser(body)) {
                parser.enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);
                JsonNode node = mapper.readTree(parser);
                if (node == null || !node.isObject() || parser.nextToken() != null) {
                    throw new GcpAttestationException(operation + " returned invalid JSON.");
                }
                return node;
            } catch (GcpAttestationException e) {
                throw e;
            } catch (Exception e) {
                throw new GcpAttestationException(operation + " returned invalid JSON.", e);
            }
        } finally {
            java.util.Arrays.fill(body, (byte) 0);
            response.clear();
        }
    }

    private static String text(JsonNode node, String name) {
        JsonNode value = node.get(name);
        return value != null && value.isTextual() ? value.textValue() : null;
    }

    private static String encode(String value) {
        return URLEncoder.encode(value, StandardCharsets.UTF_8);
    }
}package org.opentron.backend.security.confidential.gateway.gcp;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.math.BigInteger;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.KeyFactory;
import java.security.Signature;
import java.security.interfaces.RSAPublicKey;
import java.security.spec.RSAPublicKeySpec;
import java.time.Duration;
import java.time.Instant;
import java.util.Base64;
import java.util.Map;
import java.util.regex.Pattern;
import org.springframework.security.oauth2.jwt.Jwt;

/** Verifies RS256 signatures against Google's pinned GCA issuer JWKS URI. */
public final class GoogleGcaJwtDecoder implements GcpAttestationJwtDecoder {
    static final URI GOOGLE_GCA_JWKS_URI = URI.create(
            "https://www.googleapis.com/service_accounts/v1/metadata/jwk/"
                    + "signer@confidentialspace-sign.iam.gserviceaccount.com");
    private static final int MAX_JWT_BYTES = 64 * 1024;
    private static final int MAX_JWKS_BYTES = 256 * 1024;
    private static final Duration REQUEST_TIMEOUT = Duration.ofSeconds(4);
    private static final Pattern KEY_ID = Pattern.compile("[A-Za-z0-9_-]{1,128}");

    private final GcpHttpTransport transport;
    private final ObjectMapper mapper;

    public GoogleGcaJwtDecoder(GcpHttpTransport transport, ObjectMapper mapper) {
        this.transport = transport;
        this.mapper = mapper;
    }

    @Override
    public Jwt decode(String compactJwt) {
        if (compactJwt == null || compactJwt.length() > MAX_JWT_BYTES) {
            throw new GcpAttestationException("GCA JWT is missing or oversized.");
        }
        String[] parts = compactJwt.split("\\.", -1);
        if (parts.length != 3 || parts[0].isEmpty() || parts[1].isEmpty() || parts[2].isEmpty()) {
            throw new GcpAttestationException("GCA evidence is not a compact JWT.");
        }
        try {
            JsonNode header = parseSegment(parts[0]);
            if (!"RS256".equals(text(header, "alg"))) {
                throw new GcpAttestationException("GCA JWT algorithm is not the pinned RS256 algorithm.");
            }
            if (header.has("crit") || header.has("jku") || header.has("jwk")
                    || header.has("x5u") || header.has("x5c")
                    || hasUnsupportedHeader(header)) {
                throw new GcpAttestationException("GCA JWT contains unsupported JOSE header parameters.");
            }
            String kid = text(header, "kid");
            if (kid == null || !KEY_ID.matcher(kid).matches()) {
                throw new GcpAttestationException("GCA JWT key identifier is invalid.");
            }
            verifySignature(parts, findKey(kid));

            JsonNode payload = parseSegment(parts[1]);
            Map<String, Object> headers = mapper.convertValue(
                    header, new TypeReference<Map<String, Object>>() {});
            Map<String, Object> claims = mapper.convertValue(
                    payload, new TypeReference<Map<String, Object>>() {});
            Instant issuedAt = epoch(claims.get("iat"));
            Instant expiresAt = epoch(claims.get("exp"));
            if (issuedAt == null || expiresAt == null) {
                throw new GcpAttestationException("GCA JWT is missing valid issue or expiration times.");
            }
            return new Jwt(compactJwt, issuedAt, expiresAt, headers, claims);
        } catch (GcpAttestationException e) {
            throw e;
        } catch (Exception e) {
            throw new GcpAttestationException("GCA JWT signature or encoding is invalid.", e);
        }
    }

    private RSAPublicKey findKey(String keyId) throws Exception {
        GcpHttpTransport.HttpResponse response = transport.postOrGet(
                "GET",
                GOOGLE_GCA_JWKS_URI,
                Map.of("Accept", "application/json"),
                null,
                REQUEST_TIMEOUT,
                MAX_JWKS_BYTES);
        if (response.statusCode() != 200) {
            response.clear();
            throw new GcpAttestationException("Google GCA signing keys could not be retrieved.");
        }
        byte[] jwksBytes = response.body();
        JsonNode keys;
        try {
            keys = parseJson(jwksBytes);
        } finally {
            java.util.Arrays.fill(jwksBytes, (byte) 0);
            response.clear();
        }
        JsonNode key = null;
        for (JsonNode candidate : keys.path("keys")) {
            if (keyId.equals(text(candidate, "kid"))) {
                if (key != null) {
                    throw new GcpAttestationException("Google GCA JWKS contains a duplicate key identifier.");
                }
                key = candidate;
            }
        }
        if (key == null || !"RSA".equals(text(key, "kty"))
                || !"RS256".equals(text(key, "alg"))
                || (text(key, "use") != null && !"sig".equals(text(key, "use")))) {
            throw new GcpAttestationException("No compatible Google GCA signing key was found.");
        }
        BigInteger modulus = unsignedBase64Url(text(key, "n"));
        BigInteger exponent = unsignedBase64Url(text(key, "e"));
        if (modulus.bitLength() < 2048 || modulus.bitLength() > 8192
                || exponent.compareTo(BigInteger.valueOf(3)) < 0 || !exponent.testBit(0)) {
            throw new GcpAttestationException("Google GCA RSA signing key parameters are invalid.");
        }
        return (RSAPublicKey) KeyFactory.getInstance("RSA")
                .generatePublic(new RSAPublicKeySpec(modulus, exponent));
    }

    private JsonNode parseSegment(String segment) throws Exception {
        return parseJson(Base64.getUrlDecoder().decode(segment));
    }

    private JsonNode parseJson(byte[] json) throws Exception {
        try (JsonParser parser = mapper.getFactory().createParser(json)) {
            parser.enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);
            JsonNode node = mapper.readTree(parser);
            if (node == null || !node.isObject() || parser.nextToken() != null) {
                throw new GcpAttestationException("GCA JWT or JWKS must contain one JSON object.");
            }
            return node;
        }
    }

    private static void verifySignature(String[] parts, RSAPublicKey key) throws Exception {
        Signature verifier = Signature.getInstance("SHA256withRSA");
        verifier.initVerify(key);
        verifier.update((parts[0] + "." + parts[1]).getBytes(StandardCharsets.US_ASCII));
        if (!verifier.verify(Base64.getUrlDecoder().decode(parts[2]))) {
            throw new GcpAttestationException("GCA JWT signature is invalid.");
        }
    }

    private static BigInteger unsignedBase64Url(String value) {
        if (value == null || value.isBlank()) {
            throw new GcpAttestationException("Google GCA JWKS RSA key is malformed.");
        }
        return new BigInteger(1, Base64.getUrlDecoder().decode(value));
    }

    private static Instant epoch(Object value) {
        if (!(value instanceof Byte || value instanceof Short
                || value instanceof Integer || value instanceof Long
                || value instanceof BigInteger)) {
            return null;
        }
        try {
            long epochSeconds = value instanceof BigInteger integer
                    ? integer.longValueExact() : ((Number) value).longValue();
            return Instant.ofEpochSecond(epochSeconds);
        } catch (RuntimeException e) {
            return null;
        }
    }

    private static boolean hasUnsupportedHeader(JsonNode header) {
        var fields = header.fieldNames();
        while (fields.hasNext()) {
            String name = fields.next();
            if (!"alg".equals(name) && !"kid".equals(name) && !"typ".equals(name)) {
                return true;
            }
        }
        return false;
    }

    private static String text(JsonNode node, String field) {
        JsonNode value = node.get(field);
        return value != null && value.isTextual() ? value.textValue() : null;
    }
}package org.opentron.backend.security.confidential.gateway.gcp;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.regex.Pattern;

/** Acquires nonce-bound GCA evidence using Google's vTPM attestation tool. */
public final class GoTpmGcpAttestationTokenSource implements GcpAttestationTokenSource {
    private static final int MAX_TOKEN_BYTES = 16 * 1024;
    private static final int MAX_DIAGNOSTIC_BYTES = 32 * 1024;
    private static final Pattern AUDIENCE = Pattern.compile("[^\\p{Cntrl}\\s]{1,2048}");
    private static final Pattern NONCE = Pattern.compile("[A-Za-z0-9_-]{20,64}");
    private static final Pattern COMPACT_JWT = Pattern.compile(
            "[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+");

    private final Path executable;
    private final String teeTechnology;
    private final Path eventLog;
    private final Duration timeout;
    private final CommandExecutor commandExecutor;

    public GoTpmGcpAttestationTokenSource(
            Path executable,
            String teeTechnology,
            Path eventLog,
            Duration timeout) {
        this(executable, teeTechnology, eventLog, timeout, GoTpmGcpAttestationTokenSource::execute);
    }

    GoTpmGcpAttestationTokenSource(
            Path executable,
            String teeTechnology,
            Path eventLog,
            Duration timeout,
            CommandExecutor commandExecutor) {
        this.executable = Objects.requireNonNull(executable, "executable");
        if (teeTechnology == null
                || (!teeTechnology.isEmpty() && !"sev-snp".equals(teeTechnology)
                        && !"tdx".equals(teeTechnology))) {
            throw new IllegalArgumentException("GCA TEE technology must be empty, sev-snp, or tdx.");
        }
        this.eventLog = Objects.requireNonNull(eventLog, "eventLog");
        if (!eventLog.isAbsolute()) {
            throw new IllegalArgumentException("GCA event log path must be absolute.");
        }
        this.teeTechnology = teeTechnology;
        this.timeout = Objects.requireNonNull(timeout, "timeout");
        if (timeout.isZero() || timeout.isNegative() || timeout.compareTo(Duration.ofMinutes(2)) > 0) {
            throw new IllegalArgumentException("GCA token acquisition timeout must be in (0, 2 minutes].");
        }
        this.commandExecutor = Objects.requireNonNull(commandExecutor, "commandExecutor");
    }

    @Override
    public String fetch(String audience, String nonce) {
        if (audience == null || !AUDIENCE.matcher(audience).matches()) {
            throw new GcpAttestationException("GCA audience is missing or invalid.");
        }
        if (nonce == null || !NONCE.matcher(nonce).matches()) {
            throw new GcpAttestationException("GCA nonce is missing or invalid.");
        }
        List<String> command = new ArrayList<>(List.of(
                executable.toString(),
                "token",
                "--audience",
                audience,
                "--custom-nonce",
                nonce,
                "--event-log",
                eventLog.toString()));
        if (!teeTechnology.isEmpty()) {
            command.add("--tee-technology");
            command.add(teeTechnology);
        }
        String token = commandExecutor.execute(command, timeout);
        if (token == null || !COMPACT_JWT.matcher(token).matches()) {
            throw new GcpAttestationException("Google gotpm did not return a compact attestation JWT.");
        }
        return token;
    }

    private static String execute(List<String> command, Duration timeout) {
        Process process;
        try {
            process = new ProcessBuilder(command).start();
        } catch (IOException exception) {
            throw new GcpAttestationException("Unable to start Google's GCA token acquisition tool.", exception);
        }

        byte[] stdout = null;
        byte[] stderr = null;
        try (var readers = Executors.newVirtualThreadPerTaskExecutor()) {
            var stdoutFuture = readers.submit(() -> readBounded(process.getInputStream(), MAX_TOKEN_BYTES));
            var stderrFuture = readers.submit(() -> readBounded(process.getErrorStream(), MAX_DIAGNOSTIC_BYTES));
            if (!process.waitFor(timeout.toMillis(), TimeUnit.MILLISECONDS)) {
                process.destroyForcibly();
                throw new GcpAttestationException("Google GCA token acquisition timed out.");
            }
            stdout = stdoutFuture.get();
            stderr = stderrFuture.get();
            if (process.exitValue() != 0) {
                throw new GcpAttestationException(
                        "Google GCA token acquisition failed with exit code " + process.exitValue() + ".");
            }
            return new String(stdout, StandardCharsets.US_ASCII).trim();
        } catch (InterruptedException exception) {
            process.destroyForcibly();
            Thread.currentThread().interrupt();
            throw new GcpAttestationException("Google GCA token acquisition was interrupted.", exception);
        } catch (ExecutionException exception) {
            process.destroyForcibly();
            throw new GcpAttestationException("Unable to read Google GCA token acquisition output.", exception);
        } finally {
            if (process.isAlive()) {
                process.destroyForcibly();
            }
            if (stdout != null) {
                Arrays.fill(stdout, (byte) 0);
            }
            if (stderr != null) {
                Arrays.fill(stderr, (byte) 0);
            }
        }
    }

    private static byte[] readBounded(InputStream input, int maximumBytes) throws IOException {
        try (input; ByteArrayOutputStream output = new ByteArrayOutputStream()) {
            byte[] buffer = new byte[4096];
            try {
                int count;
                while ((count = input.read(buffer)) != -1) {
                    if (output.size() + count > maximumBytes) {
                        throw new IOException("GCA command output exceeded its configured limit.");
                    }
                    output.write(buffer, 0, count);
                }
                return output.toByteArray();
            } finally {
                Arrays.fill(buffer, (byte) 0);
            }
        }
    }

    @FunctionalInterface
    interface CommandExecutor {
        String execute(List<String> command, Duration timeout);
    }
}package org.opentron.backend.security.confidential.gateway.gcp;

import java.io.ByteArrayOutputStream;
import java.nio.ByteBuffer;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse.BodyHandler;
import java.net.http.HttpResponse.BodySubscriber;
import java.net.http.HttpResponse.ResponseInfo;
import java.time.Duration;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Flow;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

/** Java HTTP transport with redirect denial, endpoint restrictions, and body bounds. */
public final class JavaGcpHttpTransport implements GcpHttpTransport {
    private final HttpClient client;

    public JavaGcpHttpTransport(Duration connectTimeout) {
        client = HttpClient.newBuilder()
                .connectTimeout(connectTimeout)
                .followRedirects(HttpClient.Redirect.NEVER)
                .build();
    }

    @Override
    public GcpHttpTransport.HttpResponse postOrGet(
            String method,
            URI uri,
            Map<String, String> headers,
            byte[] body,
            Duration timeout,
            int maximumResponseBytes) {
        if (uri == null || !"https".equalsIgnoreCase(uri.getScheme())) {
            throw new GcpAttestationException("External GCP endpoints must use HTTPS.");
        }
        if (maximumResponseBytes < 1 || timeout == null || timeout.isNegative() || timeout.isZero()) {
            throw new IllegalArgumentException("HTTP response bound and timeout must be positive.");
        }
        CompletableFuture<?> pending = null;
        try {
            HttpRequest.Builder builder = HttpRequest.newBuilder(uri).timeout(timeout);
            headers.forEach(builder::header);
            if ("GET".equals(method)) {
                builder.GET();
            } else if ("POST".equals(method)) {
                builder.POST(HttpRequest.BodyPublishers.ofByteArray(body == null ? new byte[0] : body));
            } else {
                throw new IllegalArgumentException("Unsupported HTTP method.");
            }
            var responseFuture = client.sendAsync(
                    builder.build(), boundedBodyHandler(maximumResponseBytes));
            pending = responseFuture;
            var response = responseFuture.get(timeout.toMillis(), TimeUnit.MILLISECONDS);
            byte[] responseBody = response.body();
            try {
                return new GcpHttpTransport.HttpResponse(response.statusCode(), responseBody);
            } finally {
                java.util.Arrays.fill(responseBody, (byte) 0);
            }
        } catch (TimeoutException e) {
            if (pending != null) {
                pending.cancel(true);
            }
            throw new GcpAttestationException("GCP security endpoint request timed out.", e);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new GcpAttestationException("GCP security endpoint request was interrupted.", e);
        } catch (java.util.concurrent.ExecutionException e) {
            throw new GcpAttestationException("GCP security endpoint request failed.", e.getCause());
        }
    }

    private static BodyHandler<byte[]> boundedBodyHandler(int maximumBytes) {
        return (ResponseInfo ignored) -> new BodySubscriber<>() {
            private final CompletableFuture<byte[]> body = new CompletableFuture<>();
            private final WipingByteArrayOutputStream output = new WipingByteArrayOutputStream(
                    Math.min(maximumBytes, 8192));
            private Flow.Subscription subscription;

            @Override
            public java.util.concurrent.CompletionStage<byte[]> getBody() {
                return body;
            }

            @Override
            public void onSubscribe(Flow.Subscription value) {
                subscription = value;
                subscription.request(1);
            }

            @Override
            public void onNext(List<ByteBuffer> buffers) {
                long incoming = buffers.stream().mapToLong(ByteBuffer::remaining).sum();
                if ((long) output.size() + incoming > maximumBytes) {
                    subscription.cancel();
                    output.wipe();
                    body.completeExceptionally(new GcpAttestationException(
                            "GCP security endpoint response exceeded its size limit."));
                    return;
                }
                for (ByteBuffer buffer : buffers) {
                    byte[] chunk = new byte[buffer.remaining()];
                    buffer.get(chunk);
                    output.write(chunk, 0, chunk.length);
                    java.util.Arrays.fill(chunk, (byte) 0);
                }
                subscription.request(1);
            }

            @Override
            public void onError(Throwable error) {
                output.wipe();
                body.completeExceptionally(error);
            }

            @Override
            public void onComplete() {
                body.complete(output.drain());
            }
        };
    }

    private static final class WipingByteArrayOutputStream extends ByteArrayOutputStream {
        private WipingByteArrayOutputStream(int size) {
            super(size);
        }

        private byte[] drain() {
            byte[] result = toByteArray();
            wipe();
            return result;
        }

        private void wipe() {
            java.util.Arrays.fill(buf, (byte) 0);
            reset();
        }
    }
}package org.opentron.backend.security.confidential.gateway.onnx;

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.text.Normalizer;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

final class BertWordPieceTokenizer {
    private static final int MAX_WORD_CODE_POINTS = 100;

    private final Map<String, Integer> vocabulary;
    private final TrieNode wordPieceRoot;
    private final int unknownId;
    private final int classificationId;
    private final int separatorId;
    private final int paddingId;
    private final boolean lowercase;

    BertWordPieceTokenizer(
            Path vocabularyPath,
            Path specialTokensPath,
            boolean lowercase,
            ObjectMapper objectMapper) {
        Objects.requireNonNull(vocabularyPath, "vocabularyPath");
        Objects.requireNonNull(specialTokensPath, "specialTokensPath");
        Objects.requireNonNull(objectMapper, "objectMapper");
        Vocabulary loadedVocabulary = loadVocabulary(vocabularyPath);
        this.vocabulary = loadedVocabulary.ids();
        this.wordPieceRoot = loadedVocabulary.root();
        Map<String, String> specialTokens = loadSpecialTokens(specialTokensPath, objectMapper);
        this.unknownId = requireTokenId(specialTokens.get("unk_token"));
        this.classificationId = requireTokenId(specialTokens.get("cls_token"));
        this.separatorId = requireTokenId(specialTokens.get("sep_token"));
        this.paddingId = requireTokenId(specialTokens.get("pad_token"));
        this.lowercase = lowercase;
    }

    int classificationId() {
        return classificationId;
    }

    int separatorId() {
        return separatorId;
    }

    int paddingId() {
        return paddingId;
    }

    List<Token> tokenize(CharSequence text) {
        Objects.requireNonNull(text, "text");
        List<Token> tokens = new ArrayList<>();
        int wordStart = -1;
        for (int offset = 0; offset < text.length();) {
            int codePoint = Character.codePointAt(text, offset);
            int nextOffset = offset + Character.charCount(codePoint);
            if (isControl(codePoint) || isWhitespace(codePoint)) {
                if (wordStart >= 0) {
                    tokenizeWord(text, wordStart, offset, tokens);
                    wordStart = -1;
                }
            } else if (isPunctuation(codePoint) || isCjk(codePoint)) {
                if (wordStart >= 0) {
                    tokenizeWord(text, wordStart, offset, tokens);
                    wordStart = -1;
                }
                tokenizeWord(text, offset, nextOffset, tokens);
            } else if (wordStart < 0) {
                wordStart = offset;
            }
            offset = nextOffset;
        }
        if (wordStart >= 0) {
            tokenizeWord(text, wordStart, text.length(), tokens);
        }
        return List.copyOf(tokens);
    }

    private int requireTokenId(String token) {
        Integer id = vocabulary.get(token);
        if (token == null || id == null) {
            throw new IllegalStateException(
                    "BERT vocabulary does not contain a required special token.");
        }
        return id;
    }

    private void tokenizeWord(CharSequence text, int start, int end, List<Token> tokens) {
        NormalizedWord word = normalizeWord(text, start, end, lowercase);
        int[] normalized = word.codePoints();

        if (normalized.length == 0) {
            return;
        }
        if (normalized.length > MAX_WORD_CODE_POINTS) {
            tokens.add(new Token(unknownId, start, end));
            return;
        }

        int cursor = 0;
        List<Token> wordPieces = new ArrayList<>();
        while (cursor < normalized.length) {
            TrieNode node = wordPieceRoot;
            if (cursor > 0) {
                node = node.children().get((int) '#');
                if (node != null) {
                    node = node.children().get((int) '#');
                }
            }
            int matchEnd = cursor;
            Integer matchId = null;
            for (int offset = cursor; node != null && offset < normalized.length; offset++) {
                node = node.children().get(normalized[offset]);
                if (node != null && node.tokenId() != null) {
                    matchId = node.tokenId();
                    matchEnd = offset + 1;
                }
            }
            if (matchId == null || matchEnd == cursor) {
                tokens.add(new Token(unknownId, start, end));
                return;
            }
            wordPieces.add(new Token(
                    matchId,
                    word.starts()[cursor],
                    word.ends()[matchEnd - 1],
                    start,
                    end));
            cursor = matchEnd;
        }
        tokens.addAll(wordPieces);
    }

    private static NormalizedWord normalizeWord(
            CharSequence text, int start, int end, boolean lowercase) {
        int capacity = Math.max(1, end - start);
        int[] codePoints = new int[capacity];
        int[] starts = new int[capacity];
        int[] ends = new int[capacity];
        int size = 0;
        for (int offset = start; offset < end;) {
            int codePoint = Character.codePointAt(text, offset);
            int sourceEnd = offset + Character.charCount(codePoint);
            if (codePoint <= 0x7f) {
                int normalizedCodePoint = lowercase
                        ? Character.toLowerCase(codePoint)
                        : codePoint;
                if (size == codePoints.length) {
                    int newCapacity = Math.max(4, codePoints.length * 2);
                    codePoints = java.util.Arrays.copyOf(codePoints, newCapacity);
                    starts = java.util.Arrays.copyOf(starts, newCapacity);
                    ends = java.util.Arrays.copyOf(ends, newCapacity);
                }
                codePoints[size] = normalizedCodePoint;
                starts[size] = offset;
                ends[size] = sourceEnd;
                size++;
            } else {
                String normalizedCharacter = normalize(codePoint, lowercase);
                for (int normalizedOffset = 0;
                        normalizedOffset < normalizedCharacter.length();) {
                    int normalizedCodePoint = normalizedCharacter.codePointAt(normalizedOffset);
                    normalizedOffset += Character.charCount(normalizedCodePoint);
                    if (size == codePoints.length) {
                        int newCapacity = Math.max(4, codePoints.length * 2);
                        codePoints = java.util.Arrays.copyOf(codePoints, newCapacity);
                        starts = java.util.Arrays.copyOf(starts, newCapacity);
                        ends = java.util.Arrays.copyOf(ends, newCapacity);
                    }
                    codePoints[size] = normalizedCodePoint;
                    starts[size] = offset;
                    ends[size] = sourceEnd;
                    size++;
                }
            }
            offset = sourceEnd;
        }
        return new NormalizedWord(
                java.util.Arrays.copyOf(codePoints, size),
                java.util.Arrays.copyOf(starts, size),
                java.util.Arrays.copyOf(ends, size));
    }

    private static String normalize(int codePoint, boolean lowercase) {
        String value = new String(Character.toChars(codePoint));
        if (lowercase) {
            value = value.toLowerCase(Locale.ROOT);
        }
        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
        StringBuilder result = new StringBuilder(decomposed.length());
        decomposed.codePoints()
                .filter(character -> Character.getType(character) != Character.NON_SPACING_MARK)
                .forEach(result::appendCodePoint);
        return result.toString();
    }

    private static Vocabulary loadVocabulary(Path path) {
        if (!Files.isRegularFile(path)) {
            throw new IllegalStateException("Configured BERT vocabulary is missing.");
        }
        Map<String, Integer> vocabulary = new HashMap<>();
        TrieNode root = new TrieNode();
        try (BufferedReader reader = Files.newBufferedReader(path)) {
            String token;
            int id = 0;
            while ((token = reader.readLine()) != null) {
                if (token.isEmpty() || vocabulary.putIfAbsent(token, id) != null) {
                    throw new IllegalStateException("BERT vocabulary contains an empty or duplicate token.");
                }
                TrieNode node = root;
                for (int codePoint : token.codePoints().toArray()) {
                    node = node.children().computeIfAbsent(
                            codePoint, ignored -> new TrieNode());
                }
                node.setTokenId(id);
                id++;
            }
        } catch (IOException exception) {
            throw new IllegalStateException("Unable to read configured BERT vocabulary.", exception);
        }
        if (vocabulary.isEmpty()) {
            throw new IllegalStateException("Configured BERT vocabulary is empty.");
        }
        return new Vocabulary(Map.copyOf(vocabulary), root);
    }

    private static Map<String, String> loadSpecialTokens(Path path, ObjectMapper objectMapper) {
        if (!Files.isRegularFile(path)) {
            throw new IllegalStateException("Configured BERT special-token map is missing.");
        }
        try {
            JsonNode root = objectMapper.readTree(path.toFile());
            Map<String, String> tokens = new HashMap<>();
            for (String name : List.of("unk_token", "cls_token", "sep_token", "pad_token")) {
                JsonNode token = root.get(name);
                if (token == null || !token.isTextual()) {
                    throw new IllegalStateException(
                            "BERT special-token map is missing a required token.");
                }
                tokens.put(name, token.textValue());
            }
            return Map.copyOf(tokens);
        } catch (IOException exception) {
            throw new IllegalStateException("Unable to read configured BERT special-token map.", exception);
        }
    }

    private static boolean isWhitespace(int codePoint) {
        return Character.isWhitespace(codePoint) || Character.isSpaceChar(codePoint);
    }

    private static boolean isControl(int codePoint) {
        int type = Character.getType(codePoint);
        return (type == Character.CONTROL && codePoint != '\t' && codePoint != '\n' && codePoint != '\r')
                || type == Character.FORMAT;
    }

    private static boolean isPunctuation(int codePoint) {
        int type = Character.getType(codePoint);
        return type == Character.CONNECTOR_PUNCTUATION
                || type == Character.DASH_PUNCTUATION
                || type == Character.START_PUNCTUATION
                || type == Character.END_PUNCTUATION
                || type == Character.INITIAL_QUOTE_PUNCTUATION
                || type == Character.FINAL_QUOTE_PUNCTUATION
                || type == Character.OTHER_PUNCTUATION;
    }

    private static boolean isCjk(int codePoint) {
        return (codePoint >= 0x4E00 && codePoint <= 0x9FFF)
                || (codePoint >= 0x3400 && codePoint <= 0x4DBF)
                || (codePoint >= 0x20000 && codePoint <= 0x2A6DF)
                || (codePoint >= 0x2A700 && codePoint <= 0x2B73F)
                || (codePoint >= 0x2B740 && codePoint <= 0x2B81F)
                || (codePoint >= 0x2B820 && codePoint <= 0x2CEAF)
                || (codePoint >= 0xF900 && codePoint <= 0xFAFF)
                || (codePoint >= 0x2F800 && codePoint <= 0x2FA1F);
    }

    record Token(long id, int start, int end, int wordStart, int wordEnd) {
        Token(long id, int start, int end) {
            this(id, start, end, start, end);
        }
    }

    private record Vocabulary(Map<String, Integer> ids, TrieNode root) {
    }

    private record NormalizedWord(int[] codePoints, int[] starts, int[] ends) {
    }

    private static final class TrieNode {
        private final Map<Integer, TrieNode> children = new HashMap<>();
        private Integer tokenId;

        private Map<Integer, TrieNode> children() {
            return children;
        }

        private Integer tokenId() {
            return tokenId;
        }

        private void setTokenId(int tokenId) {
            this.tokenId = tokenId;
        }
    }
}package org.opentron.backend.security.confidential.gateway.onnx;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.LongBuffer;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;
import java.util.concurrent.atomic.AtomicBoolean;

import ai.onnxruntime.NodeInfo;
import ai.onnxruntime.OnnxTensor;
import ai.onnxruntime.OnnxValue;
import ai.onnxruntime.OrtException;
import ai.onnxruntime.OrtSession;
import ai.onnxruntime.TensorInfo;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.opentron.backend.security.confidential.gateway.DetectedEntity;
import org.opentron.backend.security.confidential.gateway.PiiDetector;

public final class OnnxPiiDetector implements PiiDetector, AutoCloseable {
    private final OrtSession session;
    private final BertWordPieceTokenizer tokenizer;
    private final String inputIdsName;
    private final String attentionMaskName;
    private final String tokenTypeIdsName;
    private final String logitsName;
    private final Map<Long, EntityLabel> labels;
    private final int maximumSequenceLength;
    private final int tensorSequenceLength;
    private final int labelCount;
    private final AtomicBoolean closed = new AtomicBoolean();

    OnnxPiiDetector(
            OrtSession session,
            BertWordPieceTokenizer tokenizer,
            String inputIdsName,
            String attentionMaskName,
            String tokenTypeIdsName,
            String logitsName,
            Map<Long, EntityLabel> labels,
            int maximumSequenceLength,
            int tensorSequenceLength,
            int labelCount) {
        this.session = Objects.requireNonNull(session, "session");
        this.tokenizer = Objects.requireNonNull(tokenizer, "tokenizer");
        this.inputIdsName = requireName(inputIdsName, "input IDs");
        this.attentionMaskName = requireName(attentionMaskName, "attention mask");
        this.tokenTypeIdsName = tokenTypeIdsName;
        this.logitsName = requireName(logitsName, "logits");
        if (this.inputIdsName.equals(this.attentionMaskName)
                || this.inputIdsName.equals(this.logitsName)
                || this.attentionMaskName.equals(this.logitsName)
                || this.inputIdsName.equals(this.tokenTypeIdsName)
                || this.attentionMaskName.equals(this.tokenTypeIdsName)
                || this.logitsName.equals(this.tokenTypeIdsName)) {
            throw new IllegalArgumentException("ONNX input and output tensor names must be distinct.");
        }
        this.labels = Map.copyOf(labels);
        if (maximumSequenceLength < 3
                || (tensorSequenceLength > 0 && tensorSequenceLength < maximumSequenceLength)
                || labelCount < 1
                || this.labels.isEmpty()) {
            throw new IllegalArgumentException("ONNX sequence and label configuration is invalid.");
        }
        this.maximumSequenceLength = maximumSequenceLength;
        this.tensorSequenceLength = tensorSequenceLength;
        this.labelCount = labelCount;
    }

    public static OnnxPiiDetector open(
            OnnxPiiModelArtifactVerifier.VerifiedModel model,
            java.nio.file.Path vocabularyPath,
            java.nio.file.Path specialTokensPath,
            boolean lowercase,
            String inputIdsName,
            String attentionMaskName,
            String logitsName,
            String labelJson,
            int maximumSequenceLength,
            ObjectMapper objectMapper) {
        Objects.requireNonNull(model, "model");
        Map<Long, EntityLabel> labels = parseLabels(labelJson, objectMapper);
        try {
            ai.onnxruntime.OrtEnvironment environment =
                    ai.onnxruntime.OrtEnvironment.getEnvironment();
            OrtSession.SessionOptions options = new OrtSession.SessionOptions();
            OrtSession session;
            try {
                session = environment.createSession(model.path().toString(), options);
            } finally {
                options.close();
            }

            try {
                ModelContract contract = validateModelContract(
                        session,
                        inputIdsName,
                        attentionMaskName,
                        logitsName,
                        maximumSequenceLength,
                        labels.size());
                BertWordPieceTokenizer tokenizer = new BertWordPieceTokenizer(
                        vocabularyPath, specialTokensPath, lowercase, objectMapper);
                return new OnnxPiiDetector(
                        session,
                        tokenizer,
                        inputIdsName,
                        attentionMaskName,
                        contract.tokenTypeIdsName(),
                        logitsName,
                        labels,
                        maximumSequenceLength,
                        contract.tensorSequenceLength(),
                        labels.size());
            } catch (RuntimeException exception) {
                session.close();
                throw exception;
            }
        } catch (OrtException exception) {
            throw new IllegalStateException("Unable to initialize the configured ONNX PII model.", exception);
        }
    }

    @Override
    public String version() {
        return "onnx-token-classification-1";
    }

    @Override
    public List<DetectedEntity> detect(CharSequence text) {
        if (text == null) {
            throw new IllegalArgumentException("Text must not be null.");
        }
        if (closed.get()) {
            throw new IllegalStateException("ONNX PII detector is closed.");
        }
        List<BertWordPieceTokenizer.Token> tokens = tokenizer.tokenize(text);
        if (tokens.isEmpty()) {
            return List.of();
        }

        List<DetectedEntity> detected = new ArrayList<>();
        int contentLimit = maximumSequenceLength - 2;
        int overlap = Math.min(64, contentLimit / 4);
        int step = Math.max(1, contentLimit - overlap);
        for (int windowStart = 0; windowStart < tokens.size(); windowStart += step) {
            int windowEnd = Math.min(tokens.size(), windowStart + contentLimit);
            inferWindow(tokens, windowStart, windowEnd, detected);
        }
        return mergeOverlappingEntities(detected);
    }

    @Override
    public void close() {
        if (closed.compareAndSet(false, true)) {
            try {
                session.close();
            } catch (OrtException exception) {
                throw new IllegalStateException("Unable to close ONNX PII model session.", exception);
            }
        }
    }

    private void inferWindow(
            List<BertWordPieceTokenizer.Token> tokens,
            int start,
            int end,
            List<DetectedEntity> detected) {
        int sequenceLength = end - start + 2;
        int tensorLength = tensorSequenceLength > 0
                ? tensorSequenceLength
                : sequenceLength;
        int[] predictedLabels;
        try (DirectLongInput ids = new DirectLongInput(tensorLength);
                DirectLongInput attentionMask = new DirectLongInput(tensorLength);
                DirectLongInput tokenTypeIds = tokenTypeIdsName == null
                        ? null
                        : new DirectLongInput(tensorLength)) {
            ids.fill(tokenizer.paddingId());
            if (tokenTypeIds != null) {
                tokenTypeIds.fill(0);
            }
            ids.put(0, tokenizer.classificationId());
            for (int index = 0; index < sequenceLength; index++) {
                attentionMask.put(index, 1);
            }
            for (int index = start; index < end; index++) {
                ids.put(index - start + 1, tokens.get(index).id());
            }
            ids.put(sequenceLength - 1, tokenizer.separatorId());
            Map<String, OnnxTensor> inputs = new HashMap<>();
            inputs.put(inputIdsName, ids.tensor());
            inputs.put(attentionMaskName, attentionMask.tensor());
            if (tokenTypeIds != null) {
                inputs.put(tokenTypeIdsName, tokenTypeIds.tensor());
            }
            try (OrtSession.Result result = session.run(inputs)) {
                OnnxValue value = result.get(logitsName)
                        .orElseThrow(() -> new IllegalStateException(
                                "Configured ONNX session did not return the logits output."));
                if (!(value instanceof OnnxTensor logits)) {
                    throw new IllegalStateException("ONNX logits output is not a tensor.");
                }
                predictedLabels = readPredictedLabels(logits, tensorLength);
            } catch (OrtException exception) {
                throw new IllegalStateException("ONNX PII inference failed.", exception);
            }
        }
        try {
            collectWindowEntities(tokens, start, end, predictedLabels, detected);
        } finally {
            java.util.Arrays.fill(predictedLabels, -1);
        }
    }

    private int[] readPredictedLabels(OnnxTensor logits, int sequenceLength) {
        TensorInfo info = logits.getInfo();
        long[] shape = info.getShape();
        if (info.type != ai.onnxruntime.OnnxJavaType.FLOAT
                || shape.length != 3
                || shape[0] != 1
                || shape[1] != sequenceLength
                || shape[2] != labelCount) {
            throw new IllegalStateException("ONNX logits tensor does not match the configured output contract.");
        }
        java.nio.FloatBuffer values = logits.getFloatBuffer();
        int[] predictions = new int[sequenceLength];
        for (int token = 0; token < sequenceLength; token++) {
            int bestLabel = 0;
            float bestScore = Float.NEGATIVE_INFINITY;
            int rowOffset = token * labelCount;
            for (int label = 0; label < labelCount; label++) {
                float score = values.get(rowOffset + label);
                if (!Float.isFinite(score)) {
                    throw new IllegalStateException("ONNX logits contain a non-finite value.");
                }
                if (score > bestScore) {
                    bestScore = score;
                    bestLabel = label;
                }
            }
            predictions[token] = bestLabel;
        }
        return predictions;
    }

    private void collectWindowEntities(
            List<BertWordPieceTokenizer.Token> tokens,
            int start,
            int end,
            int[] predictions,
            List<DetectedEntity> output) {
        String activeType = null;
        int entityStart = -1;
        int entityEnd = -1;
        for (int index = 0; index < end - start; index++) {
            EntityLabel label = labels.get((long) predictions[index + 1]);
            if (label == null || label.type() == null) {
                if (activeType != null) {
                    output.add(new DetectedEntity(activeType, entityStart, entityEnd));
                    activeType = null;
                }
                continue;
            }

            BertWordPieceTokenizer.Token token = tokens.get(start + index);
            int tokenStart = token.wordStart();
            int tokenEnd = token.wordEnd();
            boolean continuation = label.continuation()
                    && label.type().equals(activeType);
            if (continuation) {
                entityEnd = Math.max(entityEnd, tokenEnd);
                continue;
            }
            if (activeType != null) {
                output.add(new DetectedEntity(activeType, entityStart, entityEnd));
            }
            activeType = label.type();
            entityStart = tokenStart;
            entityEnd = tokenEnd;
        }
        if (activeType != null) {
            output.add(new DetectedEntity(activeType, entityStart, entityEnd));
        }
    }

    private static List<DetectedEntity> mergeOverlappingEntities(List<DetectedEntity> entities) {
        entities.sort(Comparator.comparingInt(DetectedEntity::start)
                .thenComparingInt(DetectedEntity::end));
        List<DetectedEntity> merged = new ArrayList<>();
        for (DetectedEntity entity : entities) {
            if (!merged.isEmpty()) {
                DetectedEntity previous = merged.get(merged.size() - 1);
                if (entity.start() < previous.end()) {
                    merged.set(merged.size() - 1, new DetectedEntity(
                            previous.type(), previous.start(), Math.max(previous.end(), entity.end())));
                    continue;
                }
            }
            merged.add(entity);
        }
        return List.copyOf(merged);
    }

    private static Map<Long, EntityLabel> parseLabels(String json, ObjectMapper objectMapper) {
        Objects.requireNonNull(json, "labelJson");
        Objects.requireNonNull(objectMapper, "objectMapper");
        try {
            JsonNode root = objectMapper.readTree(json);
            if (root == null || !root.isObject() || root.isEmpty()) {
                throw new IllegalArgumentException("ONNX label mapping must be a non-empty JSON object.");
            }
            Map<Long, EntityLabel> labels = new TreeMap<>();
            for (var entry = root.fields(); entry.hasNext();) {
                Map.Entry<String, JsonNode> field = entry.next();
                long id;
                try {
                    id = Long.parseLong(field.getKey());
                } catch (NumberFormatException exception) {
                    throw new IllegalArgumentException("ONNX label IDs must be non-negative integers.");
                }
                if (id < 0 || !field.getValue().isTextual()) {
                    throw new IllegalArgumentException("ONNX label mapping has an invalid entry.");
                }
                String label = field.getValue().textValue();
                EntityLabel parsed;
                if ("O".equals(label)) {
                    parsed = new EntityLabel(null, false);
                } else if (label.matches("[BI]-[A-Z][A-Z0-9_]{0,63}")) {
                    parsed = new EntityLabel(label.substring(2), label.charAt(0) == 'I');
                } else {
                    throw new IllegalArgumentException("ONNX labels must use O or BIO entity labels.");
                }
                if (labels.putIfAbsent(id, parsed) != null) {
                    throw new IllegalArgumentException("ONNX label mapping contains duplicate IDs.");
                }
            }
            long expected = 0;
            for (long id : labels.keySet()) {
                if (id != expected++) {
                    throw new IllegalArgumentException("ONNX label IDs must be contiguous from zero.");
                }
            }
            return Map.copyOf(labels);
        } catch (java.io.IOException exception) {
            throw new IllegalArgumentException("ONNX label mapping is not valid JSON.", exception);
        }
    }

    private static ModelContract validateModelContract(
            OrtSession session,
            String idsName,
            String maskName,
            String logitsName,
            int maximumSequenceLength,
            int labelCount) {
        try {
            Map<String, NodeInfo> inputs = session.getInputInfo();
            String tokenTypeIdsName = inputs.containsKey("token_type_ids")
                    ? "token_type_ids"
                    : null;
            if (inputs.size() != (tokenTypeIdsName == null ? 2 : 3)
                    || !inputs.containsKey(idsName)
                    || !inputs.containsKey(maskName)
                    || (tokenTypeIdsName != null
                            && (tokenTypeIdsName.equals(idsName) || tokenTypeIdsName.equals(maskName)))) {
                throw new IllegalStateException(
                        "ONNX model inputs must be input_ids and attention_mask, with optional token_type_ids.");
            }
            TensorInfo ids = requireTensorInfo(inputs, idsName);
            TensorInfo mask = requireTensorInfo(inputs, maskName);
            TensorInfo tokenTypeIds = tokenTypeIdsName == null
                    ? null
                    : requireTensorInfo(inputs, tokenTypeIdsName);
            if (ids.type != ai.onnxruntime.OnnxJavaType.INT64
                    || mask.type != ai.onnxruntime.OnnxJavaType.INT64
                    || ids.getShape().length != 2
                    || mask.getShape().length != 2
                    || !supportsSingleBatch(ids.getShape()[0])
                    || !supportsSingleBatch(mask.getShape()[0])
                    || (tokenTypeIds != null
                            && (tokenTypeIds.type != ai.onnxruntime.OnnxJavaType.INT64
                                    || tokenTypeIds.getShape().length != 2
                                    || !supportsSingleBatch(tokenTypeIds.getShape()[0])))) {
                throw new IllegalStateException(
                        "ONNX model must accept rank-two INT64 input_ids, attention_mask, and optional token_type_ids tensors.");
            }
            TensorInfo logits = requireTensorInfo(session.getOutputInfo(), logitsName);
            long[] outputShape = logits.getShape();
            if (logits.type != ai.onnxruntime.OnnxJavaType.FLOAT
                    || outputShape.length != 3
                    || !supportsSingleBatch(outputShape[0])
                    || (outputShape[2] > 0 && outputShape[2] != labelCount)) {
                throw new IllegalStateException(
                        "ONNX model output must be FLOAT32 [batch, sequence, configured labels].");
            }
            validateSequenceDimension(ids.getShape()[1], maximumSequenceLength);
            validateSequenceDimension(mask.getShape()[1], maximumSequenceLength);
            if (tokenTypeIds != null) {
                validateSequenceDimension(tokenTypeIds.getShape()[1], maximumSequenceLength);
            }
            validateSequenceDimension(outputShape[1], maximumSequenceLength);
            long idsLength = ids.getShape()[1];
            long maskLength = mask.getShape()[1];
            long tokenTypeIdsLength = tokenTypeIds == null
                    ? 0
                    : tokenTypeIds.getShape()[1];
            long outputLength = outputShape[1];
            if ((idsLength > 0 && maskLength > 0 && idsLength != maskLength)
                    || (idsLength > 0 && tokenTypeIdsLength > 0 && idsLength != tokenTypeIdsLength)
                    || (maskLength > 0 && tokenTypeIdsLength > 0 && maskLength != tokenTypeIdsLength)
                    || (idsLength > 0 && outputLength > 0 && idsLength != outputLength)
                    || (maskLength > 0 && outputLength > 0 && maskLength != outputLength)
                    || (tokenTypeIdsLength > 0
                            && outputLength > 0
                            && tokenTypeIdsLength != outputLength)) {
                throw new IllegalStateException(
                        "ONNX input and output sequence dimensions do not match.");
            }
            long fixedSequenceLength = idsLength > 0
                    ? idsLength
                    : maskLength > 0
                            ? maskLength
                            : tokenTypeIdsLength > 0 ? tokenTypeIdsLength : outputLength;
            return new ModelContract(
                    fixedSequenceLength > 0 ? Math.toIntExact(fixedSequenceLength) : 0,
                    tokenTypeIdsName);
        } catch (OrtException exception) {
            throw new IllegalStateException("Unable to inspect ONNX model tensor metadata.", exception);
        }
    }

    private static TensorInfo requireTensorInfo(Map<String, NodeInfo> nodes, String name) {
        NodeInfo node = nodes.get(name);
        if (node == null || !(node.getInfo() instanceof TensorInfo tensorInfo)) {
            throw new IllegalStateException("ONNX model is missing configured tensor: " + name);
        }
        return tensorInfo;
    }

    private static void validateSequenceDimension(long dimension, int maximumSequenceLength) {
        if (dimension > 0 && dimension < maximumSequenceLength) {
            throw new IllegalStateException(
                    "Configured ONNX maximum sequence length exceeds the model tensor dimension.");
        }
    }

    private static boolean supportsSingleBatch(long dimension) {
        return dimension <= 0 || dimension == 1;
    }

    private static String requireName(String name, String label) {
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("ONNX " + label + " tensor name must not be blank.");
        }
        return name;
    }

    record EntityLabel(String type, boolean continuation) {
    }

    private record ModelContract(int tensorSequenceLength, String tokenTypeIdsName) {
    }

    private static final class DirectLongInput implements AutoCloseable {
        private final ByteBuffer bytes;
        private final LongBuffer values;
        private final OnnxTensor tensor;

        private DirectLongInput(int length) {
            bytes = ByteBuffer.allocateDirect(Math.multiplyExact(length, Long.BYTES))
                    .order(ByteOrder.nativeOrder());
            values = bytes.asLongBuffer();
            try {
                tensor = OnnxTensor.createTensor(
                        ai.onnxruntime.OrtEnvironment.getEnvironment(),
                        values,
                        new long[] {1, length});
            } catch (OrtException exception) {
                for (int index = 0; index < values.capacity(); index++) {
                    values.put(index, 0L);
                }
                throw new IllegalStateException("Unable to allocate ONNX input tensor.", exception);
            }
        }

        private void put(int index, long value) {
            values.put(index, value);
        }

        private void fill(long value) {
            for (int index = 0; index < values.capacity(); index++) {
                values.put(index, value);
            }
        }

        private OnnxTensor tensor() {
            return tensor;
        }

        @Override
        public void close() {
            try {
                tensor.close();
            } finally {
                for (int index = 0; index < values.capacity(); index++) {
                    values.put(index, 0L);
                }
                bytes.clear();
                while (bytes.hasRemaining()) {
                    bytes.put((byte) 0);
                }
            }
        }
    }
}package org.opentron.backend.security.confidential.gateway.onnx;

import java.io.IOException;
import java.nio.channels.FileChannel;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.Locale;
import java.util.Objects;

import org.opentron.backend.security.confidential.ConfidentialSegment;

public final class OnnxPiiModelArtifactVerifier {
    private static final int SCAN_CHUNK_BYTES = 1024 * 1024;

    private OnnxPiiModelArtifactVerifier() {
    }

    public static VerifiedModel verify(Path modelPath, String expectedSha256) {
        Objects.requireNonNull(modelPath, "modelPath");
        if (expectedSha256 == null || !expectedSha256.matches("[0-9a-fA-F]{64}")) {
            throw new IllegalArgumentException("Expected ONNX model SHA-256 must be 64 hex characters.");
        }

        Path normalizedPath = modelPath.toAbsolutePath().normalize();
        if (!Files.isRegularFile(normalizedPath)) {
            throw new IllegalStateException("Configured ONNX model is missing or not a regular file.");
        }

        try {
            long fileSize = Files.size(normalizedPath);
            if (fileSize == 0) {
                throw new IllegalStateException("Configured ONNX model is empty.");
            }
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            try (FileChannel file = FileChannel.open(normalizedPath, StandardOpenOption.READ);
                    ConfidentialSegment chunk =
                            ConfidentialSegment.allocate(SCAN_CHUNK_BYTES)) {
                long fileOffset = 0;
                while (fileOffset < fileSize) {
                    int remaining = (int) Math.min(SCAN_CHUNK_BYTES, fileSize - fileOffset);
                    int chunkOffset = 0;
                    while (chunkOffset < remaining) {
                        int bytesRead = chunk.readFrom(
                                file,
                                fileOffset + chunkOffset,
                                chunkOffset,
                                remaining - chunkOffset);
                        if (bytesRead <= 0) {
                            throw new IOException("Model file ended while computing its digest.");
                        }
                        chunkOffset += bytesRead;
                    }
                    chunk.updateDigest(digest, 0, remaining);
                    chunk.zeroize();
                    fileOffset += remaining;
                }
            }

            byte[] actualDigest = digest.digest();
            byte[] expectedDigest = HexFormat.of().parseHex(expectedSha256);
            try {
                if (!MessageDigest.isEqual(actualDigest, expectedDigest)) {
                    throw new IllegalStateException(
                            "Configured ONNX model SHA-256 does not match the pinned digest.");
                }
            } finally {
                java.util.Arrays.fill(actualDigest, (byte) 0);
                java.util.Arrays.fill(expectedDigest, (byte) 0);
            }
            return new VerifiedModel(
                    normalizedPath, expectedSha256.toLowerCase(Locale.ROOT), fileSize);
        } catch (NoSuchAlgorithmException exception) {
            throw new IllegalStateException("SHA-256 is unavailable in this Java runtime.", exception);
        } catch (IOException exception) {
            throw new IllegalStateException("Unable to read configured ONNX model.", exception);
        }
    }

    public record VerifiedModel(Path path, String sha256, long sizeBytes) {
        public VerifiedModel {
            Objects.requireNonNull(path, "path");
            Objects.requireNonNull(sha256, "sha256");
            if (sizeBytes < 1) {
                throw new IllegalArgumentException("Verified ONNX model must not be empty.");
            }
        }
    }
}package org.opentron.backend.security.confidential.gateway.onnx;

import java.nio.file.Path;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.opentron.backend.security.confidential.gateway.PiiDetector;
import org.opentron.backend.security.confidential.gateway.CompositePiiDetector;
import org.opentron.backend.security.confidential.gateway.PrototypeRuleBasedPiiDetector;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;
import org.springframework.context.annotation.Primary;

@Configuration(proxyBeanMethods = false)
@Profile("onnx-pii")
public class OnnxPiiModelConfiguration {
    @Bean
    public OnnxPiiModelArtifactVerifier.VerifiedModel verifiedOnnxPiiModel(
            @Value("${confidential.onnx.pii.model-path}") Path modelPath,
            @Value("${confidential.onnx.pii.model-sha256}") String expectedSha256) {
        return OnnxPiiModelArtifactVerifier.verify(modelPath, expectedSha256);
    }

    @Bean(destroyMethod = "close")
    public OnnxPiiDetector onnxPiiDetector(
            OnnxPiiModelArtifactVerifier.VerifiedModel model,
            ObjectMapper objectMapper,
            @Value("${confidential.onnx.pii.vocab-path}") Path vocabularyPath,
            @Value("${confidential.onnx.pii.special-tokens-path}") Path specialTokensPath,
            @Value("${confidential.onnx.pii.lower-case:true}") boolean lowercase,
            @Value("${confidential.onnx.pii.input-ids-name}") String inputIdsName,
            @Value("${confidential.onnx.pii.attention-mask-name}") String attentionMaskName,
            @Value("${confidential.onnx.pii.logits-name}") String logitsName,
            @Value("${confidential.onnx.pii.labels}") String labels,
            @Value("${confidential.onnx.pii.maximum-sequence-length:512}")
                    int maximumSequenceLength) {
        return OnnxPiiDetector.open(
                model,
                vocabularyPath,
                specialTokensPath,
                lowercase,
                inputIdsName,
                attentionMaskName,
                logitsName,
                labels,
                maximumSequenceLength,
                objectMapper);
    }

    @Bean
    @Primary
    public PiiDetector compositeOnnxPiiDetector(OnnxPiiDetector onnxPiiDetector) {
        return new CompositePiiDetector(
                new PrototypeRuleBasedPiiDetector(), onnxPiiDetector);
    }
}package org.opentron.backend.security.confidential.gateway;

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.SecureRandom;
import java.time.Clock;
import java.time.Instant;
import java.util.Arrays;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.opentron.backend.security.confidential.ConfidentialSegment;

public final class AesGcmSecureContextCodec {
    private static final String VERSION = "v3";
    private static final int NONCE_BYTES = 12;
    private static final int TAG_BITS = 128;
    private static final int MAX_CONTEXT_LENGTH = 2_000_000;
    private static final int MAX_MAPPING_COUNT = 10_000;
    private static final int MAX_TOKEN_BYTES = 512;
    private static final long HEADER_BYTES = Long.BYTES + Integer.BYTES;
    private static final long MAPPING_HEADER_BYTES = 2L * Integer.BYTES;
    private static final Base64.Encoder ENCODER = Base64.getUrlEncoder().withoutPadding();
    private static final Base64.Decoder DECODER = Base64.getUrlDecoder();

    private final SecureContextKeyProvider keyProvider;
    private final SecureRandom secureRandom;
    private final Clock clock;

    public AesGcmSecureContextCodec(
            SecureContextKeyProvider keyProvider,
            ObjectMapper objectMapper,
            SecureRandom secureRandom,
            Clock clock) {
        this.keyProvider = Objects.requireNonNull(keyProvider, "keyProvider");
        Objects.requireNonNull(objectMapper, "objectMapper");
        this.secureRandom = Objects.requireNonNull(secureRandom, "secureRandom");
        this.clock = Objects.requireNonNull(clock, "clock");
    }

    public String sealNative(
            String contextBinding,
            Map<String, ConfidentialSegment> tokenMappings,
            Instant expiresAt) {
        validateContextBinding(contextBinding);
        if (tokenMappings == null || expiresAt == null || !expiresAt.isAfter(clock.instant())) {
            throw new IllegalArgumentException("Secure context parameters are invalid.");
        }
        if (tokenMappings.size() > MAX_MAPPING_COUNT) {
            throw new IllegalArgumentException("Secure context has too many mappings.");
        }

        long plaintextSize = HEADER_BYTES;
        for (Map.Entry<String, ConfidentialSegment> entry : tokenMappings.entrySet()) {
            String token = Objects.requireNonNull(entry.getKey(), "token");
            ConfidentialSegment value = Objects.requireNonNull(entry.getValue(), "value");
            long tokenLength = ConfidentialSegment.utf8Length(token);
            if (tokenLength == 0 || tokenLength > MAX_TOKEN_BYTES) {
                throw new IllegalArgumentException("Secure context token is invalid.");
            }
            long entrySize = MAPPING_HEADER_BYTES + tokenLength + value.byteSize();
            if (entrySize > MAX_CONTEXT_LENGTH - plaintextSize) {
                throw new IllegalArgumentException("Secure context exceeds the supported size.");
            }
            plaintextSize += entrySize;
        }

        byte[] nonce = new byte[NONCE_BYTES];
        try (ConfidentialSegment plaintext = ConfidentialSegment.allocate(plaintextSize);
                ConfidentialSegment ciphertext =
                        ConfidentialSegment.allocate(plaintextSize + TAG_BITS / Byte.SIZE)) {
            SecureContextKey key = keyProvider.currentKey();
            secureRandom.nextBytes(nonce);
            plaintext.writeLong(0, expiresAt.toEpochMilli());
            plaintext.writeInt(Long.BYTES, tokenMappings.size());
            long offset = HEADER_BYTES;
            for (Map.Entry<String, ConfidentialSegment> entry : tokenMappings.entrySet()) {
                byte[] tokenBytes = entry.getKey().getBytes(StandardCharsets.UTF_8);
                ConfidentialSegment value = entry.getValue();
                try {
                    plaintext.writeInt(offset, tokenBytes.length);
                    plaintext.writeInt(
                            offset + Integer.BYTES, Math.toIntExact(value.byteSize()));
                    offset += MAPPING_HEADER_BYTES;
                    writeBytes(plaintext, offset, tokenBytes);
                    offset += tokenBytes.length;
                    value.copyTo(plaintext, 0, offset, value.byteSize());
                    offset += value.byteSize();
                } finally {
                    Arrays.fill(tokenBytes, (byte) 0);
                }
            }

            Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
            cipher.init(Cipher.ENCRYPT_MODE, key.key(), new GCMParameterSpec(TAG_BITS, nonce));
            cipher.updateAAD(aad(contextBinding, key.id()));
            ByteBuffer output = ciphertext.memory().asByteBuffer();
            int encryptedLength = cipher.doFinal(
                    plaintext.memory().asByteBuffer(), output);
            ciphertext.truncate(encryptedLength);
            byte[] encryptedBytes = ciphertext.memory().toArray(
                    java.lang.foreign.ValueLayout.JAVA_BYTE);
            try {
                String secureContext = String.join(
                        ".",
                        VERSION,
                        key.id(),
                        ENCODER.encodeToString(nonce),
                        ENCODER.encodeToString(encryptedBytes));
                if (secureContext.length() > MAX_CONTEXT_LENGTH) {
                    throw new IllegalArgumentException(
                            "Secure context exceeds the supported size.");
                }
                return secureContext;
            } finally {
                Arrays.fill(encryptedBytes, (byte) 0);
            }
        } catch (GeneralSecurityException | RuntimeException e) {
            if (e instanceof IllegalArgumentException argumentException) {
                throw argumentException;
            }
            throw new SecureContextException();
        } finally {
            Arrays.fill(nonce, (byte) 0);
        }
    }

    public SecureContextMappings openNative(String contextBinding, String secureContext) {
        validateContextBinding(contextBinding);
        ConfidentialSegment encryptedSegment = null;
        ConfidentialSegment plaintext = null;
        try {
            if (secureContext == null || secureContext.length() > MAX_CONTEXT_LENGTH) {
                throw new SecureContextException();
            }
            String[] parts = secureContext.split("\\.", -1);
            if (parts.length != 4 || !VERSION.equals(parts[0])) {
                throw new SecureContextException();
            }

            Optional<SecureContextKey> key = keyProvider.findKey(parts[1]);
            if (key.isEmpty()) {
                throw new SecureContextException();
            }

            byte[] nonce = DECODER.decode(parts[2]);
            byte[] ciphertext = DECODER.decode(parts[3]);
            try {
                if (nonce.length != NONCE_BYTES || ciphertext.length <= TAG_BITS / 8) {
                    throw new SecureContextException();
                }

                encryptedSegment = ConfidentialSegment.allocate(ciphertext.length);
                writeBytes(encryptedSegment, 0, ciphertext);
                plaintext = ConfidentialSegment.allocate(
                        encryptedSegment.byteSize() - TAG_BITS / Byte.SIZE);
                Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
                cipher.init(
                        Cipher.DECRYPT_MODE,
                        key.get().key(),
                        new GCMParameterSpec(TAG_BITS, nonce));
                cipher.updateAAD(aad(contextBinding, parts[1]));
                int plaintextLength = cipher.doFinal(
                        encryptedSegment.memory().asByteBuffer(),
                        plaintext.memory().asByteBuffer());
                plaintext.truncate(plaintextLength);
                SecureContextMappings mappings = parseMappings(plaintext);
                plaintext = null;
                return mappings;
            } finally {
                Arrays.fill(nonce, (byte) 0);
                Arrays.fill(ciphertext, (byte) 0);
            }
        } catch (GeneralSecurityException | RuntimeException e) {
            throw new SecureContextException();
        } finally {
            if (encryptedSegment != null) {
                encryptedSegment.close();
            }
            if (plaintext != null) {
                plaintext.close();
            }
        }
    }

    private SecureContextMappings parseMappings(ConfidentialSegment plaintext) {
        if (plaintext.byteSize() < HEADER_BYTES) {
            throw new SecureContextException();
        }
        long expiresAtEpochMillis = plaintext.readLong(0);
        Instant expiresAt;
        try {
            expiresAt = Instant.ofEpochMilli(expiresAtEpochMillis);
        } catch (RuntimeException failure) {
            throw new SecureContextException();
        }
        int count = plaintext.readInt(Long.BYTES);
        if (count < 0 || count > MAX_MAPPING_COUNT) {
            throw new SecureContextException();
        }
        Map<String, ConfidentialSegment> mappings = new LinkedHashMap<>();
        long offset = HEADER_BYTES;
        try {
            for (int index = 0; index < count; index++) {
                requireRange(offset, MAPPING_HEADER_BYTES, plaintext.byteSize());
                int tokenLength = plaintext.readInt(offset);
                int valueLength = plaintext.readInt(offset + Integer.BYTES);
                offset += MAPPING_HEADER_BYTES;
                if (tokenLength < 1 || tokenLength > MAX_TOKEN_BYTES || valueLength < 0) {
                    throw new SecureContextException();
                }
                requireRange(offset, (long) tokenLength + valueLength, plaintext.byteSize());
                String token = readToken(plaintext, offset, tokenLength);
                offset += tokenLength;
                ConfidentialSegment value = plaintext.slice(offset, valueLength);
                if (mappings.putIfAbsent(token, value) != null) {
                    value.close();
                    throw new SecureContextException();
                }
                offset += valueLength;
            }
            if (offset != plaintext.byteSize()
                    || !expiresAt.isAfter(clock.instant())) {
                throw new SecureContextException();
            }
            return new SecureContextMappings(plaintext, mappings, expiresAt);
        } catch (RuntimeException failure) {
            closeMappings(mappings);
            throw failure;
        }
    }

    private static String readToken(
            ConfidentialSegment segment, long offset, int length) {
        byte[] bytes = new byte[length];
        try {
            for (int index = 0; index < length; index++) {
                bytes[index] = segment.readByte(offset + index);
            }
            return StandardCharsets.UTF_8.newDecoder().decode(ByteBuffer.wrap(bytes)).toString();
        } catch (java.nio.charset.CharacterCodingException failure) {
            throw new SecureContextException();
        } finally {
            Arrays.fill(bytes, (byte) 0);
        }
    }

    private static void writeBytes(
            ConfidentialSegment destination, long offset, byte[] bytes) {
        for (int index = 0; index < bytes.length; index++) {
            destination.writeByte(offset + index, bytes[index]);
        }
    }

    private static void requireRange(long offset, long length, long capacity) {
        if (offset < 0 || length < 0 || offset > capacity - length) {
            throw new SecureContextException();
        }
    }

    private static void closeMappings(Map<String, ConfidentialSegment> mappings) {
        RuntimeException failure = null;
        for (ConfidentialSegment segment : mappings.values()) {
            try {
                segment.close();
            } catch (RuntimeException closeFailure) {
                if (failure == null) {
                    failure = closeFailure;
                } else {
                    failure.addSuppressed(closeFailure);
                }
            }
        }
        if (failure != null) {
            throw failure;
        }
    }

    private static byte[] aad(String contextBinding, String keyId) {
        return (VERSION + "\u0000" + contextBinding + "\u0000" + keyId)
                .getBytes(StandardCharsets.UTF_8);
    }

    private static void validateContextBinding(String contextBinding) {
        if (contextBinding == null || contextBinding.isBlank()
                || contextBinding.length() > 600) {
            throw new IllegalArgumentException("Secure context binding is invalid.");
        }
    }

    public static final class SecureContextMappings implements AutoCloseable {
        private final ConfidentialSegment plaintext;
        private final Map<String, ConfidentialSegment> values;
        private final Instant expiresAt;
        private boolean closed;

        private SecureContextMappings(
                ConfidentialSegment plaintext,
                Map<String, ConfidentialSegment> values,
                Instant expiresAt) {
            this.plaintext = plaintext;
            this.values = Map.copyOf(values);
            this.expiresAt = expiresAt;
        }

        public Map<String, ConfidentialSegment> values() {
            if (closed) {
                throw new IllegalStateException("Secure context mappings are closed.");
            }
            return values;
        }

        public Instant expiresAt() {
            if (closed) {
                throw new IllegalStateException("Secure context mappings are closed.");
            }
            return expiresAt;
        }

        @Override
        public void close() {
            if (closed) {
                return;
            }
            closed = true;
            try {
                closeMappings(values);
            } finally {
                plaintext.close();
            }
        }
    }
}package org.opentron.backend.security.confidential.gateway;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

public final class CompositePiiDetector implements PiiDetector {
    private final PiiDetector rules;
    private final PiiDetector model;

    public CompositePiiDetector(PiiDetector rules, PiiDetector model) {
        this.rules = Objects.requireNonNull(rules, "rules");
        this.model = Objects.requireNonNull(model, "model");
    }

    @Override
    public String version() {
        return rules.version() + "+" + model.version();
    }

    @Override
    public List<DetectedEntity> detect(CharSequence text) {
        List<DetectedEntity> ruleEntities = rules.detect(text);
        List<DetectedEntity> combined = new ArrayList<>(ruleEntities);
        for (DetectedEntity candidate : model.detect(text)) {
            boolean overlapsRule = ruleEntities.stream().anyMatch(rule ->
                    rule.start() < candidate.end() && rule.end() > candidate.start());
            if (!overlapsRule) {
                combined.add(candidate);
            }
        }
        combined.sort(Comparator.comparingInt(DetectedEntity::start)
                .thenComparingInt(DetectedEntity::end));
        return List.copyOf(combined);
    }
}package org.opentron.backend.security.confidential.gateway;

import java.io.IOException;
import java.io.OutputStream;
import java.security.SecureRandom;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;

import org.opentron.backend.security.confidential.ConfidentialSegment;

public final class ConfidentialGatewayService {
    private static final String TOKEN_PREFIX = "<OJE_";
    private static final String TOKEN_SUFFIX = ">";
    private static final int TOKEN_RANDOM_BYTES = 16;
    private static final int MAX_TEXT_LENGTH = 1_000_000;
    private static final int MAX_BATCH_SEGMENTS = 100;
    private static final int MAX_BATCH_TEXT_LENGTH = 5_000_000;
    private static final int MAX_ENTITIES = 10_000;

    private final PiiDetector piiDetector;
    private final AesGcmSecureContextCodec contextCodec;
    private final Duration contextLifetime;
    private final SecureRandom secureRandom;
    private final Clock clock;
    private final ConfidentialOperationGovernor operationGovernor;
    private final SecureContextConsumptionStore contextConsumptionStore;

    public ConfidentialGatewayService(
            PiiDetector piiDetector,
            AesGcmSecureContextCodec contextCodec,
            Duration contextLifetime,
            SecureRandom secureRandom,
            Clock clock) {
        this(piiDetector, contextCodec, contextLifetime, secureRandom, clock,
                new ConfidentialOperationGovernor(64), (context, expiresAt) -> true);
    }

    public ConfidentialGatewayService(
            PiiDetector piiDetector,
            AesGcmSecureContextCodec contextCodec,
            Duration contextLifetime,
            SecureRandom secureRandom,
            Clock clock,
            ConfidentialOperationGovernor operationGovernor) {
        this(piiDetector, contextCodec, contextLifetime, secureRandom, clock,
                operationGovernor, (context, expiresAt) -> true);
    }

    public ConfidentialGatewayService(
            PiiDetector piiDetector,
            AesGcmSecureContextCodec contextCodec,
            Duration contextLifetime,
            SecureRandom secureRandom,
            Clock clock,
            ConfidentialOperationGovernor operationGovernor,
            SecureContextConsumptionStore contextConsumptionStore) {
        if (contextLifetime == null || contextLifetime.isZero() || contextLifetime.isNegative()) {
            throw new IllegalArgumentException("Secure context lifetime must be positive.");
        }
        this.piiDetector = piiDetector;
        this.contextCodec = contextCodec;
        this.contextLifetime = contextLifetime;
        this.secureRandom = secureRandom;
        this.clock = clock;
        this.operationGovernor = Objects.requireNonNull(operationGovernor, "operationGovernor");
        this.contextConsumptionStore =
                Objects.requireNonNull(contextConsumptionStore, "contextConsumptionStore");
    }

    public SanitizeResult sanitize(String tenantId, String text) {
        if (text == null || text.length() > MAX_TEXT_LENGTH) {
            throw new IllegalArgumentException("Text is missing or exceeds the supported size.");
        }
        return operationGovernor.execute(() -> {
            try (ConfidentialSegment source = ConfidentialSegment.fromUtf8(text)) {
                return sanitizeNativeSegmentWithinPermit(tenantId, source);
            }
        });
    }

    public SanitizeResult sanitize(String tenantId, ConfidentialSegment source) {
        Objects.requireNonNull(source, "source");
        return operationGovernor.execute(
                () -> sanitizeNativeSegmentWithinPermit(tenantId, source));
    }

    public ConfidentialOperationGovernor.Permit acquireOperationPermit() {
        return operationGovernor.acquire();
    }

    public SanitizeResult sanitize(
            String tenantId,
            ConfidentialSegment source,
            ConfidentialOperationGovernor.Permit permit) {
        Objects.requireNonNull(source, "source");
        return operationGovernor.execute(permit,
                () -> sanitizeNativeSegmentWithinPermit(tenantId, source));
    }

    private SanitizeResult sanitizeNativeSegmentWithinPermit(
            String tenantId, ConfidentialSegment source) {
        try (NativeSecretMappings tokenMappings = new NativeSecretMappings()) {
            try (ConfidentialSegment sanitized = sanitizeToNative(source, tokenMappings)) {
                Instant expiresAt = clock.instant().plus(contextLifetime);
                String secureContext = contextCodec.sealNative(
                        tenantId, tokenMappings.values(), expiresAt);
                return new SanitizeResult(
                        sanitized.toUtf8String(), secureContext, piiDetector.version(), expiresAt);
            }
        }
    }

    public void writeSanitizeJson(
            String tenantId,
            ConfidentialSegment source,
            ConfidentialOperationGovernor.Permit permit,
            OutputStream output) throws IOException {
        Objects.requireNonNull(source, "source");
        Objects.requireNonNull(output, "output");
        try {
            operationGovernor.execute(permit, () -> {
                try (NativeSecretMappings tokenMappings = new NativeSecretMappings();
                        ConfidentialSegment sanitized = sanitizeToNative(source, tokenMappings);
                        NativeJsonStringWriter writer = new NativeJsonStringWriter(output)) {
                    Instant expiresAt = clock.instant().plus(contextLifetime);
                    String secureContext = contextCodec.sealNative(
                            tenantId, tokenMappings.values(), expiresAt);
                    writeSanitizeResponseJson(
                            writer, sanitized, secureContext, piiDetector.version(), expiresAt);
                    return null;
                } catch (IOException exception) {
                    throw new GatewayResponseWriteException(exception);
                }
            });
        } catch (GatewayResponseWriteException exception) {
            throw exception.ioException();
        }
    }

    public void writeSanitizeBatchJson(
            String tenantId,
            List<ConfidentialSegment> sources,
            ConfidentialOperationGovernor.Permit permit,
            OutputStream output) throws IOException {
        if (sources == null || sources.isEmpty() || sources.size() > MAX_BATCH_SEGMENTS) {
            throw new IllegalArgumentException(
                    "Request must contain between 1 and 100 text segments.");
        }
        Objects.requireNonNull(output, "output");
        try {
            operationGovernor.execute(permit, () -> {
                try (NativeSecretMappings tokenMappings = new NativeSecretMappings();
                        NativeJsonStringWriter writer = new NativeJsonStringWriter(output)) {
                    List<ConfidentialSegment> sanitized = new ArrayList<>(sources.size());
                    long totalCharacters = 0;
                    try {
                        for (ConfidentialSegment source : sources) {
                            NativeUtf8CharSequence text = new NativeUtf8CharSequence(
                                    Objects.requireNonNull(source, "source"));
                            totalCharacters += text.length();
                            if (text.length() > MAX_TEXT_LENGTH
                                    || totalCharacters > MAX_BATCH_TEXT_LENGTH) {
                                throw new IllegalArgumentException(
                                        "Text segments exceed the supported size.");
                            }
                            sanitized.add(sanitizeToNative(source, tokenMappings));
                        }
                        Instant expiresAt = clock.instant().plus(contextLifetime);
                        String secureContext = contextCodec.sealNative(
                                tenantId, tokenMappings.values(), expiresAt);
                        writer.writeAscii("{\"sanitizedSegments\":[");
                        for (int index = 0; index < sanitized.size(); index++) {
                            if (index > 0) {
                                writer.writeAscii(",");
                            }
                            writer.writeJsonString(new NativeUtf8CharSequence(
                                    sanitized.get(index)));
                        }
                        writer.writeAscii("],\"secureContext\":");
                        writer.writeJsonString(secureContext);
                        writer.writeAscii(",\"detectorVersion\":");
                        writer.writeJsonString(piiDetector.version());
                        writer.writeAscii(",\"expiresAt\":");
                        writer.writeJsonString(expiresAt.toString());
                        writer.writeAscii("}");
                        return null;
                    } finally {
                        closeSegments(sanitized);
                    }
                } catch (IOException exception) {
                    throw new GatewayResponseWriteException(exception);
                }
            });
        } catch (GatewayResponseWriteException exception) {
            throw exception.ioException();
        }
    }

    public BatchSanitizeResult sanitizeSegments(String tenantId, List<String> segments) {
        validateSegments(segments);
        return operationGovernor.execute(() -> sanitizeSegmentsWithinPermit(tenantId, segments));
    }

    public BatchSanitizeResult sanitizeNativeSegments(
            String tenantId, List<ConfidentialSegment> segments) {
        if (segments == null || segments.isEmpty() || segments.size() > MAX_BATCH_SEGMENTS) {
            throw new IllegalArgumentException(
                    "Request must contain between 1 and 100 text segments.");
        }
        return operationGovernor.execute(
                () -> sanitizeNativeSegmentsWithinPermit(tenantId, segments));
    }

    public BatchSanitizeResult sanitizeNativeSegments(
            String tenantId,
            List<ConfidentialSegment> segments,
            ConfidentialOperationGovernor.Permit permit) {
        if (segments == null || segments.isEmpty() || segments.size() > MAX_BATCH_SEGMENTS) {
            throw new IllegalArgumentException(
                    "Request must contain between 1 and 100 text segments.");
        }
        return operationGovernor.execute(permit,
                () -> sanitizeNativeSegmentsWithinPermit(tenantId, segments));
    }

    private BatchSanitizeResult sanitizeNativeSegmentsWithinPermit(
            String tenantId, List<ConfidentialSegment> segments) {
        try (NativeSecretMappings tokenMappings = new NativeSecretMappings()) {
            List<String> sanitizedSegments = new ArrayList<>(segments.size());
            long totalCharacters = 0;
            for (ConfidentialSegment segment : segments) {
                NativeUtf8CharSequence text = new NativeUtf8CharSequence(
                        Objects.requireNonNull(segment, "segment"));
                totalCharacters += text.length();
                if (text.length() > MAX_TEXT_LENGTH
                        || totalCharacters > MAX_BATCH_TEXT_LENGTH) {
                    throw new IllegalArgumentException(
                            "Text segments exceed the supported size.");
                }
                sanitizedSegments.add(sanitizeText(segment, tokenMappings));
            }
            Instant expiresAt = clock.instant().plus(contextLifetime);
            String secureContext = contextCodec.sealNative(
                    tenantId, tokenMappings.values(), expiresAt);
            return new BatchSanitizeResult(
                    List.copyOf(sanitizedSegments),
                    secureContext,
                    piiDetector.version(),
                    expiresAt);
        }
    }

    private BatchSanitizeResult sanitizeSegmentsWithinPermit(
            String tenantId, List<String> segments) {
        List<ConfidentialSegment> sources = new ArrayList<>(segments.size());
        try {
            try (NativeSecretMappings tokenMappings = new NativeSecretMappings()) {
                List<String> sanitizedSegments = new ArrayList<>(segments.size());
                for (String segment : segments) {
                    ConfidentialSegment source = ConfidentialSegment.fromUtf8(segment);
                    sources.add(source);
                    sanitizedSegments.add(sanitizeText(source, tokenMappings));
                }
                Instant expiresAt = clock.instant().plus(contextLifetime);
                String secureContext = contextCodec.sealNative(
                        tenantId, tokenMappings.values(), expiresAt);
                return new BatchSanitizeResult(
                        List.copyOf(sanitizedSegments),
                        secureContext,
                        piiDetector.version(),
                        expiresAt);
            }
        } finally {
            for (ConfidentialSegment source : sources) {
                source.close();
            }
        }
    }

    public String desanitize(String tenantId, String modelResponse, String secureContext) {
        if (modelResponse == null || modelResponse.length() > MAX_TEXT_LENGTH) {
            throw new IllegalArgumentException("Model response is missing or exceeds the supported size.");
        }
        return operationGovernor.execute(() -> {
            try (ConfidentialSegment response =
                    ConfidentialSegment.fromUtf8(modelResponse)) {
                return desanitizeNativeWithinPermit(tenantId, response, secureContext);
            }
        });
    }

    public String desanitize(
            String tenantId,
            ConfidentialSegment modelResponse,
            String secureContext,
            ConfidentialOperationGovernor.Permit permit) {
        Objects.requireNonNull(modelResponse, "modelResponse");
        return operationGovernor.execute(permit,
                () -> desanitizeNativeWithinPermit(tenantId, modelResponse, secureContext));
    }

    private String desanitizeNativeWithinPermit(
            String tenantId, ConfidentialSegment modelResponse, String secureContext) {
        NativeUtf8CharSequence response = new NativeUtf8CharSequence(modelResponse);
        if (response.length() > MAX_TEXT_LENGTH) {
            throw new IllegalArgumentException(
                    "Model response exceeds the supported size.");
        }
        try (AesGcmSecureContextCodec.SecureContextMappings tokenMappings =
                contextCodec.openNative(tenantId, secureContext)) {
            consumeSecureContext(secureContext, tokenMappings.expiresAt());
            return restoreText(modelResponse, tokenMappings.values());
        }
    }

    public void writeDesanitizeJson(
            String tenantId,
            ConfidentialSegment modelResponse,
            String secureContext,
            ConfidentialOperationGovernor.Permit permit,
            OutputStream output) throws IOException {
        Objects.requireNonNull(modelResponse, "modelResponse");
        Objects.requireNonNull(output, "output");
        try {
            operationGovernor.execute(permit, () -> {
                NativeUtf8CharSequence response = new NativeUtf8CharSequence(modelResponse);
                if (response.length() > MAX_TEXT_LENGTH) {
                    throw new IllegalArgumentException(
                            "Model response exceeds the supported size.");
                }
                try (AesGcmSecureContextCodec.SecureContextMappings tokenMappings =
                                contextCodec.openNative(tenantId, secureContext);
                        NativeJsonStringWriter writer = new NativeJsonStringWriter(output)) {
                    consumeSecureContext(secureContext, tokenMappings.expiresAt());
                    writer.writeAscii("{\"desanitizedText\":");
                    writeRestoredJsonString(writer, response, tokenMappings.values());
                    writer.writeAscii("}");
                    return null;
                } catch (IOException exception) {
                    throw new GatewayResponseWriteException(exception);
                }
            });
        } catch (GatewayResponseWriteException exception) {
            throw exception.ioException();
        }
    }

    public List<String> desanitizeSegments(
            String tenantId, List<String> modelResponses, String secureContext) {
        validateSegments(modelResponses);
        return operationGovernor.execute(() -> {
            try (AesGcmSecureContextCodec.SecureContextMappings tokenMappings =
                    contextCodec.openNative(tenantId, secureContext)) {
                consumeSecureContext(secureContext, tokenMappings.expiresAt());
                List<String> restored = new ArrayList<>(modelResponses.size());
                for (String response : modelResponses) {
                    try (ConfidentialSegment nativeResponse =
                            ConfidentialSegment.fromUtf8(response)) {
                        restored.add(restoreText(nativeResponse, tokenMappings.values()));
                    }
                }
                return List.copyOf(restored);
            }
        });
    }

    public List<String> desanitizeNativeSegments(
            String tenantId,
            List<ConfidentialSegment> modelResponses,
            String secureContext,
            ConfidentialOperationGovernor.Permit permit) {
        if (modelResponses == null || modelResponses.isEmpty()
                || modelResponses.size() > MAX_BATCH_SEGMENTS) {
            throw new IllegalArgumentException(
                    "Request must contain between 1 and 100 text segments.");
        }
        return operationGovernor.execute(permit, () -> {
            long totalCharacters = 0;
            for (ConfidentialSegment response : modelResponses) {
                int length = new NativeUtf8CharSequence(
                        Objects.requireNonNull(response, "modelResponse")).length();
                totalCharacters += length;
                if (length > MAX_TEXT_LENGTH || totalCharacters > MAX_BATCH_TEXT_LENGTH) {
                    throw new IllegalArgumentException(
                            "Model responses exceed the supported size.");
                }
            }
            try (AesGcmSecureContextCodec.SecureContextMappings tokenMappings =
                    contextCodec.openNative(tenantId, secureContext)) {
                consumeSecureContext(secureContext, tokenMappings.expiresAt());
                List<String> restored = new ArrayList<>(modelResponses.size());
                for (ConfidentialSegment response : modelResponses) {
                    restored.add(restoreText(response, tokenMappings.values()));
                }
                return List.copyOf(restored);
            }
        });
    }

    public void writeDesanitizeBatchJson(
            String tenantId,
            List<ConfidentialSegment> modelResponses,
            String secureContext,
            ConfidentialOperationGovernor.Permit permit,
            OutputStream output) throws IOException {
        if (modelResponses == null || modelResponses.isEmpty()
                || modelResponses.size() > MAX_BATCH_SEGMENTS) {
            throw new IllegalArgumentException(
                    "Request must contain between 1 and 100 text segments.");
        }
        Objects.requireNonNull(output, "output");
        try {
            operationGovernor.execute(permit, () -> {
                long totalCharacters = 0;
                List<NativeUtf8CharSequence> responses =
                        new ArrayList<>(modelResponses.size());
                for (ConfidentialSegment response : modelResponses) {
                    NativeUtf8CharSequence text = new NativeUtf8CharSequence(
                            Objects.requireNonNull(response, "modelResponse"));
                    totalCharacters += text.length();
                    if (text.length() > MAX_TEXT_LENGTH
                            || totalCharacters > MAX_BATCH_TEXT_LENGTH) {
                        throw new IllegalArgumentException(
                                "Model responses exceed the supported size.");
                    }
                    responses.add(text);
                }
                try (AesGcmSecureContextCodec.SecureContextMappings tokenMappings =
                                contextCodec.openNative(tenantId, secureContext);
                        NativeJsonStringWriter writer = new NativeJsonStringWriter(output)) {
                    consumeSecureContext(secureContext, tokenMappings.expiresAt());
                    writer.writeAscii("{\"desanitizedResponses\":[");
                    for (int index = 0; index < responses.size(); index++) {
                        if (index > 0) {
                            writer.writeAscii(",");
                        }
                        writeRestoredJsonString(
                                writer, responses.get(index), tokenMappings.values());
                    }
                    writer.writeAscii("]}");
                    return null;
                } catch (IOException exception) {
                    throw new GatewayResponseWriteException(exception);
                }
            });
        } catch (GatewayResponseWriteException exception) {
            throw exception.ioException();
        }
    }

    private String sanitizeText(
            ConfidentialSegment source, NativeSecretMappings tokenMappings) {
        try (ConfidentialSegment sanitized = sanitizeToNative(source, tokenMappings)) {
            return sanitized.toUtf8String();
        }
    }

    private void consumeSecureContext(String secureContext, Instant expiresAt) {
        if (!contextConsumptionStore.consume(secureContext, expiresAt)) {
            throw new SecureContextException();
        }
    }

    private ConfidentialSegment sanitizeToNative(
            ConfidentialSegment source, NativeSecretMappings tokenMappings) {
        NativeUtf8CharSequence text = new NativeUtf8CharSequence(source);
        if (text.length() > MAX_TEXT_LENGTH) {
            throw new IllegalArgumentException("Text is missing or exceeds the supported size.");
        }
        List<DetectedEntity> entities = piiDetector.detect(text);
        validateEntities(text, entities);
        if (tokenMappings.size() + entities.size() > MAX_ENTITIES) {
            throw new IllegalArgumentException("Request contains too many supported entities.");
        }

        int[] utf8Offsets = utf8Offsets(text);
        List<TokenizedEntity> replacements = new ArrayList<>(entities.size());
        long sanitizedSize = source.byteSize();
        for (DetectedEntity entity : entities) {
            if (splitsSurrogatePair(text, entity.start())
                    || splitsSurrogatePair(text, entity.end())) {
                throw new IllegalStateException(
                        "PII detector returned an entity boundary inside a surrogate pair.");
            }
            String token;
            do {
                token = newToken(entity.type());
            } while (contains(text, token) || tokenMappings.containsToken(token));
            tokenMappings.put(token, source.slice(
                    utf8Offsets[entity.start()],
                    utf8Offsets[entity.end()] - utf8Offsets[entity.start()]));
            long tokenByteLength = ConfidentialSegment.utf8Length(token);
            replacements.add(new TokenizedEntity(
                    entity.start(), entity.end(), token, utf8Offsets[entity.start()],
                    utf8Offsets[entity.end()], tokenByteLength));
            sanitizedSize += tokenByteLength
                    - (long) (utf8Offsets[entity.end()] - utf8Offsets[entity.start()]);
        }

        ConfidentialSegment sanitized = ConfidentialSegment.allocate(sanitizedSize);
        try {
            long sourceOffset = 0;
            long targetOffset = 0;
            for (TokenizedEntity replacement : replacements) {
                long unchangedLength = replacement.utf8Start() - sourceOffset;
                source.copyTo(sanitized, sourceOffset, targetOffset, unchangedLength);
                targetOffset += unchangedLength;
                sanitized.writeUtf8(replacement.token(), targetOffset);
                targetOffset += replacement.tokenByteLength();
                sourceOffset = replacement.utf8End();
            }
            source.copyTo(
                    sanitized, sourceOffset, targetOffset, source.byteSize() - sourceOffset);
            return sanitized;
        } catch (RuntimeException | Error failure) {
            sanitized.close();
            throw failure;
        }
    }

    private static void writeSanitizeResponseJson(
            NativeJsonStringWriter writer,
            ConfidentialSegment sanitized,
            String secureContext,
            String detectorVersion,
            Instant expiresAt) throws IOException {
        writer.writeAscii("{\"sanitizedText\":");
        writer.writeJsonString(new NativeUtf8CharSequence(sanitized));
        writer.writeAscii(",\"secureContext\":");
        writer.writeJsonString(secureContext);
        writer.writeAscii(",\"detectorVersion\":");
        writer.writeJsonString(detectorVersion);
        writer.writeAscii(",\"expiresAt\":");
        writer.writeJsonString(expiresAt.toString());
        writer.writeAscii("}");
    }

    private static void closeSegments(List<ConfidentialSegment> segments) {
        RuntimeException failure = null;
        for (ConfidentialSegment segment : segments) {
            try {
                segment.close();
            } catch (RuntimeException closeFailure) {
                if (failure == null) {
                    failure = closeFailure;
                } else {
                    failure.addSuppressed(closeFailure);
                }
            }
        }
        if (failure != null) {
            throw failure;
        }
    }

    private static int[] utf8Offsets(CharSequence text) {
        int[] offsets = new int[text.length() + 1];
        int charOffset = 0;
        int byteOffset = 0;
        while (charOffset < text.length()) {
            char current = text.charAt(charOffset);
            if (Character.isHighSurrogate(current)
                    && charOffset + 1 < text.length()
                    && Character.isLowSurrogate(text.charAt(charOffset + 1))) {
                offsets[charOffset + 1] = byteOffset;
                byteOffset += 4;
                charOffset += 2;
                offsets[charOffset] = byteOffset;
            } else {
                byteOffset += Character.isSurrogate(current)
                        ? 1
                        : current <= 0x7f ? 1 : current <= 0x7ff ? 2 : 3;
                offsets[++charOffset] = byteOffset;
            }
        }
        return offsets;
    }

    private static boolean splitsSurrogatePair(CharSequence text, int charOffset) {
        return charOffset > 0
                && charOffset < text.length()
                && Character.isHighSurrogate(text.charAt(charOffset - 1))
                && Character.isLowSurrogate(text.charAt(charOffset));
    }

    private static String restoreText(
            ConfidentialSegment response, Map<String, ConfidentialSegment> tokenMappings) {
        CharSequence text = new NativeUtf8CharSequence(response);
        StringBuilder restored = new StringBuilder(text.length());
        int cursor = 0;
        while (cursor < text.length()) {
            int tokenStart = indexOf(text, TOKEN_PREFIX, cursor);
            if (tokenStart < 0) {
                append(restored, text, cursor, text.length());
                break;
            }
            int tokenEnd = indexOf(text, TOKEN_SUFFIX, tokenStart + TOKEN_PREFIX.length());
            if (tokenEnd < 0) {
                append(restored, text, cursor, text.length());
                break;
            }

            append(restored, text, cursor, tokenStart);
            String token = text.subSequence(tokenStart, tokenEnd + TOKEN_SUFFIX.length()).toString();
            ConfidentialSegment value = tokenMappings.get(token);
            restored.append(value == null ? token : new NativeUtf8CharSequence(value));
            cursor = tokenEnd + TOKEN_SUFFIX.length();
        }
        return restored.toString();
    }

    private static void writeRestoredJsonString(
            NativeJsonStringWriter writer,
            CharSequence text,
            Map<String, ConfidentialSegment> tokenMappings) throws IOException {
        writer.writeAscii("\"");
        int cursor = 0;
        while (cursor < text.length()) {
            int tokenStart = indexOf(text, TOKEN_PREFIX, cursor);
            if (tokenStart < 0) {
                writer.writeJsonStringContent(text.subSequence(cursor, text.length()));
                break;
            }
            int tokenEnd = indexOf(text, TOKEN_SUFFIX, tokenStart + TOKEN_PREFIX.length());
            if (tokenEnd < 0) {
                writer.writeJsonStringContent(text.subSequence(cursor, text.length()));
                break;
            }
            writer.writeJsonStringContent(text.subSequence(cursor, tokenStart));
            String token = text.subSequence(
                    tokenStart, tokenEnd + TOKEN_SUFFIX.length()).toString();
            ConfidentialSegment value = tokenMappings.get(token);
            if (value == null) {
                writer.writeJsonStringContent(text.subSequence(
                        tokenStart, tokenEnd + TOKEN_SUFFIX.length()));
            } else {
                writer.writeJsonStringContent(new NativeUtf8CharSequence(value));
            }
            cursor = tokenEnd + TOKEN_SUFFIX.length();
        }
        writer.writeAscii("\"");
    }

    private static int indexOf(CharSequence text, String sought, int start) {
        int lastStart = text.length() - sought.length();
        for (int offset = start; offset <= lastStart; offset++) {
            int index = 0;
            while (index < sought.length()
                    && text.charAt(offset + index) == sought.charAt(index)) {
                index++;
            }
            if (index == sought.length()) {
                return offset;
            }
        }
        return -1;
    }

    private static void append(StringBuilder target, CharSequence source, int start, int end) {
        for (int index = start; index < end; index++) {
            target.append(source.charAt(index));
        }
    }

    private static void validateSegments(List<String> segments) {
        if (segments == null || segments.isEmpty() || segments.size() > MAX_BATCH_SEGMENTS) {
            throw new IllegalArgumentException(
                    "Request must contain between 1 and 100 text segments.");
        }
        long totalLength = 0;
        for (String segment : segments) {
            if (segment == null) {
                throw new IllegalArgumentException("Text segments must not be null.");
            }
            totalLength += segment.length();
            if (segment.length() > MAX_TEXT_LENGTH || totalLength > MAX_BATCH_TEXT_LENGTH) {
                throw new IllegalArgumentException("Text segments exceed the supported size.");
            }
        }
    }

    private String newToken(String type) {
        byte[] bytes = new byte[TOKEN_RANDOM_BYTES];
        secureRandom.nextBytes(bytes);
        return TOKEN_PREFIX + type + "_" + java.util.HexFormat.of().formatHex(bytes) + TOKEN_SUFFIX;
    }

    private static void validateEntities(CharSequence text, List<DetectedEntity> entities) {
        if (entities == null) {
            throw new IllegalStateException("PII detector returned no result.");
        }

        int previousEnd = 0;
        for (DetectedEntity entity : entities) {
            if (entity == null || entity.end() > text.length()
                    || entity.start() < previousEnd || entity.end() <= entity.start()) {
                throw new IllegalStateException("PII detector returned invalid entity offsets.");
            }
            previousEnd = entity.end();
        }
    }

    private static boolean contains(CharSequence text, String value) {
        int lastStart = text.length() - value.length();
        for (int start = 0; start <= lastStart; start++) {
            int index = 0;
            while (index < value.length() && text.charAt(start + index) == value.charAt(index)) {
                index++;
            }
            if (index == value.length()) {
                return true;
            }
        }
        return false;
    }

    public record SanitizeResult(
            String sanitizedText,
            String secureContext,
            String detectorVersion,
            Instant expiresAt) {
    }

    public record BatchSanitizeResult(
            List<String> sanitizedSegments,
            String secureContext,
            String detectorVersion,
            Instant expiresAt) {
    }

    private record TokenizedEntity(
            int start, int end, String token, int utf8Start, int utf8End, long tokenByteLength) {
    }

    private static final class GatewayResponseWriteException extends RuntimeException {
        private final IOException ioException;

        private GatewayResponseWriteException(IOException ioException) {
            super(ioException);
            this.ioException = ioException;
        }

        private IOException ioException() {
            return ioException;
        }
    }
}package org.opentron.backend.security.confidential.gateway;

import java.util.Objects;
import java.util.concurrent.Semaphore;
import java.util.function.Supplier;

public final class ConfidentialOperationGovernor {
    private final Semaphore permits;
    private final int maximumConcurrentOperations;

    public ConfidentialOperationGovernor(int maximumConcurrentOperations) {
        if (maximumConcurrentOperations < 1) {
            throw new IllegalArgumentException(
                    "Maximum concurrent confidential operations must be positive.");
        }
        this.maximumConcurrentOperations = maximumConcurrentOperations;
        permits = new Semaphore(maximumConcurrentOperations, true);
    }

    public <T> T execute(Supplier<T> operation) {
        Objects.requireNonNull(operation, "operation");
        try (Permit permit = acquire()) {
            return execute(permit, operation);
        }
    }

    public Permit acquire() {
        try {
            permits.acquire();
        } catch (InterruptedException exception) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException(
                    "Interrupted while waiting for a confidential operation permit.", exception);
        }
        return new Permit(this);
    }

    <T> T execute(Permit permit, Supplier<T> operation) {
        Objects.requireNonNull(operation, "operation");
        if (permit == null || permit.governor != this) {
            throw new IllegalArgumentException("A live permit from this governor is required.");
        }
        return permit.execute(operation);
    }

    public static final class Permit implements AutoCloseable {
        private final ConfidentialOperationGovernor governor;
        private boolean closed;

        private Permit(ConfidentialOperationGovernor governor) {
            this.governor = governor;
        }

        @Override
        public synchronized void close() {
            if (!closed) {
                closed = true;
                governor.permits.release();
            }
        }

        private synchronized <T> T execute(Supplier<T> operation) {
            if (closed) {
                throw new IllegalArgumentException("A live permit from this governor is required.");
            }
            return operation.get();
        }
    }

    public int maximumConcurrentOperations() {
        return maximumConcurrentOperations;
    }
}package org.opentron.backend.security.confidential.gateway;

public record DetectedEntity(String type, int start, int end) {
    public DetectedEntity {
        if (type == null || !type.matches("[A-Z][A-Z0-9_]{0,63}")) {
            throw new IllegalArgumentException("Entity type is invalid.");
        }
        if (start < 0 || end <= start) {
            throw new IllegalArgumentException("Entity offsets are invalid.");
        }
    }
