import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.sql.Timestamp;
import java.time.Clock;
import java.time.Instant;
import java.util.HexFormat;
import java.util.Objects;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;

public final class JdbcSecureContextConsumptionStore
        implements SecureContextConsumptionStore {
    private final JdbcTemplate jdbcTemplate;
    private final Clock clock;

    public JdbcSecureContextConsumptionStore(JdbcTemplate jdbcTemplate, Clock clock) {
        this.jdbcTemplate = Objects.requireNonNull(jdbcTemplate, "jdbcTemplate");
        this.clock = Objects.requireNonNull(clock, "clock");
        jdbcTemplate.execute("""
                CREATE TABLE IF NOT EXISTS confidential_context_consumption (
                    context_hash CHAR(64) PRIMARY KEY,
                    expires_at TIMESTAMP WITH TIME ZONE NOT NULL
                )
                """);
        jdbcTemplate.execute("""
                CREATE INDEX IF NOT EXISTS confidential_context_consumption_expires_at_idx
                ON confidential_context_consumption (expires_at)
                """);
    }

    @Override
    public boolean consume(String secureContext, Instant expiresAt) {
        if (secureContext == null || secureContext.isBlank() || expiresAt == null) {
            throw new IllegalArgumentException("Secure context consumption parameters are invalid.");
        }
        if (!expiresAt.isAfter(clock.instant())) {
            return false;
        }
        String contextHash = sha256(secureContext);
        Timestamp expiration = Timestamp.from(expiresAt);
        jdbcTemplate.update(
                "DELETE FROM confidential_context_consumption WHERE expires_at <= ?",
                Timestamp.from(clock.instant()));
        try {
            jdbcTemplate.update(
                    "INSERT INTO confidential_context_consumption (context_hash, expires_at) "
                            + "VALUES (?, ?)",
                    contextHash,
                    expiration);
            return true;
        } catch (DuplicateKeyException alreadyConsumed) {
            return false;
        }
    }

    private static String sha256(String secureContext) {
        byte[] encoded = secureContext.getBytes(StandardCharsets.UTF_8);
        try {
            return HexFormat.of().formatHex(
                    MessageDigest.getInstance("SHA-256").digest(encoded));
        } catch (NoSuchAlgorithmException impossible) {
            throw new IllegalStateException("SHA-256 is not available.", impossible);
        } finally {
            java.util.Arrays.fill(encoded, (byte) 0);
        }
    }
}package org.opentron.backend.security.confidential.gateway;

import java.io.IOException;
import java.io.OutputStream;
import java.util.Arrays;
import java.util.Objects;

final class NativeJsonStringWriter implements AutoCloseable {
    private static final byte[] HEX = "0123456789abcdef".getBytes(java.nio.charset.StandardCharsets.US_ASCII);

    private final OutputStream output;
    private final byte[] buffer = new byte[4096];
    private int position;

    NativeJsonStringWriter(OutputStream output) {
        this.output = Objects.requireNonNull(output, "output");
    }

    void writeAscii(String value) throws IOException {
        for (int index = 0; index < value.length(); index++) {
            writeByte((byte) value.charAt(index));
        }
    }

    void writeJsonString(CharSequence value) throws IOException {
        writeByte((byte) '"');
        writeJsonStringContent(value);
        writeByte((byte) '"');
    }

    void writeJsonStringContent(CharSequence value) throws IOException {
        for (int index = 0; index < value.length();) {
            char current = value.charAt(index++);
            int codePoint;
            if (Character.isHighSurrogate(current)
                    && index < value.length()
                    && Character.isLowSurrogate(value.charAt(index))) {
                codePoint = Character.toCodePoint(current, value.charAt(index++));
            } else {
                codePoint = current;
            }
            if (codePoint == '"' || codePoint == '\\') {
                writeByte((byte) '\\');
                writeByte((byte) codePoint);
            } else if (codePoint < 0x20) {
                writeByte((byte) '\\');
                writeByte((byte) 'u');
                writeByte((byte) '0');
                writeByte((byte) '0');
                writeByte(HEX[(codePoint >>> 4) & 0x0f]);
                writeByte(HEX[codePoint & 0x0f]);
            } else {
                writeUtf8(codePoint);
            }
        }
    }

    @Override
    public void close() throws IOException {
        try {
            flush();
        } finally {
            Arrays.fill(buffer, (byte) 0);
        }
    }

    private void writeUtf8(int codePoint) throws IOException {
        if (codePoint <= 0x7f) {
            writeByte((byte) codePoint);
        } else if (codePoint <= 0x7ff) {
            writeByte((byte) (0xc0 | (codePoint >>> 6)));
            writeByte((byte) (0x80 | (codePoint & 0x3f)));
        } else if (codePoint <= 0xffff) {
            writeByte((byte) (0xe0 | (codePoint >>> 12)));
            writeByte((byte) (0x80 | ((codePoint >>> 6) & 0x3f)));
            writeByte((byte) (0x80 | (codePoint & 0x3f)));
        } else {
            writeByte((byte) (0xf0 | (codePoint >>> 18)));
            writeByte((byte) (0x80 | ((codePoint >>> 12) & 0x3f)));
            writeByte((byte) (0x80 | ((codePoint >>> 6) & 0x3f)));
            writeByte((byte) (0x80 | (codePoint & 0x3f)));
        }
    }

    private void writeByte(byte value) throws IOException {
        buffer[position++] = value;
        if (position == buffer.length) {
            flush();
        }
    }

    private void flush() throws IOException {
        if (position > 0) {
            int written = position;
            try {
                output.write(buffer, 0, written);
            } finally {
                Arrays.fill(buffer, 0, written, (byte) 0);
                position = 0;
            }
        }
    }
}package org.opentron.backend.security.confidential.gateway;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;

import org.opentron.backend.security.confidential.ConfidentialSegment;

final class NativeSecretMappings implements AutoCloseable {
    private final Map<String, ConfidentialSegment> values = new LinkedHashMap<>();
    private boolean closed;

    void put(String token, ConfidentialSegment value) {
        if (closed) {
            throw new IllegalStateException("Secret mappings are closed.");
        }
        Objects.requireNonNull(token, "token");
        Objects.requireNonNull(value, "value");
        if (values.putIfAbsent(token, value) != null) {
            value.close();
            throw new IllegalArgumentException("Token mapping already exists.");
        }
    }

    int size() {
        if (closed) {
            throw new IllegalStateException("Secret mappings are closed.");
        }
        return values.size();
    }

    boolean containsToken(String token) {
        if (closed) {
            throw new IllegalStateException("Secret mappings are closed.");
        }
        return values.containsKey(token);
    }

    Map<String, ConfidentialSegment> values() {
        if (closed) {
            throw new IllegalStateException("Secret mappings are closed.");
        }
        return Map.copyOf(values);
    }

    @Override
    public void close() {
        if (closed) {
            return;
        }
        closed = true;
        RuntimeException failure = null;
        for (ConfidentialSegment value : values.values()) {
            try {
                value.close();
            } catch (RuntimeException closeFailure) {
                if (failure == null) {
                    failure = closeFailure;
                } else {
                    failure.addSuppressed(closeFailure);
                }
            }
        }
        values.clear();
        if (failure != null) {
            throw failure;
        }
    }
}package org.opentron.backend.security.confidential.gateway;

import java.util.Objects;

import org.opentron.backend.security.confidential.ConfidentialSegment;

public final class NativeUtf8CharSequence implements CharSequence {
    private final ConfidentialSegment segment;
    private final int[] byteOffsets;
    private final int start;
    private final int end;

    public NativeUtf8CharSequence(ConfidentialSegment segment) {
        this(segment, 0, buildOffsets(Objects.requireNonNull(segment, "segment")), -1);
    }

    private NativeUtf8CharSequence(
            ConfidentialSegment segment, int start, int[] byteOffsets, int end) {
        this.segment = segment;
        this.start = start;
        this.end = end < 0 ? byteOffsets.length - 1 : end;
        this.byteOffsets = byteOffsets;
    }

    @Override
    public int length() {
        return end - start;
    }

    @Override
    public char charAt(int index) {
        if (index < 0 || index >= length()) {
            throw new IndexOutOfBoundsException(index);
        }
        int absolute = start + index;
        int codePoint = codePointAt(absolute);
        if (codePoint <= Character.MAX_VALUE) {
            return (char) codePoint;
        }
        return byteOffsets[absolute + 1] == byteOffsets[absolute]
                ? Character.highSurrogate(codePoint)
                : Character.lowSurrogate(codePoint);
    }

    @Override
    public CharSequence subSequence(int beginIndex, int endIndex) {
        if (beginIndex < 0 || endIndex < beginIndex || endIndex > length()) {
            throw new IndexOutOfBoundsException();
        }
        return new NativeUtf8CharSequence(
                segment, start + beginIndex, byteOffsets, start + endIndex);
    }

    @Override
    public String toString() {
        char[] characters = new char[length()];
        for (int index = 0; index < characters.length; index++) {
            characters[index] = charAt(index);
        }
        return new String(characters);
    }

    private int codePointAt(int charOffset) {
        long byteOffset = byteOffsets[charOffset];
        int first = Byte.toUnsignedInt(segment.readByte(byteOffset));
        if (first < 0x80) {
            return first;
        }
        int continuationCount = first < 0xE0 ? 1 : first < 0xF0 ? 2 : 3;
        int codePoint = first & (continuationCount == 1 ? 0x1F
                : continuationCount == 2 ? 0x0F : 0x07);
        for (int index = 1; index <= continuationCount; index++) {
            codePoint = (codePoint << 6)
                    | (Byte.toUnsignedInt(segment.readByte(byteOffset + index)) & 0x3F);
        }
        return codePoint;
    }

    private static int[] buildOffsets(ConfidentialSegment segment) {
        if (segment.byteSize() > Integer.MAX_VALUE - 1) {
            throw new IllegalArgumentException("Native text exceeds supported CharSequence size.");
        }
        int characterCount = 0;
        for (long offset = 0; offset < segment.byteSize();) {
            int first = Byte.toUnsignedInt(segment.readByte(offset));
            int byteCount = utf8Length(first);
            int codePoint = readCodePoint(segment, offset, first, byteCount);
            characterCount += Character.charCount(codePoint);
            offset += byteCount;
        }

        int[] offsets = new int[characterCount + 1];
        int charOffset = 0;
        long byteOffset = 0;
        while (byteOffset < segment.byteSize()) {
            offsets[charOffset++] = Math.toIntExact(byteOffset);
            int first = Byte.toUnsignedInt(segment.readByte(byteOffset));
            int byteCount = utf8Length(first);
            int codePoint = readCodePoint(segment, byteOffset, first, byteCount);
            if (codePoint > Character.MAX_VALUE) {
                offsets[charOffset++] = Math.toIntExact(byteOffset);
            }
            byteOffset += byteCount;
        }
        offsets[charOffset] = Math.toIntExact(byteOffset);
        return java.util.Arrays.copyOf(offsets, charOffset + 1);
    }

    private static int readCodePoint(
            ConfidentialSegment segment, long byteOffset, int first, int byteCount) {
        int codePoint = first & (byteCount == 1 ? 0x7F
                : byteCount == 2 ? 0x1F : byteCount == 3 ? 0x0F : 0x07);
        for (int continuation = 1; continuation < byteCount; continuation++) {
            if (byteOffset + continuation >= segment.byteSize()) {
                throw new IllegalArgumentException("Native text contains incomplete UTF-8.");
            }
            int next = Byte.toUnsignedInt(segment.readByte(byteOffset + continuation));
            if ((next & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Native text contains invalid UTF-8.");
            }
            codePoint = (codePoint << 6) | (next & 0x3F);
        }
        if (!validCodePoint(codePoint, byteCount)) {
            throw new IllegalArgumentException("Native text contains invalid UTF-8.");
        }
        return codePoint;
    }

    private static int utf8Length(int firstByte) {
        if (firstByte < 0x80) {
            return 1;
        }
        if (firstByte >= 0xC2 && firstByte <= 0xDF) {
            return 2;
        }
        if (firstByte >= 0xE0 && firstByte <= 0xEF) {
            return 3;
        }
        if (firstByte >= 0xF0 && firstByte <= 0xF4) {
            return 4;
        }
        throw new IllegalArgumentException("Native text contains invalid UTF-8.");
    }

    private static boolean validCodePoint(int codePoint, int byteCount) {
        return codePoint <= Character.MAX_CODE_POINT
                && (codePoint < 0xD800 || codePoint > 0xDFFF)
                && !(byteCount == 2 && codePoint < 0x80)
                && !(byteCount == 3 && codePoint < 0x800)
                && !(byteCount == 4 && codePoint < 0x10000);
    }
}package org.opentron.backend.security.confidential.gateway;

import java.util.List;

public interface PiiDetector {
    String version();

    List<DetectedEntity> detect(CharSequence text);
}package org.opentron.backend.security.confidential.gateway;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Conservative rules for common contact and structured identifier formats. */
public final class PrototypeRuleBasedPiiDetector implements PiiDetector {
    private static final Pattern EMAIL = Pattern.compile(
            "(?<![\\p{L}\\p{N}.+-])[\\p{L}\\p{N}_!#$%&'*+/=?^`{|}~-]+(?:\\.[\\p{L}\\p{N}_!#$%&'*+/=?^`{|}~-]+)*@[\\p{L}\\p{N}](?:[\\p{L}\\p{N}-]{0,61}[\\p{L}\\p{N}])?(?:\\.[\\p{L}\\p{N}](?:[\\p{L}\\p{N}-]{0,61}[\\p{L}\\p{N}])?)+(?![\\p{L}\\p{N}.-])");
    private static final Pattern SOCIAL_SECURITY_NUMBER = Pattern.compile(
            "(?<!\\d)(?!000|666|9\\d\\d)\\d{3}[- ]?(?!00)\\d{2}[- ]?(?!0000)\\d{4}(?!\\d)");
    private static final Pattern CREDIT_CARD_CANDIDATE = Pattern.compile(
            "(?<!\\d)(?:\\d[ -]?){12,18}\\d(?!\\d)");
    private static final Pattern IBAN_CANDIDATE = Pattern.compile(
            "(?<![A-Z0-9])[A-Z]{2}\\d{2}(?: ?[A-Z0-9]){11,30}(?![A-Z0-9])",
            Pattern.CASE_INSENSITIVE);
    private static final Pattern PHONE_CANDIDATE = Pattern.compile(
            "(?<![\\p{L}\\d])(?:\\+|00)?(?:\\(\\d{1,4}\\)|\\d)(?:[\\d\\s().-]{5,24}\\d)(?![\\p{L}\\d])");

    @Override
    public String version() {
        return "prototype-rules-2";
    }

    @Override
    public List<DetectedEntity> detect(CharSequence text) {
        if (text == null) {
            throw new IllegalArgumentException("Text must not be null.");
        }

        List<DetectedEntity> entities = new ArrayList<>();
        collect(EMAIL.matcher(text), "EMAIL", entities);
        collect(SOCIAL_SECURITY_NUMBER.matcher(text), "SSN", entities);
        collectValidated(CREDIT_CARD_CANDIDATE.matcher(text), "CREDIT_CARD", entities,
                PrototypeRuleBasedPiiDetector::isLuhnValid, text);
        collectValidated(IBAN_CANDIDATE.matcher(text), "IBAN", entities,
                PrototypeRuleBasedPiiDetector::isIbanValid, text);
        collectValidated(PHONE_CANDIDATE.matcher(text), "PHONE_NUMBER", entities,
                (candidate, start, end, existing) -> {
                    int digits = countDigits(candidate, start, end);
                    return digits >= 8 && digits <= 15
                            && existing.stream().noneMatch(entity ->
                                    entity.start() < end && entity.end() > start);
                }, text);
        entities.sort(Comparator.comparingInt(DetectedEntity::start)
                .thenComparingInt(DetectedEntity::end));

        int previousEnd = -1;
        for (DetectedEntity entity : entities) {
            if (entity.start() < previousEnd) {
                throw new IllegalStateException("PII detector returned overlapping entities.");
            }
            previousEnd = entity.end();
        }
        return List.copyOf(entities);
    }

    private static void collect(
            Matcher matcher, String type, List<DetectedEntity> entities) {
        while (matcher.find()) {
            entities.add(new DetectedEntity(type, matcher.start(), matcher.end()));
        }
    }

    private static void collectValidated(
            Matcher matcher,
            String type,
            List<DetectedEntity> entities,
            CandidateValidator validator,
            CharSequence text) {
        while (matcher.find()) {
            int start = matcher.start();
            int end = matcher.end();
            if (validator.isValid(text, start, end, entities)) {
                entities.add(new DetectedEntity(type, start, end));
            }
        }
    }

    private static int countDigits(CharSequence value, int start, int end) {
        int count = 0;
        for (int index = start; index < end; index++) {
            if (Character.isDigit(value.charAt(index))) {
                count++;
            }
        }
        return count;
    }

    private static boolean isLuhnValid(
            CharSequence candidate, int start, int end, List<DetectedEntity> ignored) {
        int checksum = 0;
        int digitPosition = 0;
        for (int index = end - 1; index >= start; index--) {
            char value = candidate.charAt(index);
            if (!Character.isDigit(value)) {
                continue;
            }
            int digit = Character.digit(value, 10);
            if ((digitPosition & 1) == 1) {
                digit *= 2;
                if (digit > 9) {
                    digit -= 9;
                }
            }
            checksum += digit;
            digitPosition++;
        }
        return digitPosition >= 13 && digitPosition <= 19 && checksum % 10 == 0;
    }

    private static boolean isIbanValid(
            CharSequence candidate, int start, int end, List<DetectedEntity> ignored) {
        int length = 0;
        for (int index = start; index < end; index++) {
            if (candidate.charAt(index) != ' ') {
                length++;
            }
        }
        if (length < 15 || length > 34) {
            return false;
        }

        int remainder = 0;
        int position = 0;
        for (int index = 0; index < 4; index++) {
            char value = nextIbanCharacter(candidate, start, end, position++);
            if ((index < 2 && !isAsciiLetter(value))
                    || (index >= 2 && !Character.isDigit(value))) {
                return false;
            }
        }
        for (int index = 4; index < length; index++) {
            char value = nextIbanCharacter(candidate, start, end, position++);
            remainder = appendIbanRemainder(remainder, value);
        }
        for (int index = 0; index < 4; index++) {
            char value = nextIbanCharacter(candidate, start, end, index);
            remainder = appendIbanRemainder(remainder, value);
        }
        return remainder == 1;
    }

    private static int appendIbanRemainder(int remainder, char value) {
        if (Character.isDigit(value)) {
            return (remainder * 10 + Character.digit(value, 10)) % 97;
        }
        if (isAsciiLetter(value)) {
            int expanded = value - 'A' + 10;
            return (remainder * 100 + expanded) % 97;
        }
        throw new IllegalStateException("IBAN candidate contains an invalid character.");
    }

    private static char nextIbanCharacter(
            CharSequence candidate, int start, int end, int position) {
        int current = 0;
        for (int index = start; index < end; index++) {
            char value = candidate.charAt(index);
            if (value == ' ') {
                continue;
            }
            if (current++ == position) {
                return Character.toUpperCase(value);
            }
        }
        throw new IllegalStateException("IBAN candidate offsets are inconsistent.");
    }

    private static boolean isAsciiLetter(char value) {
        return value >= 'A' && value <= 'Z';
    }

    @FunctionalInterface
    private interface CandidateValidator {
        boolean isValid(
                CharSequence candidate, int start, int end, List<DetectedEntity> existing);
    }
}package org.opentron.backend.security.confidential.gateway;

import java.time.Clock;

import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;
import org.springframework.jdbc.core.JdbcTemplate;

@Configuration(proxyBeanMethods = false)
@Profile("gateway-oidc")
@ConditionalOnProperty(name = "confidential.gateway.enabled", havingValue = "true")
public class SecureContextConsumptionConfiguration {
    @Bean
    public SecureContextConsumptionStore secureContextConsumptionStore(
            JdbcTemplate jdbcTemplate) {
        return new JdbcSecureContextConsumptionStore(jdbcTemplate, Clock.systemUTC());
    }
}package org.opentron.backend.security.confidential.gateway;

import java.time.Instant;

@FunctionalInterface
public interface SecureContextConsumptionStore {
    boolean consume(String secureContext, Instant expiresAt);
}package org.opentron.backend.security.confidential.gateway;

public final class SecureContextException extends RuntimeException {
    public SecureContextException() {
        super("Secure context is invalid, expired, or unavailable.");
    }
}package org.opentron.backend.security.confidential.gateway;

import javax.crypto.SecretKey;

public record SecureContextKey(String id, SecretKey key) {
    public SecureContextKey {
        if (id == null || !id.matches("[A-Za-z0-9_-]{1,64}")) {
            throw new IllegalArgumentException("Key identifier is invalid.");
        }
        if (key == null || !"AES".equalsIgnoreCase(key.getAlgorithm())) {
            throw new IllegalArgumentException("An AES key is required.");
        }
    }
}package org.opentron.backend.security.confidential.gateway;

import java.util.Optional;

public interface SecureContextKeyProvider {
    SecureContextKey currentKey();

    Optional<SecureContextKey> findKey(String id);
}package org.opentron.backend.security.confidential;

import java.lang.foreign.Arena;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.CharBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.CodingErrorAction;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Arrays;
import java.util.Objects;

/**
 * Owns UTF-8 bytes in native memory and clears that memory before releasing it.
 */
public final class ConfidentialSegment implements AutoCloseable {
    private final Arena arena;
    private final boolean ownsArena;
    private MemorySegment segment;
    private long byteSize;
    private boolean closed;

    private ConfidentialSegment(Arena arena, MemorySegment segment, long byteSize) {
        this(arena, segment, byteSize, true);
    }

    private ConfidentialSegment(
            Arena arena, MemorySegment segment, long byteSize, boolean ownsArena) {
        this.arena = arena;
        this.segment = segment;
        this.byteSize = byteSize;
        this.ownsArena = ownsArena;
    }

    public static ConfidentialSegment fromUtf8(String value) {
        Objects.requireNonNull(value, "value");
        long byteSize = utf8Length(value);
        Arena arena = Arena.ofConfined();
        MemorySegment segment = null;
        try {
            segment = arena.allocate(byteSize, 1);
            ByteBuffer output = segment.asByteBuffer();
            var encoder = StandardCharsets.UTF_8.newEncoder()
                    .onMalformedInput(CodingErrorAction.REPLACE)
                    .onUnmappableCharacter(CodingErrorAction.REPLACE)
                    .replaceWith(new byte[] {'?'});
            try {
                var encoded = encoder.encode(CharBuffer.wrap(value), output, true);
                if (encoded.isError()) {
                    encoded.throwException();
                }
                var flushed = encoder.flush(output);
                if (flushed.isError()) {
                    flushed.throwException();
                }
            } catch (CharacterCodingException exception) {
                throw new IllegalStateException("Unable to encode UTF-8 into native memory.", exception);
            }
            if (output.position() != byteSize) {
                throw new IllegalStateException("UTF-8 byte length changed during native encoding.");
            }
            return new ConfidentialSegment(arena, segment, byteSize);
        } catch (RuntimeException | Error failure) {
            if (segment != null) {
                segment.fill((byte) 0);
            }
            try {
                arena.close();
            } catch (RuntimeException | Error closeFailure) {
                failure.addSuppressed(closeFailure);
            }
            throw failure;
        }
    }

    public static ConfidentialSegment allocate(long byteSize) {
        if (byteSize < 0) {
            throw new IllegalArgumentException("Segment size must not be negative.");
        }
        Arena arena = Arena.ofConfined();
        try {
            return new ConfidentialSegment(arena, arena.allocate(byteSize, 1), byteSize);
        } catch (RuntimeException | Error failure) {
            try {
                arena.close();
            } catch (RuntimeException | Error closeFailure) {
                failure.addSuppressed(closeFailure);
            }
            throw failure;
        }
    }

    public MemorySegment memory() {
        ensureOpen();
        return segment;
    }

    public long byteSize() {
        ensureOpen();
        return byteSize;
    }

    public ConfidentialSegment slice(long offset, long length) {
        ensureOpen();
        checkRange(offset, length, byteSize);
        return new ConfidentialSegment(arena, segment.asSlice(offset, length), length, false);
    }

    public void truncate(long newByteSize) {
        ensureOpen();
        if (newByteSize < 0 || newByteSize > byteSize) {
            throw new IllegalArgumentException("Truncated segment size is invalid.");
        }
        segment.asSlice(newByteSize, byteSize - newByteSize).fill((byte) 0);
        segment = segment.asSlice(0, newByteSize);
        byteSize = newByteSize;
    }

    public void writeByte(long offset, byte value) {
        ensureOpen();
        checkRange(offset, 1, byteSize);
        segment.set(ValueLayout.JAVA_BYTE, offset, value);
    }

    public byte readByte(long offset) {
        ensureOpen();
        checkRange(offset, 1, byteSize);
        return segment.get(ValueLayout.JAVA_BYTE, offset);
    }

    public void writeInt(long offset, int value) {
        ensureOpen();
        checkRange(offset, Integer.BYTES, byteSize);
        for (int index = 0; index < Integer.BYTES; index++) {
            segment.set(ValueLayout.JAVA_BYTE, offset + index,
                    (byte) (value >>> (index * Byte.SIZE)));
        }
    }

    public int readInt(long offset) {
        ensureOpen();
        checkRange(offset, Integer.BYTES, byteSize);
        int value = 0;
        for (int index = 0; index < Integer.BYTES; index++) {
            value |= Byte.toUnsignedInt(segment.get(ValueLayout.JAVA_BYTE, offset + index))
                    << (index * Byte.SIZE);
        }
        return value;
    }

    public void writeLong(long offset, long value) {
        ensureOpen();
        checkRange(offset, Long.BYTES, byteSize);
        for (int index = 0; index < Long.BYTES; index++) {
            segment.set(ValueLayout.JAVA_BYTE, offset + index,
                    (byte) (value >>> (index * Byte.SIZE)));
        }
    }

    public long readLong(long offset) {
        ensureOpen();
        checkRange(offset, Long.BYTES, byteSize);
        long value = 0;
        for (int index = 0; index < Long.BYTES; index++) {
            value |= (long) Byte.toUnsignedInt(
                    segment.get(ValueLayout.JAVA_BYTE, offset + index))
                    << (index * Byte.SIZE);
        }
        return value;
    }

    public void copyTo(
            ConfidentialSegment target, long sourceOffset, long targetOffset, long length) {
        ensureOpen();
        Objects.requireNonNull(target, "target").ensureOpen();
        checkRange(sourceOffset, length, byteSize);
        checkRange(targetOffset, length, target.byteSize);
        target.segment.asSlice(targetOffset, length)
                .copyFrom(segment.asSlice(sourceOffset, length));
    }

    public int readFrom(
            FileChannel source, long sourceOffset, long targetOffset, int length)
            throws IOException {
        ensureOpen();
        Objects.requireNonNull(source, "source");
        checkRange(targetOffset, length, byteSize);
        if (sourceOffset < 0 || length < 0) {
            throw new IndexOutOfBoundsException("Requested file range is invalid.");
        }
        if (length == 0) {
            return 0;
        }
        MemorySegment destination = segment.asSlice(targetOffset, length);
        destination.fill((byte) 0);
        return source.read(destination.asByteBuffer(), sourceOffset);
    }

    public void updateDigest(MessageDigest digest, long offset, long length) {
        ensureOpen();
        Objects.requireNonNull(digest, "digest");
        checkRange(offset, length, byteSize);
        if (length > Integer.MAX_VALUE) {
            throw new IllegalArgumentException("Digest slice exceeds ByteBuffer capacity.");
        }
        digest.update(segment.asSlice(offset, length).asByteBuffer());
    }

    public void writeUtf8(String value, long targetOffset) {
        ensureOpen();
        Objects.requireNonNull(value, "value");
        long requiredBytes = utf8Length(value);
        checkRange(targetOffset, requiredBytes, byteSize);
        long offset = targetOffset;
        for (int index = 0; index < value.length();) {
            char current = value.charAt(index++);
            int codePoint;
            if (Character.isHighSurrogate(current)
                    && index < value.length()
                    && Character.isLowSurrogate(value.charAt(index))) {
                codePoint = Character.toCodePoint(current, value.charAt(index++));
            } else if (Character.isSurrogate(current)) {
                writeByte(offset++, (byte) '?');
                continue;
            } else {
                codePoint = current;
            }
            if (codePoint <= 0x7f) {
                writeByte(offset++, (byte) codePoint);
            } else if (codePoint <= 0x7ff) {
                writeByte(offset++, (byte) (0xc0 | (codePoint >>> 6)));
                writeByte(offset++, (byte) (0x80 | (codePoint & 0x3f)));
            } else if (codePoint <= 0xffff) {
                writeByte(offset++, (byte) (0xe0 | (codePoint >>> 12)));
                writeByte(offset++, (byte) (0x80 | ((codePoint >>> 6) & 0x3f)));
                writeByte(offset++, (byte) (0x80 | (codePoint & 0x3f)));
            } else {
                writeByte(offset++, (byte) (0xf0 | (codePoint >>> 18)));
                writeByte(offset++, (byte) (0x80 | ((codePoint >>> 12) & 0x3f)));
                writeByte(offset++, (byte) (0x80 | ((codePoint >>> 6) & 0x3f)));
                writeByte(offset++, (byte) (0x80 | (codePoint & 0x3f)));
            }
        }
    }

    public String toUtf8String() {
        ensureOpen();
        byte[] encoded = segment.toArray(ValueLayout.JAVA_BYTE);
        try {
            return new String(encoded, StandardCharsets.UTF_8);
        } finally {
            Arrays.fill(encoded, (byte) 0);
        }
    }

    public static long utf8Length(String value) {
        Objects.requireNonNull(value, "value");
        long length = 0;
        for (int offset = 0; offset < value.length();) {
            char current = value.charAt(offset++);
            if (Character.isHighSurrogate(current)
                    && offset < value.length()
                    && Character.isLowSurrogate(value.charAt(offset))) {
                offset++;
                length += 4;
            } else if (Character.isSurrogate(current) || current <= 0x7f) {
                length++;
            } else if (current <= 0x7ff) {
                length += 2;
            } else {
                length += 3;
            }
        }
        return length;
    }

    public void zeroize() {
        ensureOpen();
        segment.fill((byte) 0);
    }

    @Override
    public void close() {
        if (closed) {
            return;
        }
        segment.fill((byte) 0);
        if (ownsArena) {
            arena.close();
        }
        closed = true;
    }

    private static void checkRange(long offset, long length, long capacity) {
        if (offset < 0 || length < 0 || offset > capacity - length) {
            throw new IndexOutOfBoundsException("Requested range exceeds the segment bounds.");
        }
    }

    private void ensureOpen() {
        if (closed) {
            throw new IllegalStateException("Confidential segment is closed.");
        }
    }
