import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Requires a verified confidential runtime before invoking a Spring-proxied
 * method or any method on a Spring-proxied type carrying this annotation.
 */
@Target({ElementType.METHOD, ElementType.TYPE})
@Retention(RetentionPolicy.RUNTIME)
public @interface ConfidentialAI {
}package org.opentron.backend.security.confidential;

import java.util.List;
import java.util.concurrent.CompletionStage;

import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.reflect.MethodSignature;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;

@Aspect
@Order(Ordered.HIGHEST_PRECEDENCE)
public class ConfidentialAIAspect {
    private final List<ConfidentialRuntimeVerifier> verifiers;

    public ConfidentialAIAspect(List<ConfidentialRuntimeVerifier> verifiers) {
        this.verifiers = List.copyOf(verifiers);
    }

    @Around("@annotation(org.opentron.backend.security.confidential.ConfidentialAI) "
            + "|| @within(org.opentron.backend.security.confidential.ConfidentialAI)")
    public Object aroundConfidentialAI(ProceedingJoinPoint joinPoint) throws Throwable {
        return requireConfidentialRuntime(joinPoint);
    }

    public Object requireConfidentialRuntime(ProceedingJoinPoint joinPoint) throws Throwable {
        if (verifiers.size() != 1) {
            throw new ConfidentialExecutionDeniedException(
                    "Confidential execution requires exactly one configured runtime verifier.");
        }
        if (isAsynchronous(joinPoint)) {
            throw new ConfidentialExecutionDeniedException(
                    "@ConfidentialAI supports synchronous method execution only.");
        }

        verifiers.get(0).verifyCurrentRuntime();
        return joinPoint.proceed();
    }

    private static boolean isAsynchronous(ProceedingJoinPoint joinPoint) {
        if (!(joinPoint.getSignature() instanceof MethodSignature signature)) {
            return false;
        }
        Class<?> returnType = signature.getReturnType();
        return CompletionStage.class.isAssignableFrom(returnType)
                || java.util.concurrent.Future.class.isAssignableFrom(returnType)
                || implementsReactivePublisher(returnType);
    }

    private static boolean implementsReactivePublisher(Class<?> type) {
        if (type == null) {
            return false;
        }
        if ("org.reactivestreams.Publisher".equals(type.getName())) {
            return true;
        }
        for (Class<?> implementedInterface : type.getInterfaces()) {
            if (implementsReactivePublisher(implementedInterface)) {
                return true;
            }
        }
        return implementsReactivePublisher(type.getSuperclass());
    }
}package org.opentron.backend.security.confidential;

public final class ConfidentialExecutionDeniedException extends SecurityException {
    public ConfidentialExecutionDeniedException(String message) {
        super(message);
    }

    public ConfidentialExecutionDeniedException(String message, Throwable cause) {
        super(message, cause);
    }
}package org.opentron.backend.security.confidential;

/**
 * Verifies that the current runtime satisfies the configured confidential
 * computing policy. Implementations must fail closed and validate fresh,
 * challenge-bound attestation evidence before approving execution.
 */
@FunctionalInterface
public interface ConfidentialRuntimeVerifier {
    void verifyCurrentRuntime();
}package org.opentron.cjae.starter;

