}package org.opentron.cjae.worker;

import java.security.SecureRandom;
import java.time.Clock;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.opentron.backend.security.confidential.gateway.AesGcmSecureContextCodec;
import org.opentron.backend.security.confidential.gateway.SecureContextKeyProvider;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Conditional;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;

@Configuration(proxyBeanMethods = false)
@Profile("aws-nitro & !gcp-cvm & !local-untrusted")
@Conditional(AwsNitroBenchmarkEnabledCondition.class)
public class AwsNitroConfidentialBenchmarkConfiguration {
    @Bean
    public AesGcmSecureContextCodec awsNitroBenchmarkSecureContextCodec(
            SecureContextKeyProvider keyProvider,
            ObjectMapper objectMapper) {
        return new AesGcmSecureContextCodec(
                keyProvider,
                objectMapper,
                new SecureRandom(),
                Clock.systemUTC());
    }

    @Bean(destroyMethod = "clear")
    public AwsNitroConfidentialBenchmarkReport awsNitroConfidentialBenchmarkReport() {
        return new AwsNitroConfidentialBenchmarkReport();
    }
}package org.opentron.cjae.worker;

import java.nio.charset.StandardCharsets;
import java.time.Clock;
import java.time.Duration;
import java.util.Map;
import java.util.Objects;

import org.opentron.backend.security.confidential.ConfidentialAI;
import org.opentron.backend.security.confidential.ConfidentialSegment;
import org.opentron.backend.security.confidential.gateway.AesGcmSecureContextCodec;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Conditional;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Component;

@Component
@Profile("aws-nitro & !gcp-cvm & !local-untrusted")
@Conditional(AwsNitroHealthVsockEnabledCondition.class)
@ConditionalOnProperty(
        name = "confidential.aws.nitro.benchmark.enabled",
        havingValue = "true")
public class AwsNitroConfidentialBenchmarkOperation {
    private static final String TENANT_ID = "thesis-benchmark";
    private static final String TOKEN = "<CJAE_BENCHMARK_SECRET>";
    private static final Duration CONTEXT_LIFETIME = Duration.ofMinutes(5);

    private final AesGcmSecureContextCodec contextCodec;
    private final Clock clock;

    public AwsNitroConfidentialBenchmarkOperation(AesGcmSecureContextCodec contextCodec) {
        this(contextCodec, Clock.systemUTC());
    }

    AwsNitroConfidentialBenchmarkOperation(
            AesGcmSecureContextCodec contextCodec, Clock clock) {
        this.contextCodec = Objects.requireNonNull(contextCodec, "contextCodec");
        this.clock = Objects.requireNonNull(clock, "clock");
    }

    @ConfidentialAI
    public AwsNitroConfidentialBenchmarkCall encryptAndVerify(String syntheticPayload) {
        Objects.requireNonNull(syntheticPayload, "syntheticPayload");
        byte[] encodedPayload = syntheticPayload.getBytes(StandardCharsets.UTF_8);
        try (ConfidentialSegment secret = ConfidentialSegment.fromUtf8(syntheticPayload)) {
            Map<String, ConfidentialSegment> mappings = Map.of(TOKEN, secret);
            long encryptionStarted = System.nanoTime();
            String encryptedContext = contextCodec.sealNative(
                    TENANT_ID, mappings, clock.instant().plus(CONTEXT_LIFETIME));
            long encryptionNanos = System.nanoTime() - encryptionStarted;

            long decryptionStarted = System.nanoTime();
            String restored;
            try (AesGcmSecureContextCodec.SecureContextMappings opened =
                    contextCodec.openNative(TENANT_ID, encryptedContext)) {
                ConfidentialSegment recovered = opened.values().get(TOKEN);
                if (recovered == null) {
                    throw new IllegalStateException(
                            "Encrypted benchmark context did not contain its protected value.");
                }
                restored = recovered.toUtf8String();
            }
            long decryptionNanos = System.nanoTime() - decryptionStarted;
            if (!syntheticPayload.equals(restored)) {
                throw new IllegalStateException(
                        "Encrypted benchmark context failed its plaintext round trip.");
            }
            if (!encryptedContext.startsWith("v3.")) {
                throw new IllegalStateException(
                        "Encrypted benchmark context used an unexpected format.");
            }
            return new AwsNitroConfidentialBenchmarkCall(
                    encodedPayload.length,
                    encryptedContext.getBytes(StandardCharsets.UTF_8).length,
                    encryptionNanos,
                    decryptionNanos,
                    true);
        } finally {
            java.util.Arrays.fill(encodedPayload, (byte) 0);
        }
    }
}package org.opentron.cjae.worker;

import java.util.Arrays;

import org.opentron.backend.security.confidential.gateway.aws.LinuxVsockHealthBridge;

public final class AwsNitroConfidentialBenchmarkReport {
    private volatile byte[] serializedReport;
    private volatile String failureCode;

    public synchronized void publish(byte[] report) {
        if (serializedReport != null || failureCode != null) {
            throw new IllegalStateException("The AWS Nitro benchmark report is already published.");
        }
        serializedReport = report.clone();
    }

    public synchronized void fail(String code) {
        if (serializedReport != null || failureCode != null
                || !("startup_verification_failed".equals(code)
                        || "benchmark_execution_failed".equals(code))) {
            throw new IllegalStateException("The AWS Nitro benchmark failure is invalid.");
        }
        failureCode = code;
    }

    public LinuxVsockHealthBridge.HealthResponse response() {
        byte[] report = serializedReport;
        String failed = failureCode;
        if (failed != null) {
            return new LinuxVsockHealthBridge.HealthResponse(
                    503,
                    ("{\"status\":\"benchmark_failed\",\"failureCode\":\""
                            + failed + "\"}").getBytes(
                                    java.nio.charset.StandardCharsets.UTF_8));
        }
        if (report == null) {
            return new LinuxVsockHealthBridge.HealthResponse(
                    503, "{\"status\":\"benchmark_not_ready\"}".getBytes(
                            java.nio.charset.StandardCharsets.UTF_8));
        }
        return new LinuxVsockHealthBridge.HealthResponse(200, report.clone());
    }

    public synchronized void clear() {
        if (serializedReport != null) {
            Arrays.fill(serializedReport, (byte) 0);
            serializedReport = null;
        }
        failureCode = null;
    }
}package org.opentron.cjae.worker;

import java.io.IOException;
import java.time.Clock;
import java.util.ArrayList;
import java.util.List;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Conditional;
import org.springframework.context.annotation.Profile;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;

@Component
@Profile("aws-nitro & !gcp-cvm & !local-untrusted")
@Conditional(AwsNitroHealthVsockEnabledCondition.class)
@ConditionalOnProperty(
        name = "confidential.aws.nitro.benchmark.enabled",
        havingValue = "true")
@Order(50)
public class AwsNitroConfidentialBenchmarkRunner implements ApplicationRunner {
    private final AwsNitroConfidentialBenchmarkOperation operation;
    private final AwsNitroConfidentialBenchmarkReport report;
    private final ObjectMapper objectMapper;
    private final int warmupRequests;
    private final int sampleCount;
    private final Clock clock;
    private final AwsNitroStartupStatus startupStatus;

    @Autowired
    public AwsNitroConfidentialBenchmarkRunner(
            AwsNitroConfidentialBenchmarkOperation operation,
            AwsNitroConfidentialBenchmarkReport report,
            ObjectMapper objectMapper,
            @Value("${confidential.aws.nitro.benchmark.warmup:10}") int warmupRequests,
            @Value("${confidential.aws.nitro.benchmark.samples:100}") int sampleCount,
            AwsNitroStartupStatus startupStatus) {
        this(
                operation,
                report,
                objectMapper,
                warmupRequests,
                sampleCount,
                Clock.systemUTC(),
                startupStatus);
    }

    AwsNitroConfidentialBenchmarkRunner(
            AwsNitroConfidentialBenchmarkOperation operation,
            AwsNitroConfidentialBenchmarkReport report,
            ObjectMapper objectMapper,
            int warmupRequests,
            int sampleCount,
            Clock clock) {
        this(
                operation,
                report,
                objectMapper,
                warmupRequests,
                sampleCount,
                clock,
                new AwsNitroStartupStatus(false));
    }

    AwsNitroConfidentialBenchmarkRunner(
            AwsNitroConfidentialBenchmarkOperation operation,
            AwsNitroConfidentialBenchmarkReport report,
            ObjectMapper objectMapper,
            int warmupRequests,
            int sampleCount,
            Clock clock,
            AwsNitroStartupStatus startupStatus) {
        if (warmupRequests < 1 || sampleCount < 1 || sampleCount > 500) {
            throw new IllegalArgumentException(
                    "AWS Nitro benchmark requires 1-500 samples and at least one warmup.");
        }
        this.operation = operation;
        this.report = report;
        this.objectMapper = objectMapper;
        this.warmupRequests = warmupRequests;
        this.sampleCount = sampleCount;
        this.clock = clock;
        this.startupStatus = startupStatus;
    }

    @Override
    public void run(ApplicationArguments arguments) throws IOException {
        if (!startupStatus.snapshot().ready()) {
            report.fail("startup_verification_failed");
            return;
        }
        for (int index = 0; index < warmupRequests; index++) {
            AwsNitroConfidentialBenchmarkCall result = operation.encryptAndVerify(payload(index));
            requireSuccessfulRoundTrip(result);
        }

        List<Sample> samples = new ArrayList<>(sampleCount);
        for (int index = 0; index < sampleCount; index++) {
            String payload = payload(index + warmupRequests);
            String startedAt = clock.instant().toString();
            long callStarted = System.nanoTime();
            AwsNitroConfidentialBenchmarkCall result = operation.encryptAndVerify(payload);
            long callNanos = System.nanoTime() - callStarted;
            requireSuccessfulRoundTrip(result);
            samples.add(new Sample(
                    index + 1,
                    startedAt,
                    result.plaintextBytes(),
                    result.encryptedContextBytes(),
                    callNanos,
                    result.encryptionNanos(),
                    result.decryptionNanos(),
                    result.roundTripVerified()));
        }
        report.publish(objectMapper.writeValueAsBytes(new BenchmarkDocument(
                "aws-nitro-confidential-annotation-aes-gcm-roundtrip",
                clock.instant().toString(),
                new Methodology(
                        warmupRequests,
                        sampleCount,
                        true,
                        true,
                        "Caller-to-return latency includes @ConfidentialAI runtime verification, "
                                + "fresh NSM/KMS key release, and AES-GCM context seal/open."),
                summarize(samples),
                samples)));
    }

    private static String payload(int index) {
        return "Synthetic thesis benchmark payload "
                + index
                + " | protected-value=subject-"
                + String.format("%06d", index)
                + "@example.invalid";
    }

    private static void requireSuccessfulRoundTrip(AwsNitroConfidentialBenchmarkCall result) {
        if (!result.roundTripVerified()
                || result.plaintextBytes() <= 0
                || result.encryptedContextBytes() <= result.plaintextBytes()) {
            throw new IllegalStateException(
                    "AWS Nitro annotated AES-GCM benchmark round trip failed.");
        }
    }

    private static Summary summarize(List<Sample> samples) {
        List<Long> values = samples.stream().map(Sample::annotatedCallNanos).sorted().toList();
        double mean = values.stream().mapToLong(Long::longValue).average().orElseThrow();
        return new Summary(
                values.size(),
                values.getFirst(),
                mean,
                percentile(values, 50),
                percentile(values, 90),
                percentile(values, 95),
                percentile(values, 99),
                values.getLast(),
                values.stream().allMatch(value -> value > 0),
                samples.stream().allMatch(Sample::roundTripVerified));
    }

    private static long percentile(List<Long> sortedValues, int percentile) {
        int index = Math.max(0, (int) Math.ceil(percentile / 100.0 * sortedValues.size()) - 1);
        return sortedValues.get(index);
    }

    public record BenchmarkDocument(
            String benchmark,
            String generatedAtUtc,
            Methodology methodology,
            Summary summary,
            List<Sample> samples) {
    }

    public record Methodology(
            int warmupRequestsExcluded,
            int measuredRequests,
            boolean gatewayDisabled,
            boolean everyAnnotatedCallPassedAesGcmRoundTrip,
            String measuredPath) {
    }

    public record Summary(
            int sampleCount,
            long minAnnotatedCallNanos,
            double meanAnnotatedCallNanos,
            long p50AnnotatedCallNanos,
            long p90AnnotatedCallNanos,
            long p95AnnotatedCallNanos,
            long p99AnnotatedCallNanos,
            long maxAnnotatedCallNanos,
            boolean allCallsPositiveDuration,
            boolean allEncryptionRoundTripsVerified) {
    }

    public record Sample(
            int sample,
            String timestampUtc,
            int plaintextBytes,
            int encryptedContextBytes,
            long annotatedCallNanos,
            long aesGcmEncryptNanos,
            long aesGcmDecryptNanos,
            boolean roundTripVerified) {
    }
}package org.opentron.cjae.worker;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.opentron.backend.security.confidential.gateway.aws.LinuxVsockHealthBridge;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.ApplicationRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Conditional;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;
import org.springframework.core.annotation.Order;
import org.springframework.beans.factory.ObjectProvider;

@Configuration(proxyBeanMethods = false)
@Profile("aws-nitro & !gcp-cvm & !local-untrusted")
@Conditional(AwsNitroHealthVsockEnabledCondition.class)
public class AwsNitroHealthVsockConfiguration {
    @Bean(destroyMethod = "close")
    public LinuxVsockHealthBridge awsNitroHealthVsockBridge(
            @Value("${confidential.aws.nitro.vsock.parent-cid:3}") int parentCid,
            @Value("${confidential.aws.nitro.health-vsock.port:8002}") int vsockPort,
            AwsNitroStartupStatus startupStatus,
            ObjectProvider<AwsNitroConfidentialBenchmarkReport> benchmarkReport,
            ObjectMapper objectMapper) {
        LinuxVsockHealthBridge.HealthResponseProvider healthResponse = () -> {
            var health = ConfidentialWorkerApplication.healthPayload(startupStatus.snapshot());
            return new LinuxVsockHealthBridge.HealthResponse(
                    health.awsNitroStartup().ready() ? 200 : 503,
                    objectMapper.writeValueAsBytes(health));
        };
        AwsNitroConfidentialBenchmarkReport report = benchmarkReport.getIfAvailable();
        if (report == null) {
            return new LinuxVsockHealthBridge(parentCid, vsockPort, healthResponse);
        }
        return new LinuxVsockHealthBridge(
                parentCid, vsockPort, healthResponse, report::response);
    }

    @Bean
    @Order(-100)
    public ApplicationRunner startAwsNitroHealthVsockBridge(
            LinuxVsockHealthBridge bridge) {
        return arguments -> bridge.start();
    }
}package org.opentron.cjae.worker;

import org.springframework.context.annotation.Condition;
import org.springframework.context.annotation.ConditionContext;
import org.springframework.core.type.AnnotatedTypeMetadata;

public final class AwsNitroHealthVsockEnabledCondition implements Condition {
    @Override
    public boolean matches(ConditionContext context, AnnotatedTypeMetadata metadata) {
        return context.getEnvironment().getProperty(
                        "confidential.aws.nitro.health-vsock.enabled", Boolean.class, false)
                && context.getEnvironment().getProperty(
                        "confidential.aws.nitro.verify-on-startup", Boolean.class, false)
                && !context.getEnvironment().getProperty(
                        "confidential.gateway.enabled", Boolean.class, false);
    }
}package org.opentron.cjae.worker;

import java.io.IOException;
import java.nio.file.Path;
import java.time.Clock;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.TimeUnit;

import java.lang.management.ManagementFactory;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.sun.management.OperatingSystemMXBean;
import org.opentron.backend.security.confidential.ConfidentialAI;
import org.opentron.backend.security.confidential.ConfidentialSegment;
import org.opentron.backend.security.confidential.gateway.AesGcmSecureContextCodec;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Conditional;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Component;

@Component
@Profile("aws-nitro & !gcp-cvm & !local-untrusted")
@Conditional(AwsNitroHealthVsockEnabledCondition.class)
@ConditionalOnProperty(
        name = "confidential.aws.nitro.rag-benchmark.enabled",
        havingValue = "true")
public class AwsNitroRagBenchmarkOperation {
    private static final String TENANT_ID = "thesis-rag-benchmark";
    private static final String JAVA_PROMPT = "<CJAE_JAVA_RAG_PROMPT>";
    private static final String PYTHON_PROMPT = "<CJAE_PYTHON_RAG_PROMPT>";
    private static final Duration CONTEXT_LIFETIME = Duration.ofMinutes(5);
    private static final long PYTHON_TIMEOUT_MINUTES = 20;
    private static final OperatingSystemMXBean OPERATING_SYSTEM_BEAN =
            requireOperatingSystemBean();

    private final AwsNitroRagPipeline pipeline;
    private final AesGcmSecureContextCodec contextCodec;
    private final ObjectMapper objectMapper;
    private final Clock clock;
    private final String pythonExecutable;
    private final Path pythonScript;

    public AwsNitroRagBenchmarkOperation(
            AesGcmSecureContextCodec contextCodec,
            ObjectMapper objectMapper,
            @Value("${confidential.aws.nitro.rag-benchmark.python-executable:python3}")
                    String pythonExecutable,
            @Value("${confidential.aws.nitro.rag-benchmark.python-script:"
                    + "/opt/cjae/bin/python_serialized_proxy.py}") String pythonScript) {
        this(
                new AwsNitroRagPipeline(),
                contextCodec,
                objectMapper,
                Clock.systemUTC(),
                pythonExecutable,
                Path.of(pythonScript));
    }

    AwsNitroRagBenchmarkOperation(
            AwsNitroRagPipeline pipeline,
            AesGcmSecureContextCodec contextCodec,
            ObjectMapper objectMapper,
            Clock clock,
            String pythonExecutable,
            Path pythonScript) {
        this.pipeline = Objects.requireNonNull(pipeline, "pipeline");
        this.contextCodec = Objects.requireNonNull(contextCodec, "contextCodec");
        this.objectMapper = Objects.requireNonNull(objectMapper, "objectMapper");
        this.clock = Objects.requireNonNull(clock, "clock");
        this.pythonExecutable = Objects.requireNonNull(pythonExecutable, "pythonExecutable");
        this.pythonScript = Objects.requireNonNull(pythonScript, "pythonScript");
    }

    @ConfidentialAI
    public AwsNitroRagComparisonCall compare(
            int recordCount,
            int warmupSamples,
            int measuredSamples,
            int batchSize,
            String query,
            int topK) throws IOException, InterruptedException {
        validateRequest(recordCount, warmupSamples, measuredSamples, batchSize, query, topK);
        List<JavaRun> javaResults =
                new ArrayList<>(warmupSamples + measuredSamples);
        for (int index = 0; index < warmupSamples + measuredSamples; index++) {
            javaResults.add(runJavaSample(recordCount, query, topK));
        }

        AwsNitroRagComparisonCall.PythonDocument python =
                runPythonProxy(recordCount, warmupSamples, measuredSamples, batchSize, query, topK);
        if (python.recordCount() != recordCount
                || python.warmupSamplesExcluded() != warmupSamples
                || python.measuredSamples() != measuredSamples
                || python.samples().size() != measuredSamples) {
            throw new IllegalStateException("Python RAG proxy returned incomplete measurements.");
        }

        List<AwsNitroRagComparisonCall.JavaSample> measuredJava = new ArrayList<>(measuredSamples);
        List<String> protectedPrompts = new ArrayList<>(measuredSamples * 2);
        for (int index = 0; index < measuredSamples; index++) {
            JavaRun javaRun = javaResults.get(warmupSamples + index);
            AwsNitroRagPipeline.Result javaResult = javaRun.result();
            AwsNitroRagComparisonCall.PythonSample pythonResult = python.samples().get(index);
            if (!javaResult.topRecordIds().equals(pythonResult.topRecordIds())
                    || !javaResult.promptSha256().equals(pythonResult.promptSha256())) {
                throw new IllegalStateException(
                        "Java and Python RAG results differ for measured sample " + (index + 1) + ".");
            }
            measuredJava.add(toJavaSample(index + 1, javaRun));
            protectedPrompts.add(javaResult.syntheticPrompt());
            protectedPrompts.add(pythonPrompt(query, pythonResult.topMatches()));
        }
        boolean encryptedRoundTripVerified = encryptAndVerifyPrompts(protectedPrompts);

        return new AwsNitroRagComparisonCall(
                recordCount,
                warmupSamples,
                measuredSamples,
                query,
                measuredJava,
                python,
                true,
                encryptedRoundTripVerified);
    }

    private JavaRun runJavaSample(
            int recordCount, String query, int topK) {
        long cpuStarted = processCpuNanos();
        AwsNitroRagPipeline.Result result = pipeline.run(recordCount, query, topK);
        long cpuNanos = processCpuNanos() - cpuStarted;
        return new JavaRun(result, cpuNanos, processPeakRssKiB());
    }

    private static AwsNitroRagComparisonCall.JavaSample toJavaSample(
            int sample, JavaRun run) {
        AwsNitroRagPipeline.Result result = run.result();
        return new AwsNitroRagComparisonCall.JavaSample(
                sample,
                result.elapsedNanos(),
                run.processCpuNanos(),
                run.processPeakRssKiB(),
                result.nativeIndexBytes(),
                result.promptSha256(),
                result.topRecordIds());
    }

    private AwsNitroRagComparisonCall.PythonDocument runPythonProxy(
            int recordCount,
            int warmupSamples,
            int measuredSamples,
            int batchSize,
            String query,
            int topK) throws IOException, InterruptedException {
        Process process = new ProcessBuilder(
                pythonExecutable,
                pythonScript.toString(),
                "--record-count", Integer.toString(recordCount),
                "--warmups", Integer.toString(warmupSamples),
                "--samples", Integer.toString(measuredSamples),
                "--batch-size", Integer.toString(batchSize),
                "--query", query,
                "--top-k", Integer.toString(topK))
                .redirectError(ProcessBuilder.Redirect.DISCARD)
                .start();
        boolean completed;
        try {
            completed = process.waitFor(PYTHON_TIMEOUT_MINUTES, TimeUnit.MINUTES);
        } catch (InterruptedException exception) {
            process.destroyForcibly();
            Thread.currentThread().interrupt();
            throw exception;
        }
        if (!completed) {
            process.destroyForcibly();
            throw new IllegalStateException("Python RAG proxy exceeded its 20-minute time limit.");
        }
        byte[] output = process.getInputStream().readAllBytes();
        if (process.exitValue() != 0) {
            throw new IllegalStateException(
                    "Python RAG proxy failed with exit code " + process.exitValue() + ".");
        }
        return objectMapper.readValue(output, AwsNitroRagComparisonCall.PythonDocument.class);
    }

    private boolean encryptAndVerifyPrompts(List<String> prompts) {
        for (int index = 0; index < prompts.size(); index += 2) {
            try (ConfidentialSegment javaPrompt = ConfidentialSegment.fromUtf8(prompts.get(index));
                    ConfidentialSegment pythonPrompt =
                            ConfidentialSegment.fromUtf8(prompts.get(index + 1))) {
                String encrypted = contextCodec.sealNative(
                        TENANT_ID,
                        Map.of(JAVA_PROMPT, javaPrompt, PYTHON_PROMPT, pythonPrompt),
                        clock.instant().plus(CONTEXT_LIFETIME));
                try (AesGcmSecureContextCodec.SecureContextMappings opened =
                        contextCodec.openNative(TENANT_ID, encrypted)) {
                    ConfidentialSegment recoveredJava = opened.values().get(JAVA_PROMPT);
                    ConfidentialSegment recoveredPython = opened.values().get(PYTHON_PROMPT);
                    if (recoveredJava == null
                            || recoveredPython == null
                            || !prompts.get(index).equals(recoveredJava.toUtf8String())
                            || !prompts.get(index + 1).equals(recoveredPython.toUtf8String())) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private static String pythonPrompt(
            String query, List<AwsNitroRagComparisonCall.Match> matches) {
        StringBuilder result = new StringBuilder("query=").append(query).append('\n');
        for (AwsNitroRagComparisonCall.Match match : matches) {
            result.append(match.recordId())
                    .append(',')
                    .append(match.dotProduct())
                    .append(',')
                    .append(match.recordNormSquared())
                    .append('\n');
        }
        return result.toString();
    }

    private static void validateRequest(
            int recordCount,
            int warmupSamples,
            int measuredSamples,
            int batchSize,
            String query,
            int topK) {
        if (recordCount < 1 || recordCount > AwsNitroRagPipeline.MAX_RECORDS
                || warmupSamples < 1 || measuredSamples < 1 || measuredSamples > 10
                || batchSize < 1 || batchSize > 100_000
                || topK < 1 || topK > 100 || topK > recordCount
                || !AwsNitroRagPipeline.isSyntheticQuery(query)) {
            throw new IllegalArgumentException("AWS Nitro RAG benchmark parameters are invalid.");
        }
    }

    private static OperatingSystemMXBean requireOperatingSystemBean() {
        var bean = ManagementFactory.getOperatingSystemMXBean();
        if (!(bean instanceof OperatingSystemMXBean extended)) {
            throw new IllegalStateException("Process CPU time metrics are unavailable.");
        }
        return extended;
    }

    private static long processCpuNanos() {
        long value = OPERATING_SYSTEM_BEAN.getProcessCpuTime();
        if (value < 0) {
            throw new IllegalStateException("Process CPU time metrics are unavailable.");
        }
        return value;
    }

    private static long processPeakRssKiB() {
        try {
            for (String line : java.nio.file.Files.readAllLines(Path.of("/proc/self/status"))) {
                if (line.startsWith("VmHWM:")) {
                    return Long.parseLong(line.replaceAll("[^0-9]", ""));
                }
            }
        } catch (IOException | NumberFormatException exception) {
            throw new IllegalStateException("Process peak RSS metrics are unavailable.", exception);
        }
        throw new IllegalStateException("Process peak RSS metrics are unavailable.");
    }

    private record JavaRun(
            AwsNitroRagPipeline.Result result,
            long processCpuNanos,
            long processPeakRssKiB) {
    }
}package org.opentron.cjae.worker;

import java.io.IOException;
import java.time.Clock;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Conditional;
import org.springframework.context.annotation.Profile;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;

@Component
@Profile("aws-nitro & !gcp-cvm & !local-untrusted")
@Conditional(AwsNitroHealthVsockEnabledCondition.class)
@ConditionalOnProperty(
        name = "confidential.aws.nitro.rag-benchmark.enabled",
        havingValue = "true")
@Order(50)
public class AwsNitroRagBenchmarkRunner implements ApplicationRunner {
    private static final Logger LOGGER =
            LoggerFactory.getLogger(AwsNitroRagBenchmarkRunner.class);
    static final int RECORD_COUNT = 1_000_000;
    static final int WARMUP_SAMPLES = 1;
    static final int MEASURED_SAMPLES = 3;
    static final int SERIALIZATION_BATCH_SIZE = 10_000;
    static final int TOP_K = 10;
    static final String QUERY = "segment-7 region-11 product-42";

    private final AwsNitroRagBenchmarkOperation operation;
    private final AwsNitroConfidentialBenchmarkReport report;
    private final ObjectMapper objectMapper;
    private final AwsNitroStartupStatus startupStatus;
    private final Clock clock;

    @Autowired
    public AwsNitroRagBenchmarkRunner(
            AwsNitroRagBenchmarkOperation operation,
            AwsNitroConfidentialBenchmarkReport report,
            ObjectMapper objectMapper,
            AwsNitroStartupStatus startupStatus) {
        this(operation, report, objectMapper, startupStatus, Clock.systemUTC());
    }

    AwsNitroRagBenchmarkRunner(
            AwsNitroRagBenchmarkOperation operation,
            AwsNitroConfidentialBenchmarkReport report,
            ObjectMapper objectMapper,
            AwsNitroStartupStatus startupStatus,
            Clock clock) {
        this.operation = operation;
        this.report = report;
        this.objectMapper = objectMapper;
        this.startupStatus = startupStatus;
        this.clock = clock;
    }

    @Override
    public void run(ApplicationArguments arguments) throws IOException, InterruptedException {
        if (!startupStatus.snapshot().ready()) {
            report.fail("startup_verification_failed");
            return;
        }
        try {
            AwsNitroRagComparisonCall result = operation.compare(
                    RECORD_COUNT,
                    WARMUP_SAMPLES,
                    MEASURED_SAMPLES,
                    SERIALIZATION_BATCH_SIZE,
                    QUERY,
                    TOP_K);
            if (!result.javaPythonResultsMatch() || !result.encryptedPromptRoundTripVerified()) {
                throw new IllegalStateException(
                        "AWS Nitro RAG comparison failed result or encryption verification.");
            }
            report.publish(objectMapper.writeValueAsBytes(new BenchmarkDocument(
                    "aws-nitro-confidential-rag-java-vs-python-serialized-proxy",
                    clock.instant().toString(),
                    new Methodology(
                            result.recordCount(),
                            result.warmupSamplesExcluded(),
                            result.measuredSamples(),
                            result.python().serializationBatchSize(),
                            true,
                            true,
                            "verified".equals(startupStatus.snapshot().status()),
                            true,
                            "Both pipelines ran sequentially inside the same Nitro Enclave. "
                                    + "The Java path tokenizes synthetic rows, builds a 16-dimensional "
                                    + "hash embedding index in zeroizing Panama off-heap memory, searches "
                                    + "top-k cosine matches, and packages a prompt. The Python proxy "
                                    + "runs the same deterministic workload but pickles and unpickles "
                                    + "each input batch. This is a local Python serialization proxy, "
                                    + "not Apache Spark or Opaque. Per-sample pipeline latency excludes "
                                    + "the single enclosing @ConfidentialAI runtime verification; "
                                    + "the protected prompts are AES-GCM sealed and reopened. Java RSS "
                                    + "includes the worker JVM; Python RSS covers its subprocess."),
                    result.query(),
                    result.javaSamples(),
                    result.python().samples(),
                    result.python().totalSerializedBytes(),
                    result.javaPythonResultsMatch(),
                    result.encryptedPromptRoundTripVerified())));
        } catch (IOException | InterruptedException | RuntimeException exception) {
            if (!startupStatus.diagnosticsEnabled()) {
                throw exception;
            }
            if (exception instanceof InterruptedException) {
                Thread.currentThread().interrupt();
            }
            report.fail("benchmark_execution_failed");
            LOGGER.warn(
                    "AWS Nitro RAG benchmark failed; sanitized failureType={}",
                    exception.getClass().getSimpleName());
        }
    }

    public record BenchmarkDocument(
            String benchmark,
            String generatedAtUtc,
            Methodology methodology,
            String syntheticQuery,
            java.util.List<AwsNitroRagComparisonCall.JavaSample> javaSamples,
            java.util.List<AwsNitroRagComparisonCall.PythonSample> pythonSamples,
            long totalPythonSerializedBytes,
            boolean matchingRetrievalResults,
            boolean everyPromptAesGcmRoundTripVerified) {
    }

    public record Methodology(
            int syntheticRecordsPerSample,
            int warmupSamplesExcluded,
            int measuredSamples,
            int pythonSerializationBatchSize,
            boolean sameNitroEnclave,
            boolean gatewayDisabled,
            boolean startupAttestationPassed,
            boolean everyAnnotatedCallPassedAesGcmRoundTrip,
            String measuredPath) {
    }
