}package org.opentron.cjae.worker;

import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HexFormat;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.PriorityQueue;

import org.opentron.backend.security.confidential.ConfidentialSegment;

final class AwsNitroRagPipeline {
    static final int EMBEDDING_DIMENSIONS = 16;
    static final int MAX_RECORDS = 2_000_000;
    private static final int MAX_TOP_K = 100;
    private static final Pattern SYNTHETIC_QUERY =
            Pattern.compile("segment-(\\d{1,2}) region-(\\d{1,2}) product-(\\d{1,3})");
    private static final ValueLayout.OfInt INT_LAYOUT = ValueLayout.JAVA_INT_UNALIGNED;
    private static final Comparator<Match> BEST_FIRST =
            Comparator.comparingDouble(Match::similarity)
                    .reversed()
                    .thenComparingInt(Match::recordId);

    Result run(int recordCount, String query, int topK) {
        validate(recordCount, query, topK);
        long started = System.nanoTime();
        long indexBytes = Math.multiplyExact(
                Math.multiplyExact((long) recordCount, EMBEDDING_DIMENSIONS),
                Integer.BYTES);
        int[] queryVector = embed(query.split(" "), 0);

        try (ConfidentialSegment index = ConfidentialSegment.allocate(indexBytes)) {
            MemorySegment memory = index.memory();
            buildIndex(memory, recordCount);
            List<Match> matches = retrieve(memory, recordCount, queryVector, topK);
            String prompt = packagePrompt(query, matches);
            return new Result(
                    recordCount,
                    indexBytes,
                    System.nanoTime() - started,
                    matches,
                    sha256(prompt),
                    prompt);
        }
    }

    static String syntheticRecord(int id) {
        return "customer-" + id
                + " segment-" + id % 31
                + " region-" + (id * 17L + 5) % 23
                + " product-" + (id * 7L + 3) % 101
                + " tier-" + (id * 13L + 1) % 7;
    }

    static boolean isSyntheticQuery(String query) {
        if (query == null) {
            return false;
        }
        Matcher matcher = SYNTHETIC_QUERY.matcher(query);
        if (!matcher.matches()) {
            return false;
        }
        return Integer.parseInt(matcher.group(1)) < 31
                && Integer.parseInt(matcher.group(2)) < 23
                && Integer.parseInt(matcher.group(3)) < 101;
    }

    static int[] embed(String[] tokens) {
        return embed(tokens, 1);
    }

    private static int[] embed(String[] tokens, int firstToken) {
        int[] vector = new int[EMBEDDING_DIMENSIONS];
        for (int index = firstToken; index < tokens.length; index++) {
            int hash = fnv1a(tokens[index]);
            int bucket = hash & (EMBEDDING_DIMENSIONS - 1);
            vector[bucket] += hash < 0 ? -1 : 1;
        }
        return vector;
    }

    private static void validate(int recordCount, String query, int topK) {
        if (recordCount < 1 || recordCount > MAX_RECORDS) {
            throw new IllegalArgumentException(
                    "RAG benchmark record count must be between 1 and " + MAX_RECORDS + ".");
        }
        if (!isSyntheticQuery(query)) {
            throw new IllegalArgumentException("RAG benchmark query must be synthetic text.");
        }
        if (topK < 1 || topK > MAX_TOP_K || topK > recordCount) {
            throw new IllegalArgumentException("RAG benchmark top-k value is invalid.");
        }
    }

    private static void buildIndex(MemorySegment memory, int recordCount) {
        for (int id = 0; id < recordCount; id++) {
            int[] vector = embed(syntheticRecord(id).split(" "));
            long offset = (long) id * EMBEDDING_DIMENSIONS;
            for (int dimension = 0; dimension < EMBEDDING_DIMENSIONS; dimension++) {
                memory.setAtIndex(INT_LAYOUT, offset + dimension, vector[dimension]);
            }
        }
    }

    private static List<Match> retrieve(
            MemorySegment memory, int recordCount, int[] queryVector, int topK) {
        int queryNorm = squaredNorm(queryVector);
        PriorityQueue<Match> bestMatches = new PriorityQueue<>(topK, BEST_FIRST.reversed());
        for (int id = 0; id < recordCount; id++) {
            long offset = (long) id * EMBEDDING_DIMENSIONS;
            int dotProduct = 0;
            int recordNorm = 0;
            for (int dimension = 0; dimension < EMBEDDING_DIMENSIONS; dimension++) {
                int value = memory.getAtIndex(INT_LAYOUT, offset + dimension);
                dotProduct += value * queryVector[dimension];
                recordNorm += value * value;
            }
            if (recordNorm == 0 || queryNorm == 0) {
                continue;
            }
            Match candidate = new Match(
                    id,
                    dotProduct,
                    recordNorm,
                    dotProduct / Math.sqrt((double) recordNorm * queryNorm));
            if (bestMatches.size() < topK) {
                bestMatches.add(candidate);
            } else if (BEST_FIRST.compare(candidate, bestMatches.peek()) < 0) {
                bestMatches.remove();
                bestMatches.add(candidate);
            }
        }
        return bestMatches.stream().sorted(BEST_FIRST).toList();
    }

    private static int squaredNorm(int[] vector) {
        int result = 0;
        for (int value : vector) {
            result += value * value;
        }
        return result;
    }

    private static int fnv1a(String value) {
        int hash = 0x811c9dc5;
        for (byte item : value.getBytes(StandardCharsets.UTF_8)) {
            hash = (hash ^ Byte.toUnsignedInt(item)) * 0x01000193;
        }
        return hash;
    }

    private static String packagePrompt(String query, List<Match> matches) {
        StringBuilder prompt = new StringBuilder("query=").append(query).append('\n');
        for (Match match : matches) {
            prompt.append(match.recordId())
                    .append(',')
                    .append(match.dotProduct())
                    .append(',')
                    .append(match.recordNormSquared())
                    .append('\n');
        }
        return prompt.toString();
    }

    private static String sha256(String prompt) {
        try {
            return HexFormat.of().formatHex(
                    MessageDigest.getInstance("SHA-256")
                            .digest(prompt.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException exception) {
            throw new IllegalStateException("SHA-256 is unavailable.", exception);
        }
    }

    record Match(int recordId, int dotProduct, int recordNormSquared, double similarity) {
    }

    record Result(
            int recordCount,
            long nativeIndexBytes,
            long elapsedNanos,
            List<Match> topMatches,
            String promptSha256,
            String syntheticPrompt) {

        Result {
            topMatches = List.copyOf(topMatches);
        }

        List<Integer> topRecordIds() {
            return topMatches.stream().map(Match::recordId).toList();
        }
    }
}package org.opentron.cjae.worker;

import java.util.Objects;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.opentron.backend.security.confidential.ConfidentialRuntimeVerifier;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Profile;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;

@Component
@Profile("aws-nitro")
@ConditionalOnProperty(
        name = "confidential.aws.nitro.verify-on-startup",
        havingValue = "true")
@Order(0)
public final class AwsNitroStartupAttestationRunner implements ApplicationRunner {
    private static final Logger LOGGER =
            LoggerFactory.getLogger(AwsNitroStartupAttestationRunner.class);

    private final ConfidentialRuntimeVerifier runtimeVerifier;
    private final AwsNitroStartupStatus startupStatus;
    private final boolean diagnosticsEnabled;

    @Autowired
    public AwsNitroStartupAttestationRunner(
            ConfidentialRuntimeVerifier runtimeVerifier,
            AwsNitroStartupStatus startupStatus,
            @Value("${confidential.aws.nitro.diagnostics.enabled:false}")
                    boolean diagnosticsEnabled) {
        this.runtimeVerifier = Objects.requireNonNull(runtimeVerifier, "runtimeVerifier");
        this.startupStatus = Objects.requireNonNull(startupStatus, "startupStatus");
        this.diagnosticsEnabled = diagnosticsEnabled;
    }

    AwsNitroStartupAttestationRunner(
            ConfidentialRuntimeVerifier runtimeVerifier,
            AwsNitroStartupStatus startupStatus) {
        this(runtimeVerifier, startupStatus, startupStatus.diagnosticsEnabled());
    }

    @Override
    public void run(ApplicationArguments arguments) {
        startupStatus.verificationStarted();
        try {
            runtimeVerifier.verifyCurrentRuntime();
            startupStatus.verificationPassed();
            LOGGER.info(
                    "AWS Nitro startup verification passed: freshNsmAttestation=true, "
                            + "kmsRecipientResponseReceived=true, "
                            + "aes256ContextKeyUnwrapped=true, startupRunnerPassed=true");
        } catch (RuntimeException exception) {
            String failureType = exception.getClass().getSimpleName();
            startupStatus.verificationFailed(failureType);
            if (diagnosticsEnabled) {
                LOGGER.warn(
                        "AWS Nitro startup verification failed; sanitized failureType={}",
                        failureType);
                return;
            }
            throw exception;
        }
    }
}package org.opentron.cjae.worker;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public final class AwsNitroStartupStatus {
    private final boolean required;
    private final boolean diagnosticsEnabled;
    private State state;
    private String failureType;

    @Autowired
    public AwsNitroStartupStatus(
            @Value("${confidential.aws.nitro.verify-on-startup:false}") boolean required,
            @Value("${confidential.aws.nitro.diagnostics.enabled:false}")
                    boolean diagnosticsEnabled) {
        this.required = required;
        this.diagnosticsEnabled = diagnosticsEnabled;
        this.state = required ? State.PENDING : State.NOT_REQUIRED;
    }

    public AwsNitroStartupStatus(boolean required) {
        this(required, false);
    }

    public boolean diagnosticsEnabled() {
        return diagnosticsEnabled;
    }

    public synchronized void verificationStarted() {
        if (required) {
            state = State.RUNNING;
        }
    }

    public synchronized void verificationPassed() {
        if (required) {
            state = State.VERIFIED;
            failureType = null;
        }
    }

    public synchronized void verificationFailed(String failureType) {
        if (required) {
            state = State.FAILED;
            this.failureType = sanitizeFailureType(failureType);
        }
    }

    private static String sanitizeFailureType(String failureType) {
        if (failureType == null || !failureType.matches("[A-Za-z][A-Za-z0-9]{0,79}")) {
            return "VerificationFailure";
        }
        return failureType;
    }

    public synchronized Snapshot snapshot() {
        boolean verified = state == State.VERIFIED;
        return new Snapshot(
                required,
                state.value,
                verified,
                verified,
                verified,
                verified,
                failureType);
    }

    public record Snapshot(
            boolean required,
            String status,
            boolean freshNsmAttestation,
            boolean kmsRecipientResponseReceived,
            boolean aes256ContextKeyUnwrapped,
            boolean startupRunnerPassed,
            String failureType) {

        public boolean ready() {
            return !required || "verified".equals(status);
        }
    }

    private enum State {
        NOT_REQUIRED("not-required"),
        PENDING("pending"),
        RUNNING("running"),
        VERIFIED("verified"),
        FAILED("failed");

        private final String value;

        State(String value) {
            this.value = value;
        }
    }
}package org.opentron.cjae.worker;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.autoconfigure.jdbc.DataSourceAutoConfiguration;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@SpringBootApplication(scanBasePackages = {
        "org.opentron.backend.security.confidential.gateway",
        "org.opentron.cjae.worker"
}, exclude = DataSourceAutoConfiguration.class)
@RestController
public class ConfidentialWorkerApplication {
    private final ObjectProvider<AwsNitroStartupStatus> startupStatus;

    public ConfidentialWorkerApplication(ObjectProvider<AwsNitroStartupStatus> startupStatus) {
        this.startupStatus = startupStatus;
    }

    public static void main(String[] args) {
        SpringApplication.run(ConfidentialWorkerApplication.class, args);
    }

    @GetMapping("/health")
    public ResponseEntity<WorkerHealth> health() {
        AwsNitroStartupStatus.Snapshot verification = startupStatus.getObject().snapshot();
        WorkerHealth health = healthPayload(verification);
        boolean ready = health.awsNitroStartup().ready();
        return ResponseEntity.status(ready ? HttpStatus.OK : HttpStatus.SERVICE_UNAVAILABLE)
                .body(health);
    }

    static WorkerHealth healthPayload(AwsNitroStartupStatus.Snapshot verification) {
        boolean ready = verification.ready();
        String healthStatus = ready
                ? "ok"
                : "failed".equals(verification.status()) ? "failed" : "starting";
        return new WorkerHealth(
                healthStatus,
                "cjae-confidential-worker",
                verification);
    }

    public record WorkerHealth(
            String status,
            String service,
            AwsNitroStartupStatus.Snapshot awsNitroStartup) {
    }
}package org.opentron.cjae.worker;

import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;

@Configuration(proxyBeanMethods = false)
@Profile("gateway-oidc")
@ConditionalOnProperty(name = "confidential.gateway.enabled", havingValue = "true")
public class WorkerReplayDataSourceConfiguration {
    @Bean(destroyMethod = "close")
    public HikariDataSource replayDataSource(
            @Value("${confidential.gateway.replay.jdbc-url}") String jdbcUrl,
            @Value("${confidential.gateway.replay.username}") String username,
            @Value("${confidential.gateway.replay.password}") String password) {
        String normalizedUrl = jdbcUrl.toLowerCase(java.util.Locale.ROOT);
        if (!jdbcUrl.startsWith("jdbc:postgresql://")
                || !normalizedUrl.contains("sslmode=verify-full")
                || !normalizedUrl.contains("sslrootcert=")
                || username.isBlank() || password.isBlank()) {
            throw new IllegalStateException(
                    "PostgreSQL replay protection requires credentials and a JDBC URL with sslmode=verify-full and sslrootcert.");
        }

        HikariConfig config = new HikariConfig();
        config.setPoolName("cjae-context-replay");
        config.setJdbcUrl(jdbcUrl);
        config.setUsername(username);
        config.setPassword(password);
        config.setMaximumPoolSize(8);
        config.setMinimumIdle(1);
        config.setConnectionTimeout(10_000);
        config.setInitializationFailTimeout(10_000);
        return new HikariDataSource(config);
    }
}#!/usr/bin/env python3
"""Synthetic Python serialization proxy; intentionally not Apache Spark or Opaque."""

from __future__ import annotations

import argparse
import array
import hashlib
import heapq
import json
import math
import pickle
import time
from pathlib import Path

DIMENSIONS = 16
MAX_RECORDS = 2_000_000


def synthetic_record(record_id: int) -> str:
    return (
        f"customer-{record_id} "
        f"segment-{record_id % 31} "
        f"region-{(record_id * 17 + 5) % 23} "
        f"product-{(record_id * 7 + 3) % 101} "
        f"tier-{(record_id * 13 + 1) % 7}"
    )


def fnv1a(value: str) -> int:
    result = 0x811C9DC5
    for byte in value.encode("utf-8"):
        result = ((result ^ byte) * 0x01000193) & 0xFFFFFFFF
    return result if result < 0x80000000 else result - 0x100000000


def embed(tokens: list[str], first_token: int = 1) -> list[int]:
    vector = [0] * DIMENSIONS
    for token in tokens[first_token:]:
        hashed = fnv1a(token)
        vector[hashed & (DIMENSIONS - 1)] += -1 if hashed < 0 else 1
    return vector


def run_pipeline(
    record_count: int,
    query: str,
    top_k: int,
    batch_size: int,
) -> tuple[list[int], str, int, str, list[dict[str, int]]]:
    index = array.array("i", [0]) * (record_count * DIMENSIONS)
    serialized_bytes = 0

    for start in range(0, record_count, batch_size):
        end = min(start + batch_size, record_count)
        source_records = [synthetic_record(record_id) for record_id in range(start, end)]
        serialized_records = pickle.dumps(source_records, protocol=pickle.HIGHEST_PROTOCOL)
        serialized_bytes += len(serialized_records)
        decoded_records = pickle.loads(serialized_records)
        for offset, record in enumerate(decoded_records, start=start):
            vector = embed(record.split(" "))
            destination = offset * DIMENSIONS
            for dimension, value in enumerate(vector):
                index[destination + dimension] = value

    query_vector = embed(query.split(" "), 0)
    query_norm = sum(value * value for value in query_vector)
    best: list[tuple[float, int, int, int, int]] = []
    for record_id in range(record_count):
        offset = record_id * DIMENSIONS
        dot_product = 0
        record_norm = 0
        for dimension, query_value in enumerate(query_vector):
            value = index[offset + dimension]
            dot_product += value * query_value
            record_norm += value * value
        if record_norm == 0 or query_norm == 0:
            continue
        candidate = (
            dot_product / math.sqrt(record_norm * query_norm),
            -record_id,
            record_id,
            dot_product,
            record_norm,
        )
        if len(best) < top_k:
            heapq.heappush(best, candidate)
        elif candidate > best[0]:
            heapq.heapreplace(best, candidate)

    matches = sorted(best, reverse=True)
    prompt = f"query={query}\n" + "".join(
        f"{record_id},{dot_product},{record_norm}\n"
        for _, _, record_id, dot_product, record_norm in matches
    )
    prompt_digest = hashlib.sha256(prompt.encode("utf-8")).hexdigest()
    hit_details = [
        {
            "recordId": match[2],
            "dotProduct": match[3],
            "recordNormSquared": match[4],
        }
        for match in matches
    ]
    return [match[2] for match in matches], prompt_digest, serialized_bytes, prompt, hit_details


def peak_rss_kib() -> int:
    status = Path("/proc/self/status").read_text(encoding="ascii")
    for line in status.splitlines():
        if line.startswith("VmHWM:"):
            return int(line.split()[1])
    raise RuntimeError("Python process peak RSS metric is unavailable.")


def measured_sample(
    sample: int, record_count: int, query: str, top_k: int, batch_size: int
) -> dict[str, object]:
    cpu_started = time.process_time_ns()
    wall_started = time.monotonic_ns()
    record_ids, prompt_digest, serialized_bytes, prompt, hit_details = run_pipeline(
        record_count, query, top_k, batch_size
    )
    return {
        "sample": sample,
        "elapsedNanos": time.monotonic_ns() - wall_started,
        "processCpuNanos": time.process_time_ns() - cpu_started,
        "processPeakRssKiB": peak_rss_kib(),
        "serializedBytes": serialized_bytes,
        "promptSha256": prompt_digest,
        "topRecordIds": record_ids,
        "topMatches": hit_details,
    }


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--record-count", type=int, required=True)
    parser.add_argument("--warmups", type=int, required=True)
    parser.add_argument("--samples", type=int, required=True)
    parser.add_argument("--batch-size", type=int, required=True)
    parser.add_argument("--query", required=True)
    parser.add_argument("--top-k", type=int, required=True)
    args = parser.parse_args()
    if not 1 <= args.record_count <= MAX_RECORDS:
        parser.error(f"--record-count must be between 1 and {MAX_RECORDS}")
    if not 1 <= args.warmups <= 10 or not 1 <= args.samples <= 10:
        parser.error("--warmups and --samples must be between 1 and 10")
    if not 1 <= args.batch_size <= 100_000:
        parser.error("--batch-size must be between 1 and 100000")
    if not 1 <= args.top_k <= min(100, args.record_count):
        parser.error("--top-k is outside the supported range")
    query_tokens = args.query.split(" ")
    if (
        len(query_tokens) != 3
        or not query_tokens[0].startswith("segment-")
        or not query_tokens[1].startswith("region-")
        or not query_tokens[2].startswith("product-")
    ):
        parser.error("--query must use segment-N region-N product-N synthetic fields")
    try:
        segment_id, region_id, product_id = (
            int(token.split("-", 1)[1]) for token in query_tokens
        )
    except ValueError:
        parser.error("--query must contain numeric synthetic field values")
    if not (0 <= segment_id < 31 and 0 <= region_id < 23 and 0 <= product_id < 101):
        parser.error("--query synthetic field values are outside the supported ranges")
    return args


def main() -> None:
    args = parse_args()
    for _ in range(args.warmups):
        run_pipeline(args.record_count, args.query, args.top_k, args.batch_size)

    samples = [
        measured_sample(
            index + 1,
            args.record_count,
            args.query,
            args.top_k,
            args.batch_size,
        )
        for index in range(args.samples)
    ]
    total_serialized = sum(int(sample["serializedBytes"]) for sample in samples)
    print(
        json.dumps(
            {
                "benchmark": "python-serialized-proxy",
                "recordCount": args.record_count,
                "warmupSamplesExcluded": args.warmups,
                "measuredSamples": args.samples,
                "serializationBatchSize": args.batch_size,
                "totalSerializedBytes": total_serialized,
                "samples": samples,
            },
            separators=(",", ":"),
        )
    )


if __name__ == "__main__":
