public final class GcpAttestationException extends RuntimeException {
    public GcpAttestationException(String message) {
        super(message);
    }

    public GcpAttestationException(String message, Throwable cause) {
        super(message, cause);
    }
}package org.opentron.backend.security.confidential.gateway.sdk;

import java.io.IOException;
import java.io.InputStream;
import java.math.BigInteger;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.security.KeyFactory;
import java.security.interfaces.RSAPublicKey;
import java.security.spec.RSAPublicKeySpec;
import java.time.Duration;
import java.time.Instant;
import java.util.Arrays;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

@FunctionalInterface
interface GcpAttestationSigningKeyResolver {
    RSAPublicKey resolve(String keyId);
}

final class GoogleGcpAttestationSigningKeyResolver
        implements GcpAttestationSigningKeyResolver {
    static final URI JWKS_URI = URI.create(
            "https://www.googleapis.com/service_accounts/v1/metadata/jwk/"
                    + "signer@confidentialspace-sign.iam.gserviceaccount.com");
    private static final int MAX_JWKS_BYTES = 256 * 1024;
    private static final int MAX_KEY_COUNT = 32;
    private static final Duration REQUEST_TIMEOUT = Duration.ofSeconds(4);
    private static final Duration KEY_CACHE_LIFETIME = Duration.ofMinutes(5);
    private static final Pattern KEY_ID = Pattern.compile("[A-Za-z0-9_-]{1,128}");

    private final HttpClient httpClient;
    private final ObjectMapper objectMapper;
    private final Map<String, CachedKey> keys = new HashMap<>();

    GoogleGcpAttestationSigningKeyResolver(ObjectMapper objectMapper) {
        this(HttpClient.newBuilder()
                        .connectTimeout(REQUEST_TIMEOUT)
                        .followRedirects(HttpClient.Redirect.NEVER)
                        .build(),
                objectMapper);
    }

    GoogleGcpAttestationSigningKeyResolver(
            HttpClient httpClient, ObjectMapper objectMapper) {
        this.httpClient = httpClient;
        this.objectMapper = objectMapper;
    }

    @Override
    public synchronized RSAPublicKey resolve(String keyId) {
        if (keyId == null || !KEY_ID.matcher(keyId).matches()) {
            throw new GcpAttestationException("GCA signing key identifier is invalid.");
        }
        CachedKey cached = keys.get(keyId);
        if (cached != null && cached.expiresAt().isAfter(Instant.now())) {
            return cached.key();
        }
        refreshKeys();
        CachedKey refreshed = keys.get(keyId);
        if (refreshed == null) {
            throw new GcpAttestationException(
                    "No matching key exists in Google's GCA signing JWKS.");
        }
        return refreshed.key();
    }

    private void refreshKeys() {
        HttpRequest request = HttpRequest.newBuilder(JWKS_URI)
                .timeout(REQUEST_TIMEOUT)
                .header("Accept", "application/json")
                .GET()
                .build();
        try {
            HttpResponse<InputStream> response = httpClient.send(
                    request, HttpResponse.BodyHandlers.ofInputStream());
            byte[] body;
            try (InputStream stream = response.body()) {
                body = readBounded(stream);
            }
            try {
                if (response.statusCode() != 200) {
                    throw new GcpAttestationException(
                            "Google GCA signing keys could not be retrieved.");
                }
                Map<String, CachedKey> updated = parseKeys(body);
                if (updated.isEmpty()) {
                    throw new GcpAttestationException(
                            "Google GCA signing JWKS contains no valid RSA signing keys.");
                }
                keys.clear();
                keys.putAll(updated);
            } finally {
                Arrays.fill(body, (byte) 0);
            }
        } catch (InterruptedException failure) {
            Thread.currentThread().interrupt();
            throw new GcpAttestationException(
                    "Google GCA signing key retrieval was interrupted.", failure);
        } catch (IOException failure) {
            throw new GcpAttestationException(
                    "Google GCA signing keys could not be retrieved.", failure);
        }
    }

    private Map<String, CachedKey> parseKeys(byte[] body) {
        try (JsonParser parser = objectMapper.getFactory().createParser(body)) {
            parser.enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);
            JsonNode root = objectMapper.readTree(parser);
            if (root == null || !root.isObject() || parser.nextToken() != null
                    || !root.path("keys").isArray()
                    || root.path("keys").isEmpty()
                    || root.path("keys").size() > MAX_KEY_COUNT) {
                throw new GcpAttestationException("Google GCA signing JWKS is malformed.");
            }
            Map<String, CachedKey> updated = new HashMap<>();
            for (JsonNode entry : root.path("keys")) {
                String kid = text(entry, "kid");
                if (kid == null || !KEY_ID.matcher(kid).matches()) {
                    continue;
                }
                if (updated.containsKey(kid)) {
                    throw new GcpAttestationException(
                            "Google GCA signing JWKS contains duplicate key identifiers.");
                }
                if (!"RSA".equals(text(entry, "kty"))
                        || !"RS256".equals(text(entry, "alg"))
                        || (text(entry, "use") != null
                                && !"sig".equals(text(entry, "use")))) {
                    continue;
                }
                BigInteger modulus = unsignedBase64Url(text(entry, "n"));
                BigInteger exponent = unsignedBase64Url(text(entry, "e"));
                if (modulus.bitLength() < 2048 || modulus.bitLength() > 8192
                        || exponent.compareTo(BigInteger.valueOf(3)) < 0
                        || !exponent.testBit(0)) {
                    throw new GcpAttestationException(
                            "Google GCA RSA signing key parameters are invalid.");
                }
                RSAPublicKey publicKey = (RSAPublicKey) KeyFactory.getInstance("RSA")
                        .generatePublic(new RSAPublicKeySpec(modulus, exponent));
                updated.put(kid,
                        new CachedKey(publicKey, Instant.now().plus(KEY_CACHE_LIFETIME)));
            }
            return updated;
        } catch (GcpAttestationException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new GcpAttestationException(
                    "Google GCA signing JWKS is malformed.", failure);
        }
    }

    private static byte[] readBounded(InputStream stream) throws IOException {
        byte[] response = stream.readNBytes(MAX_JWKS_BYTES + 1);
        if (response.length > MAX_JWKS_BYTES || stream.read() != -1) {
            Arrays.fill(response, (byte) 0);
            throw new GcpAttestationException("Google GCA signing JWKS is oversized.");
        }
        return response;
    }

    private static BigInteger unsignedBase64Url(String value) {
        if (value == null || value.isBlank()) {
            throw new GcpAttestationException("Google GCA RSA signing key is malformed.");
        }
        return new BigInteger(1, Base64.getUrlDecoder().decode(value));
    }

    private static String text(JsonNode node, String name) {
        JsonNode value = node.get(name);
        return value != null && value.isTextual() ? value.textValue() : null;
    }

    private record CachedKey(RSAPublicKey key, Instant expiresAt) {
    }
}package org.opentron.backend.security.confidential.gateway.sdk;

import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.Signature;
import java.security.interfaces.RSAPublicKey;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Base64;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

final class GcpAttestationTokenVerifier {
    private static final String GOOGLE_ISSUER =
            "https://confidentialcomputing.googleapis.com";
    private static final String EAT_PROFILE =
            "https://cloud.google.com/confidential-computing/confidential-vm/docs/token-claims";
    private static final Duration CLOCK_SKEW = Duration.ofSeconds(30);
    private static final Duration MAX_TOKEN_LIFETIME = Duration.ofHours(2);
    private static final Duration MAX_TOKEN_AGE = Duration.ofMinutes(10);
    private static final int MAX_TOKEN_BYTES = 64 * 1024;
    private static final Pattern KEY_ID = Pattern.compile("[A-Za-z0-9_-]{1,128}");
    private static final Set<String> EXPECTED_ENV_OVERRIDES = Set.of(
            "CJAE_RUNTIME_CONFIG_BASE64",
            "CJAE_RUNTIME_CONFIG_SIGNATURE_BASE64");

    private final GcpAttestationSigningKeyResolver keyResolver;
    private final ObjectMapper objectMapper;
    private final Clock clock;

    GcpAttestationTokenVerifier(
            GcpAttestationSigningKeyResolver keyResolver,
            ObjectMapper objectMapper,
            Clock clock) {
        this.keyResolver = keyResolver;
        this.objectMapper = objectMapper;
        this.clock = clock;
    }

    VerifiedGcpAttestation verify(
            String compactToken, String expectedChallenge, GcpConfidentialSpacePolicy policy) {
        if (compactToken == null
                || compactToken.getBytes(StandardCharsets.US_ASCII).length > MAX_TOKEN_BYTES) {
            reject("GCA attestation token is missing or oversized.");
        }
        validateChallenge(expectedChallenge);
        String[] parts = compactToken.split("\\.", -1);
        if (parts.length != 3 || parts[0].isEmpty() || parts[1].isEmpty()
                || parts[2].isEmpty()) {
            reject("GCA attestation token is not a compact JWT.");
        }

        try {
            JsonNode header = parseObject(parts[0]);
            validateHeader(header);
            RSAPublicKey key = keyResolver.resolve(header.path("kid").textValue());
            verifySignature(parts, key);

            JsonNode claims = parseObject(parts[1]);
            validateClaims(claims, expectedChallenge, policy);
            return new VerifiedGcpAttestation(
                    Instant.ofEpochSecond(requiredLong(claims, "exp")),
                    claims.path("sub").textValue(),
                    claims.path("submods").path("container")
                            .path("image_digest").textValue());
        } catch (GcpAttestationException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new GcpAttestationException(
                    "GCA attestation token signature or claims are invalid.", failure);
        }
    }

    private JsonNode parseObject(String encodedSegment) throws Exception {
        byte[] bytes = Base64.getUrlDecoder().decode(encodedSegment);
        try (JsonParser parser = objectMapper.getFactory().createParser(bytes)) {
            parser.enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);
            JsonNode result = objectMapper.readTree(parser);
            if (result == null || !result.isObject() || parser.nextToken() != null) {
                reject("GCA JWT segments must contain one JSON object.");
            }
            return result;
        } finally {
            java.util.Arrays.fill(bytes, (byte) 0);
        }
    }

    private static void validateHeader(JsonNode header) {
        if (!"RS256".equals(text(header, "alg"))) {
            reject("GCA JWT algorithm is not the pinned RS256 algorithm.");
        }
        String keyId = text(header, "kid");
        if (keyId == null || !KEY_ID.matcher(keyId).matches()) {
            reject("GCA JWT key identifier is invalid.");
        }
        var fields = header.fieldNames();
        while (fields.hasNext()) {
            String name = fields.next();
            if (!Set.of("alg", "kid", "typ").contains(name)) {
                reject("GCA JWT contains unsupported JOSE header parameters.");
            }
        }
    }

    private void validateClaims(
            JsonNode claims, String expectedChallenge, GcpConfidentialSpacePolicy policy) {
        if (!GOOGLE_ISSUER.equals(text(claims, "iss"))
                || !EAT_PROFILE.equals(text(claims, "eat_profile"))
                || !audienceMatches(claims.path("aud"), policy.audience())
                || !policy.hardwareModel().equals(text(claims, "hwmodel"))
                || !Boolean.TRUE.equals(claims.path("secboot").booleanValue())
                || !"CONFIDENTIAL_SPACE".equals(text(claims, "swname"))
                || !"disabled-since-boot".equals(text(claims, "dbgstat"))
                || !policy.expectedSubject().equals(text(claims, "sub"))) {
            reject("GCA evidence does not satisfy the configured Confidential Space policy.");
        }
        validateLaunchPolicyClaims(claims);
        validateTimes(claims);
        validateNonce(claims.path("eat_nonce"), expectedChallenge);
        validateWorkload(claims.path("submods"), policy.expectedImageDigest());
        validateComputeSubject(claims.path("submods").path("gce"), policy);
    }

    private static void validateLaunchPolicyClaims(JsonNode claims) {
        JsonNode supportAttributes = claims.path("support_attributes");
        boolean stable = false;
        if (supportAttributes.isArray()) {
            for (JsonNode attribute : supportAttributes) {
                stable |= attribute.isTextual() && "STABLE".equals(attribute.textValue());
            }
        }
        if (!stable) {
            reject("GCA evidence does not assert the STABLE support attribute.");
        }
        validateEnvironmentOverrides(overrideClaim(claims, "env_override"));
        JsonNode commandOverride = overrideClaim(claims, "cmd_override");
        if (!commandOverride.isMissingNode() && !commandOverride.isNull()
                && !(commandOverride.isBoolean() && !commandOverride.booleanValue())
                && !(commandOverride.isArray() && commandOverride.isEmpty())
                && !(commandOverride.isTextual() && commandOverride.textValue().isEmpty())) {
            reject("GCA evidence allows an unexpected command override.");
        }
    }

    private static JsonNode overrideClaim(JsonNode claims, String name) {
        JsonNode topLevel = claims.get(name);
        JsonNode container = claims.path("submods").path("container").get(name);
        if (topLevel != null && container != null && !topLevel.equals(container)) {
            reject("GCA evidence contains conflicting " + name + " claims.");
        }
        if (topLevel != null) {
            return topLevel;
        }
        return container == null ? com.fasterxml.jackson.databind.node.MissingNode.getInstance()
                : container;
    }

    private static void validateEnvironmentOverrides(JsonNode claim) {
        if (claim.isMissingNode() || claim.isNull()) {
            return;
        }
        Set<String> values = new HashSet<>();
        if (claim.isTextual()) {
            for (String value : claim.textValue().split(",", -1)) {
                if (value.isBlank() || !values.add(value)) {
                    reject("GCA evidence contains an invalid environment override claim.");
                }
            }
        } else if (claim.isArray()) {
            for (JsonNode value : claim) {
                if (!value.isTextual() || value.textValue().isBlank()
                        || !values.add(value.textValue())) {
                    reject("GCA evidence contains an invalid environment override claim.");
                }
            }
        } else {
            reject("GCA evidence contains an invalid environment override claim.");
        }
        if (!EXPECTED_ENV_OVERRIDES.equals(values)) {
            reject("GCA evidence allows unexpected environment overrides.");
        }
    }

    private void validateTimes(JsonNode claims) {
        long issuedAtSeconds = requiredLong(claims, "iat");
        long expiresAtSeconds = requiredLong(claims, "exp");
        long notBeforeSeconds = requiredLong(claims, "nbf");
        Instant now = clock.instant();
        Instant issuedAt = Instant.ofEpochSecond(issuedAtSeconds);
        Instant expiresAt = Instant.ofEpochSecond(expiresAtSeconds);
        Instant notBefore = Instant.ofEpochSecond(notBeforeSeconds);
        if (issuedAt.isAfter(now.plus(CLOCK_SKEW))
                || issuedAt.isBefore(now.minus(MAX_TOKEN_AGE))
                || !expiresAt.isAfter(now.minus(CLOCK_SKEW))
                || !notBefore.isBefore(now.plus(CLOCK_SKEW))
                || !expiresAt.isAfter(issuedAt)
                || Duration.between(issuedAt, expiresAt).compareTo(MAX_TOKEN_LIFETIME) > 0) {
            reject("GCA attestation token is stale or has invalid validity times.");
        }
    }

    private static void validateNonce(JsonNode claim, String expectedChallenge) {
        if (claim.isTextual()) {
            if (!expectedChallenge.equals(claim.textValue())) {
                reject("GCA attestation nonce does not match the client challenge.");
            }
            return;
        }
        if (!claim.isArray() || claim.isEmpty() || claim.size() > 6) {
            reject("GCA attestation nonce claim is invalid.");
        }
        Set<String> seen = new HashSet<>();
        boolean matched = false;
        for (JsonNode nonce : claim) {
            if (!nonce.isTextual() || nonce.textValue().isBlank()
                    || nonce.textValue().getBytes(StandardCharsets.UTF_8).length > 88
                    || !seen.add(nonce.textValue())) {
                reject("GCA attestation nonce claim is invalid.");
            }
            matched |= expectedChallenge.equals(nonce.textValue());
        }
        if (!matched) {
            reject("GCA attestation nonce does not match the client challenge.");
        }
    }

    private static void validateWorkload(JsonNode submods, String expectedImageDigest) {
        if (!submods.isObject()
                || !expectedImageDigest.equals(
                        text(submods.path("container"), "image_digest"))) {
            reject("GCA workload image digest does not match the pinned image.");
        }
    }

    private static void validateComputeSubject(
            JsonNode gce, GcpConfidentialSpacePolicy policy) {
        if (!gce.isObject()) {
            reject("GCA evidence does not include Compute Engine identity claims.");
        }
        String project;
        String instance;
        String subject;
        String zone = text(gce, "zone");
        if ("GCP_AMD_SEV".equals(policy.hardwareModel())) {
            project = text(gce, "project_id");
            instance = text(gce, "instance_name");
            subject = "https://www.googleapis.com/compute/v1/projects/"
                    + project + "/zones/" + zone + "/instances/" + instance;
        } else {
            project = text(gce, "project_number");
            instance = text(gce, "instance_id");
            subject = "//compute.googleapis.com/projects/"
                    + project + "/zones/" + zone + "/instances/" + instance;
        }
        if (isBlank(project) || isBlank(instance) || isBlank(zone)
                || !policy.expectedSubject().equals(subject)) {
            reject("GCA Compute Engine identity does not match the configured VM.");
        }
    }

    private static boolean audienceMatches(JsonNode audience, String expected) {
        if (audience.isTextual()) {
            return expected.equals(audience.textValue());
        }
        if (audience.isArray()) {
            for (JsonNode value : audience) {
                if (value.isTextual() && expected.equals(value.textValue())) {
                    return true;
                }
            }
        }
        return false;
    }

    private static long requiredLong(JsonNode claims, String name) {
        JsonNode value = claims.get(name);
        if (value == null || !value.isIntegralNumber() || !value.canConvertToLong()) {
            reject("GCA attestation token is missing a valid " + name + " claim.");
        }
        return value.longValue();
    }

    private static String text(JsonNode object, String name) {
        JsonNode value = object.get(name);
        return value != null && value.isTextual() ? value.textValue() : null;
    }

    private static void validateChallenge(String challenge) {
        if (challenge == null || !challenge.matches("[A-Za-z0-9_-]{43}")) {
            reject("Client GCA challenge must be a canonical 256-bit base64url nonce.");
        }
        byte[] decoded;
        try {
            decoded = Base64.getUrlDecoder().decode(challenge);
        } catch (IllegalArgumentException failure) {
            reject("Client GCA challenge is malformed.");
            return;
        }
        try {
            if (decoded.length != 32
                    || !Base64.getUrlEncoder().withoutPadding()
                            .encodeToString(decoded).equals(challenge)) {
                reject("Client GCA challenge must be a canonical 256-bit base64url nonce.");
            }
        } finally {
            java.util.Arrays.fill(decoded, (byte) 0);
        }
    }

    private static void verifySignature(String[] parts, RSAPublicKey key) throws Exception {
        Signature signature = Signature.getInstance("SHA256withRSA");
        signature.initVerify(key);
        signature.update((parts[0] + "." + parts[1]).getBytes(StandardCharsets.US_ASCII));
        if (!signature.verify(Base64.getUrlDecoder().decode(parts[2]))) {
            reject("GCA attestation token signature is invalid.");
        }
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }

    private static void reject(String message) {
        throw new GcpAttestationException(message);
    }

    record VerifiedGcpAttestation(Instant expiresAt, String subject, String imageDigest) {
    }
}package org.opentron.backend.security.confidential.gateway.sdk;

import java.util.Objects;

public record GcpConfidentialSpacePolicy(
        String audience,
        String expectedSubject,
        String hardwareModel,
        String expectedImageDigest) {
    public GcpConfidentialSpacePolicy {
        if (audience == null || audience.isBlank() || audience.length() > 512
                || expectedSubject == null || expectedSubject.isBlank()
                || expectedSubject.length() > 1024
                || !expectedSubject.startsWith(
                        "https://www.googleapis.com/compute/v1/projects/")
                        && !expectedSubject.startsWith(
                                "//compute.googleapis.com/projects/")) {
            throw new IllegalArgumentException(
                    "Confidential Space audience and exact VM subject are required.");
        }
        if (!Objects.equals(hardwareModel, "GCP_AMD_SEV")
                && !Objects.equals(hardwareModel, "GCP_INTEL_TDX")) {
            throw new IllegalArgumentException(
                    "Confidential Space hardware model must be GCP_AMD_SEV or GCP_INTEL_TDX.");
        }
        if (expectedImageDigest == null
                || !expectedImageDigest.matches("sha256:[A-Fa-f0-9]{64}")) {
            throw new IllegalArgumentException(
                    "Confidential Space image digest must be a pinned SHA-256 digest.");
        }
    }
}package org.opentron.backend.security.confidential.gateway.sdk;

/** Model adapter that receives sanitized prompt text only. */
@FunctionalInterface
public interface SanitizedModelClient {
    String complete(String sanitizedPrompt);
}package org.opentron.backend.security.confidential.gateway.sdk;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.atomic.AtomicReference;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.sun.net.httpserver.HttpServer;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/** HTTP contract tests for the standalone Gateway client artifact. */
class ConfidentialGatewayClientTest {
    private static final String TOKEN = "0123456789abcdef0123456789abcdef";

    @Test
    void clientAttestationRefusesPlainHttpEndpoints() throws Exception {
        HttpServer server = startServer(exchange -> respond(exchange, 200, "{}"));
        try {
            assertThrows(
                    IllegalStateException.class,
                    () -> client(server).attestGcpRuntime());
        } finally {
            server.stop(0);
        }
    }

    @Test
    void clientAttestationRequiresAnExplicitConfidentialSpacePolicy() {
        var client = new ConfidentialGatewayClient(
                URI.create("https://gateway.example.test"),
                TOKEN,
                HttpClient.newHttpClient(),
                new ObjectMapper(),
                Duration.ofSeconds(1));

        assertThrows(IllegalStateException.class, client::attestGcpRuntime);
    }

    @Test
    void sanitizeAndDesanitizeUseTypedAuthenticatedRequests() throws Exception {
        AtomicReference<String> authorization = new AtomicReference<>();
        AtomicReference<String> sanitizePayload = new AtomicReference<>();
        HttpServer server = startServer(exchange -> {
            authorization.set(exchange.getRequestHeaders().getFirst("Authorization"));
            String path = exchange.getRequestURI().getPath();
            if ("/v1/confidential/sanitize".equals(path)) {
                sanitizePayload.set(new String(
                        exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
                respond(exchange, 200, """
                        {"sanitizedText":"Contact <OJE_EMAIL_token>","secureContext":"v1.key.AA.BB","detectorVersion":"test","expiresAt":"2026-01-01T00:10:00Z"}
                        """);
            } else {
                respond(exchange, 200, "{\"desanitizedText\":\"Contact ada@example.com\"}");
            }
        });

        try {
            ConfidentialGatewayClient client = client(server);
            var sanitized = client.sanitize("Contact ada@example.com");

            assertEquals("Contact <OJE_EMAIL_token>", sanitized.sanitizedText());
            assertEquals("test", sanitized.detectorVersion());
            assertEquals("2026-01-01T00:10:00Z", sanitized.expiresAt().toString());
            assertEquals("Bearer " + TOKEN, authorization.get());
            assertTrue(sanitizePayload.get().contains("Contact ada@example.com"));

            assertEquals("Contact ada@example.com",
                    client.desanitize(sanitized.sanitizedText(), sanitized.secureContext()));
            assertEquals("Bearer " + TOKEN, authorization.get());
        } finally {
            server.stop(0);
        }
    }

    @Test
    void exposesSafeTypedErrorWithoutServerMessage() throws Exception {
        HttpServer server = startServer(exchange -> respond(
                exchange, 400,
                "{\"code\":\"INVALID_CONTEXT\",\"message\":\"raw sensitive server detail\"}"));

        try {
            GatewayClientException exception = assertThrows(
                    GatewayClientException.class,
                    () -> client(server).desanitize("response", "v1.key.AA.BB"));

            assertEquals(400, exception.statusCode());
            assertEquals("INVALID_CONTEXT", exception.errorCode());
            assertFalse(exception.getMessage().contains("raw sensitive server detail"));
        } finally {
            server.stop(0);
        }
    }

    @Test
    void completionCompositionSendsOnlySanitizedPromptToModel() throws Exception {
        HttpServer server = startServer(exchange -> {
            if ("/v1/confidential/sanitize".equals(exchange.getRequestURI().getPath())) {
                respond(exchange, 200, """
                        {"sanitizedText":"Write to <OJE_EMAIL_token>","secureContext":"v1.key.AA.BB","detectorVersion":"test","expiresAt":"2026-01-01T00:10:00Z"}
                        """);
            } else {
                respond(exchange, 200, "{\"desanitizedText\":\"Sent to ada@example.com\"}");
            }
        });

        try {
            AtomicReference<String> modelInput = new AtomicReference<>();
            var completion = new ConfidentialCompletionClient(
                    client(server),
                    prompt -> {
                        modelInput.set(prompt);
                        return "Sent to <OJE_EMAIL_token>";
                    });

            assertEquals("Sent to ada@example.com",
                    completion.complete("Write to ada@example.com"));
            assertEquals("Write to <OJE_EMAIL_token>", modelInput.get());
            assertFalse(modelInput.get().contains("ada@example.com"));
        } finally {
            server.stop(0);
        }
    }

    @Test
    void batchClientSanitizesAndRestoresSegmentsUsingOneContext() throws Exception {
        HttpServer server = startServer(exchange -> {
            if ("/v1/confidential/sanitize/batch".equals(exchange.getRequestURI().getPath())) {
                respond(exchange, 200, """
                        {"sanitizedSegments":["Email <OJE_EMAIL_a>","Phone <OJE_PHONE_NUMBER_b>"],"secureContext":"v1.key.AA.BB","detectorVersion":"test","expiresAt":"2026-01-01T00:10:00Z"}
                        """);
            } else {
                respond(exchange, 200,
                        "{\"desanitizedResponses\":[\"Email ada@example.com\",\"Phone 212-555-0199\"]}");
            }
        });

        try {
            var client = client(server);
            var sanitized = client.sanitizeSegments(
                    List.of("Email ada@example.com", "Phone 212-555-0199"));

            assertEquals(2, sanitized.sanitizedSegments().size());
            assertFalse(sanitized.sanitizedSegments().get(0).contains("ada@example.com"));
            assertEquals(
                    List.of("Email ada@example.com", "Phone 212-555-0199"),
                    client.desanitizeSegments(sanitized.sanitizedSegments(), sanitized.secureContext()));
        } finally {
            server.stop(0);
        }
    }

    @Test
    void conversationCompositionSanitizesEveryRoleBeforeModelAndRestoresResponse() throws Exception {
        AtomicReference<String> sanitizePayload = new AtomicReference<>();
        HttpServer server = startServer(exchange -> {
            String path = exchange.getRequestURI().getPath();
            if ("/v1/confidential/sanitize/batch".equals(path)) {
                sanitizePayload.set(new String(
                        exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
                respond(exchange, 200, """
                        {"sanitizedSegments":["Remember <OJE_EMAIL_a>","Write to <OJE_EMAIL_a>"],"secureContext":"v1.key.AA.BB","detectorVersion":"test","expiresAt":"2026-01-01T00:10:00Z"}
                        """);
            } else {
                respond(exchange, 200,
                        "{\"desanitizedResponses\":[\"Sent to ada@example.com\"]}");
            }
        });

        try {
            AtomicReference<List<ConfidentialConversationClient.Message>> modelInput =
                    new AtomicReference<>();
            var conversationClient = new ConfidentialConversationClient(client(server));
            List<ConfidentialConversationClient.Message> response = conversationClient.complete(
                    List.of(
                            new ConfidentialConversationClient.Message(
                                    "assistant", "Remember ada@example.com"),
                            new ConfidentialConversationClient.Message(
                                    "user", "Write to ada@example.com")),
                    messages -> {
                        modelInput.set(messages);
                        return List.of(new ConfidentialConversationClient.Message(
                                "assistant", "Sent to <OJE_EMAIL_a>"));
                    });

            assertTrue(sanitizePayload.get().contains("ada@example.com"));
            assertEquals(List.of("Remember <OJE_EMAIL_a>", "Write to <OJE_EMAIL_a>"),
                    modelInput.get().stream()
                            .map(ConfidentialConversationClient.Message::content)
                            .toList());
            assertFalse(modelInput.get().toString().contains("ada@example.com"));
            assertEquals(
                    List.of(new ConfidentialConversationClient.Message(
                            "assistant", "Sent to ada@example.com")),
                    response);
        } finally {
            server.stop(0);
        }
    }

    @Test
    void requiresHttpsOutsideLoopback() {
        assertThrows(IllegalArgumentException.class, () -> new ConfidentialGatewayClient(
                URI.create("http://gateway.example.com"),
                TOKEN,
                HttpClient.newHttpClient(),
                new ObjectMapper(),
                Duration.ofSeconds(5)));
    }

    @Test
    void rejectsWeakCredentialsAndTimeouts() {
        assertThrows(IllegalArgumentException.class, () -> new ConfidentialGatewayClient(
                URI.create("http://localhost:8000"),
                "short",
                HttpClient.newHttpClient(),
                new ObjectMapper(),
                Duration.ofSeconds(5)));
        assertThrows(IllegalArgumentException.class, () -> new ConfidentialGatewayClient(
                URI.create("http://localhost:8000"),
                TOKEN,
                HttpClient.newHttpClient(),
                new ObjectMapper(),
                Duration.ZERO));
    }

    @ParameterizedTest
    @ValueSource(strings = {
        "weather", "recipe", "gardening", "travel itinerary", "book review",
        "public schedule", "meeting agenda", "product description",
        "general knowledge", "tutorial", "arithmetic", "sports score",
        "movie summary", "language translation", "documentation",
        "public announcement", "restaurant menu", "historical fact",
        "packing list", "code example"
    })
    void sendsApprovedKeywordExamplesToGateway(String keyword) throws Exception {
        HttpServer server = keywordPolicyServer();
        try {
            var result = client(server).sanitize("Please help with " + keyword + ".");
            assertEquals("approved", result.sanitizedText());
        } finally {
            server.stop(0);
        }
    }

    @ParameterizedTest
    @ValueSource(strings = {
        "password", "passcode", "secret key", "api key", "access token",
        "private key", "social security number", "ssn", "credit card",
        "bank account", "medical record", "diagnosis", "patient",
        "date of birth", "passport number", "driver license",
        "insurance policy", "biometric", "confidential", "restricted"
    })
    void returnsTypedRejectionForGatewayRejectedKeywordExamples(String keyword) throws Exception {
        HttpServer server = keywordPolicyServer();
        try {
            GatewayClientException exception = assertThrows(
                    GatewayClientException.class,
                    () -> client(server).sanitize("Please process " + keyword + "."));

            assertEquals(422, exception.statusCode());
            assertEquals("POLICY_REJECTED", exception.errorCode());
        } finally {
            server.stop(0);
        }
    }

    private static HttpServer keywordPolicyServer() throws IOException {
        List<String> rejectedKeywords = List.of(
                "password", "passcode", "secret key", "api key", "access token",
                "private key", "social security number", "ssn", "credit card",
                "bank account", "medical record", "diagnosis", "patient",
                "date of birth", "passport number", "driver license",
                "insurance policy", "biometric", "confidential", "restricted");
        ObjectMapper mapper = new ObjectMapper();
        return startServer(exchange -> {
            String requestBody = new String(
                    exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
            String text = mapper.readTree(requestBody).path("text").asText();
            boolean rejected = rejectedKeywords.stream()
                    .anyMatch(keyword -> text.toLowerCase(Locale.ROOT).contains(keyword));
            if (rejected) {
                respond(exchange, 422,
                        "{\"code\":\"POLICY_REJECTED\",\"message\":\"fixture policy match\"}");
            } else {
                respond(exchange, 200, """
                        {"sanitizedText":"approved","secureContext":"v1.key.AA.BB","detectorVersion":"test","expiresAt":"2026-01-01T00:10:00Z"}
                        """);
            }
        });
    }

    private static ConfidentialGatewayClient client(HttpServer server) {
        return new ConfidentialGatewayClient(
                URI.create("http://127.0.0.1:" + server.getAddress().getPort()),
                TOKEN,
                HttpClient.newHttpClient(),
                new ObjectMapper(),
                Duration.ofSeconds(5));
    }

    private static HttpServer startServer(
            com.sun.net.httpserver.HttpHandler handler) throws IOException {
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        server.createContext("/", handler);
        server.start();
        return server;
    }

    private static void respond(
            com.sun.net.httpserver.HttpExchange exchange,
            int status,
            String body) throws IOException {
        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
        exchange.getResponseHeaders().add("Content-Type", "application/json");
        exchange.sendResponseHeaders(status, bytes.length);
        try (var output = exchange.getResponseBody()) {
            output.write(bytes);
        }
    }
}package org.opentron.backend.security.confidential.gateway.sdk;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.charset.StandardCharsets;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.Signature;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Base64;
import java.util.List;
import java.util.Map;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class GcpAttestationTokenVerifierTest {
    private static final Instant NOW = Instant.parse("2026-10-26T10:00:00Z");
    private static final String CHALLENGE =
            Base64.getUrlEncoder().withoutPadding().encodeToString(new byte[32]);
    private static final String IMAGE_DIGEST = "sha256:" + "a".repeat(64);
    private static final String SUBJECT =
            "https://www.googleapis.com/compute/v1/projects/cjae-prod/"
                    + "zones/us-central1-a/instances/cjae-gateway";

    private KeyPair keyPair;
    private ObjectMapper objectMapper;
    private GcpAttestationTokenVerifier verifier;
    private GcpConfidentialSpacePolicy policy;

    @BeforeEach
    void setUp() throws Exception {
        KeyPairGenerator generator = KeyPairGenerator.getInstance("RSA");
        generator.initialize(2048);
        keyPair = generator.generateKeyPair();
        objectMapper = new ObjectMapper();
        verifier = new GcpAttestationTokenVerifier(
                keyId -> {
                    assertEquals("gca-key", keyId);
                    return (java.security.interfaces.RSAPublicKey) keyPair.getPublic();
                },
                objectMapper,
                Clock.fixed(NOW, ZoneOffset.UTC));
        policy = new GcpConfidentialSpacePolicy(
                "https://sts.googleapis.com",
                SUBJECT,
                "GCP_AMD_SEV",
                IMAGE_DIGEST);
    }

    @Test
    void verifiesSignatureNonceFreshnessVmAndConfidentialSpaceImageClaims() throws Exception {
        var verified = verifier.verify(signedToken(CHALLENGE, IMAGE_DIGEST), CHALLENGE, policy);

        assertEquals(SUBJECT, verified.subject());
        assertEquals(IMAGE_DIGEST, verified.imageDigest());
        assertEquals(NOW.plusSeconds(300), verified.expiresAt());
    }

    @Test
    void rejectsBadSignatureNonceAndImageDigest() throws Exception {
        String signed = signedToken(CHALLENGE, IMAGE_DIGEST);
        int signatureOffset = signed.lastIndexOf('.') + 1;
        String tampered = signed.substring(0, signatureOffset)
                + (signed.charAt(signatureOffset) == 'A' ? 'B' : 'A')
                + signed.substring(signatureOffset + 1);
        assertThrows(GcpAttestationException.class,
                () -> verifier.verify(tampered, CHALLENGE, policy));
        assertThrows(GcpAttestationException.class,
                () -> verifier.verify(signed, Base64.getUrlEncoder().withoutPadding()
                        .encodeToString(new byte[31]), policy));
        assertThrows(GcpAttestationException.class,
                () -> verifier.verify(
                        signed,
                        CHALLENGE,
                        new GcpConfidentialSpacePolicy(
                                policy.audience(),
                                SUBJECT,
                                policy.hardwareModel(),
                                "sha256:" + "b".repeat(64))));
    }

    @Test
    void rejectsVmIdentityAndDebugImages() throws Exception {
        String wrongIdentity = signedToken(CHALLENGE, IMAGE_DIGEST, "other-instance", false);
        String debugImage = signedToken(CHALLENGE, IMAGE_DIGEST, "cjae-gateway", true);

        assertThrows(GcpAttestationException.class,
                () -> verifier.verify(wrongIdentity, CHALLENGE, policy));
        assertThrows(GcpAttestationException.class,
                () -> verifier.verify(debugImage, CHALLENGE, policy));
    }

    @Test
    void requiresStableSupportAndRejectsUnexpectedOverrides() throws Exception {
        String expectedEnvironmentOverride = signedToken(CHALLENGE, IMAGE_DIGEST,
                "cjae-gateway", false, List.of("STABLE"),
                List.of("CJAE_RUNTIME_CONFIG_BASE64",
                        "CJAE_RUNTIME_CONFIG_SIGNATURE_BASE64"), null);
        String missingStable = signedToken(CHALLENGE, IMAGE_DIGEST, "cjae-gateway",
                false, List.of(), null, null);
        String wrongEnvironmentOverride = signedToken(CHALLENGE, IMAGE_DIGEST, "cjae-gateway",
                false, List.of("STABLE"), List.of("GATEWAY_OIDC_ISSUER"), null);
        String commandOverride = signedToken(CHALLENGE, IMAGE_DIGEST, "cjae-gateway",
                false, List.of("STABLE"), null, List.of("--spring.profiles.active=local"));

        assertEquals(SUBJECT, verifier.verify(
                expectedEnvironmentOverride, CHALLENGE, policy).subject());
        assertThrows(GcpAttestationException.class,
                () -> verifier.verify(missingStable, CHALLENGE, policy));
        assertThrows(GcpAttestationException.class,
                () -> verifier.verify(wrongEnvironmentOverride, CHALLENGE, policy));
        assertThrows(GcpAttestationException.class,
                () -> verifier.verify(commandOverride, CHALLENGE, policy));
    }

    private String signedToken(String nonce, String imageDigest) throws Exception {
        return signedToken(nonce, imageDigest, "cjae-gateway", false);
    }

    private String signedToken(
            String nonce, String imageDigest, String instanceName, boolean debug) throws Exception {
        return signedToken(nonce, imageDigest, instanceName, debug,
                List.of("STABLE"), null, null);
    }

    private String signedToken(
            String nonce,
            String imageDigest,
            String instanceName,
            boolean debug,
            List<String> supportAttributes,
            Object environmentOverride,
            Object commandOverride) throws Exception {
        String header = base64(objectMapper.writeValueAsBytes(
                Map.of("alg", "RS256", "kid", "gca-key")));
        Map<String, Object> claims = new java.util.LinkedHashMap<>(Map.ofEntries(
                Map.entry("iss", "https://confidentialcomputing.googleapis.com"),
                Map.entry("sub", SUBJECT),
                Map.entry("aud", List.of("https://sts.googleapis.com")),
                Map.entry("iat", NOW.getEpochSecond()),
                Map.entry("exp", NOW.plusSeconds(300).getEpochSecond()),
                Map.entry("nbf", NOW.minusSeconds(1).getEpochSecond()),
                Map.entry("eat_nonce", List.of("provider-nonce", nonce)),
                Map.entry("eat_profile", "https://cloud.google.com/confidential-computing/"
                        + "confidential-vm/docs/token-claims"),
                Map.entry("hwmodel", "GCP_AMD_SEV"),
                Map.entry("secboot", true),
                Map.entry("support_attributes", supportAttributes),
                Map.entry("swname", "CONFIDENTIAL_SPACE"),
                Map.entry("dbgstat", debug ? "enabled" : "disabled-since-boot"),
                Map.entry("submods", Map.of(
                        "gce", Map.of(
                                "project_id", "cjae-prod",
                                "zone", "us-central1-a",
                                "instance_name", instanceName),
                        "container", Map.of("image_digest", imageDigest)))));
        if (environmentOverride != null) {
            claims.put("env_override", environmentOverride);
        }
        if (commandOverride != null) {
            claims.put("cmd_override", commandOverride);
        }
        String payload = base64(objectMapper.writeValueAsBytes(claims));
        String signingInput = header + "." + payload;
        Signature signer = Signature.getInstance("SHA256withRSA");
        signer.initSign(keyPair.getPrivate());
        signer.update(signingInput.getBytes(StandardCharsets.US_ASCII));
        return signingInput + "." + base64(signer.sign());
    }

    private static String base64(byte[] value) {
        return Base64.getUrlEncoder().withoutPadding().encodeToString(value);
    }
